        public void initializeCurrencies()
        {
            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var CoreOption = dbConn.QueryFirstOrDefault<CORE_OPTION>("SELECT * FROM CORE_OPTION WHERE COMPANY_ID = " + m_company_id);
                if (CoreOption != null)
                {
                    this.m_baseCurId = (int)CoreOption.base_cur_id;
                    this.m_counterCurId = (int)CoreOption.counter_cur_id;

                    this.m_decimalPlaces = (int)CoreOption.decimal_places; //AN 2025-08-27
                    this.m_baseCurDescimalPlaces = (int)CoreOption.base_cur_decimal_places;//AN 2025-08-27
                }
            }
        }

        #region profile

        public Array[] ValidateProfileRules()
        {
            Array[] result = new Array[2];

            this.m_ListProfileAction.Clear();
            this.m_ListAuthorityRequest.Clear();

            List<CORE_RULE> listRules = new List<CORE_RULE>();
            List<CORE_RULE_ACTION> listRuleActions = new List<CORE_RULE_ACTION>();

            bool blErrorOccurred = false;
            string blErrorMsg = "";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                // if (this.m_ListRule == null || this.m_ListRule.Count == 0)
                // {
                var szSql = "";
                var szSqlActions = "";

                szSql =
                     " SELECT " +
                     " CORE_RULE.*  " +
                     " FROM CORE_RULE " +
                     " WHERE RULE_SCOPE = " + (int)Enums.RuleScope.Profile +
                     " AND (CORE_RULE.IS_INACTIVE = 0 OR (CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + DateTime.Today.ToString("yyyy/MM/dd") + "')) " +
                     " ORDER BY CORE_RULE.SORTING ";
                listRules = dbConn.Query<CORE_RULE>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();

                szSqlActions =
                    " SELECT " +
                    " CORE_RULE_ACTION.*, " +
                    " CORE_TYPE.TYPE_DESC AS ACTION_DESC " +
                    " FROM CORE_RULE_ACTION " +
                    " INNER JOIN CORE_TYPE ON CORE_RULE_ACTION.ACTION_ID = CORE_TYPE.ID " +
                    " INNER JOIN CORE_RULE ON CORE_RULE_ACTION.RULE_ID = CORE_RULE.ID " +
                    " WHERE RULE_SCOPE = " + (int)Enums.RuleScope.Profile +
                    " AND (CORE_RULE.IS_INACTIVE = 0 OR(CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + DateTime.Today.ToString("yyyy/MM/dd") + "')) " +
                    " ORDER BY CORE_RULE_ACTION.SORTING ";
                listRuleActions = dbConn.Query<CORE_RULE_ACTION>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlActions), commandTimeout: 1200).ToList();
                //}

                if (m_profileDto.profile.id > 0)
                {
                    // Delete Previous Pending AUTHORITY REQUEST
                    var szSqlOldReq =
                        " SELECT SEC_AUTHORITY_REQUEST.* " +
                        " FROM SEC_AUTHORITY_REQUEST " +
                        " WHERE AUTHORITY_SCOPE_ID = " + (int)Enums.AuthorityScope.ProfileCompliance +
                        " AND TABLE_KEY = " + m_profileDto.profile.id +
                        " AND RULE_ID IS NOT NULL " + // todo giorgio 1-Oct-2024 LIA-4047  // CR 2024-00027 compliance
                        " AND IS_APPROVED = 0 ";

                    var lstOldAuthorityRequest = dbConn.Query<SEC_AUTHORITY_REQUEST>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlOldReq)).ToList();

                    foreach (var item in lstOldAuthorityRequest)
                    {
                        dbConn.Execute("DELETE FROM SEC_AUTHORITY_REQUEST WHERE ID = " + item.id);
                    }
                    if (lstOldAuthorityRequest.Any())
                    {
                        //TODO - Hamza 06/10/2023 DEVIRIS5-11982
                        dbConn.Insert(new PF_PROFILE_STATUS
                        {
                            profile_id = m_profileDto.profile.id,
                            status_id = 8300,
                            status_date = DateTime.Now, // giorgio 30-July-2025 LAX-5077 replaced .Today with .Now
                            status_set_by = m_user_id,
                            status_set_by_ba_user = null,
                            status_reason_id = null,
                            notes = ""
                        });
                        //END TODO
                    }
                }

                dbConn.Close();
            }

            for (int i = 0; i < listRules.Count; i++)
            {
                bool blSkipRule = false;

                var szParsedCode = this._parseTheCondition(listRules.ElementAt(i).rule_condition, ref blErrorOccurred, ref blErrorMsg, ref blSkipRule);

                if (blSkipRule) continue;

                if (blErrorOccurred)
                {
                    continue;
                }

                List<CORE_RULE_ACTION> lstActionToApply = new List<CORE_RULE_ACTION>();

                // AN - 2026-03-22 - PERFORMANCE: replaced Roslyn compilation with direct in-process evaluator.
                // See #region Rule Condition Direct Evaluator for full explanation.
                if (_evaluateParsedCondition(szParsedCode))
                {
                    //rule actions if VALID
                    lstActionToApply = listRuleActions.Where(w => w.is_rule_valid == 1).ToList();
                }
                else
                {
                    //rule actions if NOT VALID
                    lstActionToApply = listRuleActions.Where(w => w.is_rule_valid == 0).ToList();
                }

                foreach (var ruleAction in lstActionToApply)
                {
                    if (ruleAction.rule_id == listRules.ElementAt(i).id)
                    {
                        this.Profile_ApplyRuleAction(ruleAction,
                                                     m_company_id,
                                                     m_branch_id,
                                                     m_profileDto.contact.print_name,
                                                     m_profileDto.profile.profile_type_id,
                                                     m_profileDto.profile.id,
                                                     m_role_id,
                                                     m_user_id);
                    }
                }
            }

            result[0] = this.m_ListProfileAction.ToArray();
            result[1] = this.m_ListAuthorityRequest.ToArray();

            return result;
        }

        private void Profile_ApplyRuleAction(CORE_RULE_ACTION _ruleAction, int _companyId, int? _branchId, string _printName, int _profileTypeId, int _profileId, int _roleId, int _userId)
        {
            //TODO IRIS 5: should we add table for profile business rule actions ? in this case we need to check the action existance before adding it again
            //TODO IRIS 5: the authorizer should be get from the RULE it self ? right?

            var profileAction = new iris5.models.PF_PROFILE_ACTION();
            profileAction.profile_id = _profileId;
            profileAction.message = _ruleAction.message;
            profileAction.action_id = _ruleAction.action_id;
            profileAction.action_desc = _ruleAction.action_desc;

            //this.m_ListProfileAction.Add(profileAction); // TODO: Elie BA - 25/JUL/2022 - ticket ALIG-206 - moved the code after checking if rule is applied

            switch (_ruleAction.action_id)
            {
                case (int)Enums.RuleAction.Warning:
                case (int)Enums.RuleAction.Errors:
                    this.m_ListProfileAction.Add(profileAction);
                    break;

                case (int)Enums.RuleAction.NeedAuthorization:
                    {
                        //TODO: IRIS5 Authority Changed
                        var szSqlAuthReq =
                            " SELECT SEC_AUTHORITY_REQUEST.* " +
                            " FROM SEC_AUTHORITY_REQUEST " +
                            " WHERE AUTHORITY_SCOPE_ID = " + (int)Enums.AuthorityScope.ProfileCompliance +
                            " AND IS_APPROVED = 1 " + //" AND IS_APPROVED = 0 " + // TODO: Elie BA - 17/MAY/2022 - ticket 10842 - check if auth alredy requested
                            " AND TABLE_KEY = " + _profileId +
                            " AND RULE_ID = " + _ruleAction.rule_id +
                            " AND ACTION_ID = " + _ruleAction.action_id +
                            " AND IS_RULE_VALID = " + _ruleAction.is_rule_valid;

                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
                            dbConn.ConnectionString = connStr;
                            dbConn.Open();

                            var lstAuthorityRequest = dbConn.Query<SEC_AUTHORITY_REQUEST>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlAuthReq)).ToList();

                            if (lstAuthorityRequest.Count == 0) // the action does not exists in the authority request table
                            {
                                this.m_ListProfileAction.Add(profileAction); // TODO: Elie BA - 25/JUL/2022 - ticket ALIG-206

                                var listAuthorizer = AuthorizerHelper.GetAuthorizerList(connStr, _companyId, _branchId, (int)Enums.AuthorityScope.ProfileCompliance, _roleId, _userId, -1);

                                if (listAuthorizer.Count() > 0)
                                {
                                    var profileType = dbConn.QueryFirstOrDefault<string>(
                                            " SELECT " +
                                            " PROFILE_TYPE_DESC " +
                                            " FROM PF_PROFILE_TYPE " +
                                            " WHERE ID = " + _profileTypeId);

                                    if (profileType == null)
                                    {
                                        profileType = "";
                                    }

                                    foreach (var authorizer in listAuthorizer)
                                    {
                                        var authReq = new SEC_AUTHORITY_REQUEST();
                                        authReq.authority_scope_id = (int)Enums.AuthorityScope.ProfileCompliance;
                                        authReq.company_id = _companyId;
                                        authReq.request_date = DateTime.Now;
                                        authReq.request_by = _userId;
                                        authReq.request_desc = profileType + ": " + _printName + " " + _ruleAction.message;
                                        authReq.is_approved = 0;
                                        authReq.table_key = _profileId;
                                        authReq.target_authorizer_id = authorizer;
                                        authReq.rule_id = _ruleAction.rule_id;
                                        authReq.action_id = _ruleAction.action_id;
                                        authReq.is_rule_valid = _ruleAction.is_rule_valid;
                                        authReq.target_authorizer_id = authorizer;
                                        this.p_ListAuthorityRequest.Add(authReq);
                                    }

                                    //// SEND NOTIFICATION
                                    //if (!result.Contains("Error"))
                                    //{
                                    //    foreach (var authorizer in listAuthorizer)
                                    //    {
                                    //        this.ProfileComplianceSendNotification(_roleId, _userId, _ruleAction.message);
                                    //    }
                                    //}
                                    //// SEND NOTIFICATION

                                    ////adding a new status as pending to the profile
                                    //var newId = dbConn.Insert(new Models.PF_PROFILE_STATUS
                                    //{
                                    //    profile_id = _profileId,
                                    //    status_id = (int)Enums.ProfileStatus.Pending,
                                    //    status_date = DateTime.Today,
                                    //    status_set_by = _userId,
                                    //    notes = "B-Rule: " + _ruleAction.message
                                    //    //status_reason_id = item.status_reason_id,
                                    //});                                     
                                }
                            }

                            dbConn.Close();
                        }
                    }
                    break;

                default:
                    break;
            }
        }

