        #region Collection

        public Array[] ValidateCollectionRules()
        {
            Array[] result = new Array[2];

            this.m_ListCollectionAction.Clear();
            this.m_ListAuthorityRequest.Clear();

            List<CORE_RULE> listRules = new List<CORE_RULE>();
            List<CORE_RULE_ACTION> listRuleActions = new List<CORE_RULE_ACTION>();

            bool blErrorOccurred = false;
            string blErrorMsg = "";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var szSql =
                     " SELECT " +
                     " CORE_RULE.*  " +
                     " FROM CORE_RULE " +
                     " WHERE CORE_RULE.COMPANY_ID = " + m_trsData.company_id +
                     " AND RULE_SCOPE = " + (int)Enums.RuleScope.Collection +
                     " AND (CORE_RULE.IS_INACTIVE = 0 OR (CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + DateTime.Today.ToString("yyyy/MM/dd") + "')) " +
                     " ORDER BY CORE_RULE.SORTING ";
                listRules = dbConn.Query<CORE_RULE>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();

                var szSqlActions =
                    " SELECT " +
                    " CORE_RULE_ACTION.*, " +
                    " CORE_TYPE.TYPE_DESC AS ACTION_DESC " +
                    " FROM CORE_RULE_ACTION " +
                    " INNER JOIN CORE_TYPE ON CORE_RULE_ACTION.ACTION_ID = CORE_TYPE.ID " +
                    " INNER JOIN CORE_RULE ON CORE_RULE_ACTION.RULE_ID = CORE_RULE.ID " +
                    " WHERE CORE_RULE.COMPANY_ID = " + m_trsData.company_id +
                    " AND RULE_SCOPE = " + (int)Enums.RuleScope.Collection +
                    " AND (CORE_RULE.IS_INACTIVE = 0 OR(CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + DateTime.Today.ToString("yyyy/MM/dd") + "')) " +
                    " ORDER BY CORE_RULE_ACTION.SORTING ";
                listRuleActions = dbConn.Query<CORE_RULE_ACTION>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlActions), commandTimeout: 1200).ToList();

                //TODO: add new scope for collection !!!???!!!!
                if (m_trsData.id > 0)
                {
                    // Delete Previous Pending AUTHORITY REQUEST
                    var szSqlOldReq =
                        " SELECT SEC_AUTHORITY_REQUEST.* " +
                        " FROM SEC_AUTHORITY_REQUEST " +
                        " WHERE AUTHORITY_SCOPE_ID = " + (int)Enums.AuthorityScope.CollectionCompliance +
                        " AND TABLE_KEY = " + m_trsData.id +
                        " AND IS_APPROVED = 0 ";

                    var lstOldAuthorityRequest = dbConn.Query<SEC_AUTHORITY_REQUEST>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlOldReq)).ToList();

                    foreach (var item in lstOldAuthorityRequest)
                    {
                        dbConn.Execute("DELETE FROM SEC_AUTHORITY_REQUEST WHERE ID = " + item.id);
                    }
                }

                dbConn.Close();
            }

            for (int i = 0; i < listRules.Count; i++)
            {
                bool blSkipRule = false;

                var szParsedCode = this._parseTheCondition(listRules.ElementAt(i).rule_condition, ref blErrorOccurred, ref blErrorMsg, ref blSkipRule);

                if (blSkipRule) continue;

                if (blErrorOccurred)
                {
                    continue;
                }

                List<CORE_RULE_ACTION> lstActionToApply = new List<CORE_RULE_ACTION>();

                // AN - 2026-03-22 - PERFORMANCE: replaced Roslyn compilation with direct in-process evaluator.
                // See #region Rule Condition Direct Evaluator for full explanation.
                if (_evaluateParsedCondition(szParsedCode))
                {
                    //rule actions if VALID
                    lstActionToApply = listRuleActions.Where(w => w.is_rule_valid == 1).ToList();
                }
                else
                {
                    //rule actions if NOT VALID
                    lstActionToApply = listRuleActions.Where(w => w.is_rule_valid == 0).ToList();
                }

                foreach (var ruleAction in lstActionToApply)
                {
                    if (ruleAction.rule_id == listRules.ElementAt(i).id)
                    {
                        this.Collection_ApplyRuleAction(ruleAction,
                                                     m_company_id,
                                                     m_branch_id,
                                                     //m_trsData.account_profile_type_id,
                                                     m_trsData.id,
                                                     m_role_id,
                                                     m_user_id);
                    }
                }
            }

            //TODO:???!!! do we need to add the table ?
            result[0] = this.m_ListCollectionAction.ToArray();
            result[1] = this.m_ListAuthorityRequest.ToArray();

            return result;
        }

        private void Collection_ApplyRuleAction(CORE_RULE_ACTION _ruleAction, int _companyId, int? _branchId, int _trsId, int _roleId, int _userId)
        {
            //TONY 10-SEP-2021
            // in case we need to show the actionm, then we need to add new data table GL_TRS_ACTION
            var trsAction = new PF_PROFILE_ACTION();
            trsAction.profile_id = _trsId;
            trsAction.message = _ruleAction.message;
            trsAction.action_id = _ruleAction.action_id;
            trsAction.action_desc = _ruleAction.action_desc;
            this.m_ListCollectionAction.Add(trsAction);

            switch (_ruleAction.action_id)
            {
                //case (int)Enums.RuleAction.Warning:
                //case (int)Enums.RuleAction.Errors:     
                //    break;

                case (int)Enums.RuleAction.NeedAuthorization:
                    {
                        //TODO: IRIS5 Authority Changed
                        var szSqlAuthReq =
                            " SELECT " +
                            " SEC_AUTHORITY_REQUEST.* " +
                            " FROM SEC_AUTHORITY_REQUEST " +
                            " WHERE AUTHORITY_SCOPE_ID = " + (int)Enums.AuthorityScope.CollectionCompliance +
                            " AND IS_APPROVED = 0 " +
                            " AND TABLE_KEY = " + _trsId +
                            " AND RULE_ID = " + _ruleAction.rule_id +
                            " AND ACTION_ID = " + _ruleAction.action_id +
                            " AND IS_RULE_VALID = " + _ruleAction.is_rule_valid;

                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
                            dbConn.ConnectionString = connStr;
                            dbConn.Open();

                            var lstAuthorityRequest = dbConn.Query<SEC_AUTHORITY_REQUEST>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlAuthReq)).ToList();

                            dbConn.Close();

                            //TONY 10-SEP-2021 removed the ruleAction.authorizer_role_id != null since by definition it is null in this scope
                            //if (lstAuthorityRequest.Count == 0 && _ruleAction.authorizer_role_id != null) // the action does not exists in the authority request table
                            if (lstAuthorityRequest.Count == 0) // the action does not exists in the authority request table
                            {
                                //TONY 10-SEP-2021 to get autghorizers from Authority not from the business rule action
                                var listAuthorizer = AuthorizerHelper.GetAuthorizerList(connStr, _companyId, _branchId, (int)Enums.AuthorityScope.CollectionCompliance, _roleId, _userId, -1);

                                if (listAuthorizer.Count() > 0)
                                {
                                    foreach (var authorizer in listAuthorizer)
                                    {
                                        var authReq = new SEC_AUTHORITY_REQUEST();
                                        authReq.authority_scope_id = (int)Enums.AuthorityScope.CollectionCompliance;
                                        authReq.company_id = _companyId;
                                        authReq.request_date = DateTime.Now;
                                        authReq.request_by = _userId;
                                        authReq.request_desc = m_trsData.being + " | " + _ruleAction.message;
                                        authReq.is_approved = 0;
                                        authReq.table_key = _trsId;
                                        authReq.target_authorizer_id = authorizer;// authorizer.id;
                                        authReq.rule_id = _ruleAction.rule_id;
                                        authReq.action_id = _ruleAction.action_id;
                                        authReq.is_rule_valid = _ruleAction.is_rule_valid;
                                        this.p_ListAuthorityRequest.Add(authReq);
                                    }
                                }
                            }
                        }
                    }
                    break;

                default:
                    break;
            }
        }

