                        //    " AND IS_RULE_VALID = " + _ruleAction.is_rule_valid;

                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
                            dbConn.ConnectionString = connStr;
                            dbConn.Open();

                            var secAuthorized = dbConn.QueryFirstOrDefault<SEC_AUTHORITY_REQUEST>(
                               " SELECT " +
                               " SEC_AUTHORITY_REQUEST.* " +
                               " FROM SEC_AUTHORITY_REQUEST " +
                               " WHERE AUTHORITY_SCOPE_ID = " + (int)Enums.AuthorityScope.BusinessRulePO +
                               " AND RULE_ID = " + _ruleAction.rule_id +
                               " AND TABLE_KEY = " + _mvmtId +
                               " AND IS_APPROVED = 1");

                            if (secAuthorized != null)
                            {
                                blActionApplied = true;
                            }

                            if (!blActionApplied)
                            {
                                //    var lstAuthorityRequest = dbConn.Query<SEC_AUTHORITY_REQUEST>(szSqlAuthReq).ToList();

                                //if (lstAuthorityRequest.Count == 0) // the action does not exists in the authority request table
                                //{
                                var secAuthorityToDelete = dbConn.Query<SEC_AUTHORITY_REQUEST>(
                              " SELECT " +
                              " SEC_AUTHORITY_REQUEST.* " +
                              " FROM SEC_AUTHORITY_REQUEST " +
                              " WHERE AUTHORITY_SCOPE_ID = " + (int)Enums.AuthorityScope.BusinessRulePO +
                              " AND RULE_ID = " + _ruleAction.rule_id +
                              " AND TABLE_KEY = " + _mvmtId).ToList();

                                foreach (var item in secAuthorityToDelete)
                                {
                                    var authorityRequest_delete = new SEC_AUTHORITY_REQUEST();
                                    authorityRequest_delete.authority_scope_id = item.authority_scope_id;
                                    authorityRequest_delete.company_id = item.company_id;
                                    authorityRequest_delete.rule_id = item.rule_id;
                                    authorityRequest_delete.request_date = item.request_date;
                                    authorityRequest_delete.request_by = item.request_by;
                                    authorityRequest_delete.request_desc = item.request_desc;
                                    authorityRequest_delete.action_id = item.action_id;
                                    authorityRequest_delete.is_rule_valid = item.is_rule_valid;
                                    authorityRequest_delete.target_authorizer_id = item.target_authorizer_id;
                                    authorityRequest_delete.is_approved = item.is_approved;
                                    m_ListAuthorityRequest_deleted.Add(authorityRequest_delete);
                                }

                                //var listAuthorizer = AuthorizerHelper.GetAuthorizerList(_companyId, _branchId, (int)Enums.AuthorityScope.ClaimPaymentOrder, _roleId, _userId, -1);

                                int[] roleIds = Array.ConvertAll(_ruleAction.authorizer_roles.Split(","), int.Parse);

                                var listAuthorizer = dbConn.Query<SEC_AUTHORIZER>(
                                    " SELECT SEC_USER.*" +
                                    " FROM SEC_USER" +
                                    " INNER JOIN SEC_USER_ROLE ON SEC_USER_ROLE.USER_ID = SEC_USER.ID" +
                                    " WHERE SEC_USER_ROLE.ROLE_ID IN @roles " +
                                    " AND SEC_USER.IS_INACTIVE = 0 " +//TODO - HAMZA 19/09/2023 DEVIRIS5-11380
                                                                      //" WHERE SEC_USER_ROLE.ROLE_ID IN (SELECT value FROM STRING_SPLIT(@roles, ',')) " +
                                    " AND SEC_USER_ROLE.COMPANY_ID = @companyId", new { companyId = m_mvmtData.company_id, roles = roleIds }).ToList();

                                if (listAuthorizer.Count() > 0)
                                {
                                    foreach (var authorizer in listAuthorizer)
                                    {
                                        var authReq = new SEC_AUTHORITY_REQUEST();
                                        authReq.authority_scope_id = (int)Enums.AuthorityScope.BusinessRulePO;
                                        authReq.company_id = _companyId;
                                        authReq.request_date = DateTime.Now;
                                        authReq.request_by = _userId;
                                        authReq.request_desc = m_mvmtData.mvmt_desc + " | " + _ruleAction.message;
                                        authReq.is_approved = 0;
                                        authReq.table_key = _mvmtId;
                                        authReq.target_authorizer_id = authorizer.id;
                                        authReq.rule_id = _ruleAction.rule_id;
                                        authReq.action_id = _ruleAction.action_id;
                                        authReq.is_rule_valid = _ruleAction.is_rule_valid;
                                        this.m_ListAuthorityRequest.Add(authReq);
                                    }
                                }
                            }

                            dbConn.Close();
                        }
                    }
                    break;

                default:
                    break;
            }
        }

