        // ════════════════════════════════════════════════════════════════════════════════
        // PERFORMANCE OPTIMISATION — Insured Snapshot Cache   AN - 2026-03-22   PERF #3
        //
        // PROBLEM:
        //   DimensionPolicyInsured has ~16 distinct field cases (INSURED_GENDER,
        //   INSURED_NATIONALITY, etc.).  Each one opens its own DB connection and runs a
        //   single-column query against PF_PROFILE / PF_CONTACT / PF_KYC.  For a rule with
        //   multiple insured fields, and across multiple rules evaluated on the same policy,
        //   the same insured row can be fetched N times.
        //
        // SOLUTION — lazy instance-level cache:
        //   On the FIRST DimensionPolicyInsured hit for a given insuredId, _EnsureInsuredSnapshot
        //   runs ONE parameterised JOIN query (PF_PROFILE + PF_CONTACT + PF_KYC +
        //   CORE_COUNTRY + PF_PROFESSION) and stores the result in _insuredSnap.
        //   Every subsequent field — in the same rule or any later rule in the same
        //   evaluation batch — reads from memory: zero additional DB calls.
        //
        //   If no DimensionPolicyInsured field is ever referenced, _insuredSnap stays null
        //   and zero queries are added — identical overhead to today.
        //
        // CHANGE SURFACE:
        //   • _InsuredSnap nested class (property types match the original per-field queries)
        //   • _insuredSnap / _insuredSnapForId instance fields
        //   • _EnsureInsuredSnapshot(int insuredId) private method
        //   • Each DimensionPolicyInsured case: old query block commented out, snapshot read added
        // ════════════════════════════════════════════════════════════════════════════════
        #region Insured Snapshot Cache (PERF #3)

        /// <summary>
        /// Holds one consolidated insured row.  Property types intentionally match those
        /// returned by the original per-case QueryFirstOrDefault calls so call-sites need
        /// no extra conversion.
        /// </summary>
        private sealed class _InsuredSnap
        {
            // ── PF_PROFILE ────────────────────────────────────────────────────────────
            public string IsCodeCompleted { get; set; }  // CAST(bit AS NVARCHAR) → "0"/"1"
            public string Frn { get; set; }
            public string Crn { get; set; }
            public string CategoryId { get; set; }  // CAST(int AS NVARCHAR)
            // ── PF_CONTACT ───────────────────────────────────────────────────────────
            public string NationalityId { get; set; }  // CAST(int AS NVARCHAR)
            public string SecondNationalityId { get; set; }  // CAST(int AS NVARCHAR)
            public string Gender { get; set; }  // CAST(int AS NVARCHAR)
            public string MaritalStatus { get; set; }  // CAST(int AS NVARCHAR)
            public string ContactType { get; set; }  // CAST(int AS NVARCHAR)
            public int? ProfessionId { get; set; }
            public DateTime? DrivingLicIssDate { get; set; }
            public DateTime? DrivingLicExpDate { get; set; }
            public string DrivingLicNo { get; set; }
            public string PassportNo { get; set; }
            public string IdentityNo { get; set; }
            public DateTime? Dob { get; set; }
            // ── CORE_COUNTRY (left-joined via PF_CONTACT.COUNTRY_ID) ─────────────────
            public string CountryCode { get; set; }
            // ── PF_KYC (left-joined via PF_PROFILE.ID) ───────────────────────────────
            public string IsUsaResident { get; set; }  // CAST(bit AS NVARCHAR) → "0"/"1"
            public string ResidencyTin { get; set; }
            public string UsaTin { get; set; }
            public string TaxResidency { get; set; }
            public int? SpouseProfessionId { get; set; }
            public string SpouseName { get; set; }
            // ── PF_PROFESSION (left-joined via PF_CONTACT.PROFESSION_ID) ─────────────
            public int? ProfessionClassId { get; set; }
        }

        // Fields: snapshot instance + the insuredId it was loaded for (-1 = nothing loaded yet)
        private _InsuredSnap _insuredSnap;
        private int _insuredSnapForId = -1;

        /// <summary>
        /// Loads the insured snapshot for <paramref name="insuredId"/> if not already cached.
        /// One parameterised JOIN query replaces all individual per-field DB calls.
        /// Safe to call multiple times — returns immediately if already loaded for this id.
        /// </summary>
        private void _EnsureInsuredSnapshot(int insuredId)
        {
            if (_insuredSnapForId == insuredId) return;   // already in cache — nothing to do

            const string szSnapSql =
               @" SELECT
                    CAST(PF_PROFILE.IS_CODIFICATION_COMPLETED AS NVARCHAR(5))  AS IsCodeCompleted,
                    PF_PROFILE.FRN                                             AS Frn,
                    PF_PROFILE.CRN                                             AS Crn,
                    CAST(PF_PROFILE.CATEGORY_ID AS NVARCHAR(20))               AS CategoryId,
                    CAST(PF_CONTACT.NATIONALITY_ID AS NVARCHAR(20))            AS NationalityId,
                    CAST(PF_CONTACT.SECOND_NATIONALITY_ID AS NVARCHAR(20))     AS SecondNationalityId,
                    CAST(PF_CONTACT.GENDER AS NVARCHAR(20))                    AS Gender,
                    CAST(PF_CONTACT.MARITAL_STATUS AS NVARCHAR(20))            AS MaritalStatus,
                    CAST(PF_CONTACT.CONTACT_TYPE AS NVARCHAR(20))              AS ContactType,
                    PF_CONTACT.PROFESSION_ID                                   AS ProfessionId,
                    PF_CONTACT.DRIVING_LICENSE_ISSUE_DATE                      AS DrivingLicIssDate,
                    PF_CONTACT.DRIVING_LICENSE_EXPIRY_DATE                     AS DrivingLicExpDate,
                    PF_CONTACT.DRIVING_LICENSE_NO                              AS DrivingLicNo,
                    PF_CONTACT.PASSPORT_NO                                     AS PassportNo,
                    PF_CONTACT.IDENTITY_NO                                     AS IdentityNo,
                    PF_CONTACT.DOB                                             AS Dob,
                    CORE_COUNTRY.COUNTRY_CODE                                  AS CountryCode,
                    CAST(PF_KYC.IS_USA_RESIDENT AS NVARCHAR(5))                AS IsUsaResident,
                    PF_KYC.RESIDENCY_TIN                                       AS ResidencyTin,
                    PF_KYC.USA_TIN                                             AS UsaTin,
                    PF_KYC.TAX_RESIDENCY                                       AS TaxResidency,
                    PF_KYC.PROFESSION_ID                                       AS SpouseProfessionId,
                    PF_KYC.SPOUSE_NAME                                         AS SpouseName,
                    PF_PROFESSION.PROFESSION_CLASS_ID                          AS ProfessionClassId
                FROM PF_PROFILE
                INNER JOIN PF_CONTACT    ON PF_CONTACT.ID      = PF_PROFILE.CONTACT_ID
                LEFT  JOIN PF_KYC        ON PF_KYC.PROFILE_ID  = PF_PROFILE.ID
                LEFT  JOIN CORE_COUNTRY  ON CORE_COUNTRY.ID    = PF_CONTACT.COUNTRY_ID
                LEFT  JOIN PF_PROFESSION ON PF_PROFESSION.ID   = PF_CONTACT.PROFESSION_ID
                WHERE PF_PROFILE.ID = @InsuredId";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();
                _insuredSnap = dbConn.QueryFirstOrDefault<_InsuredSnap>(
                                    Pixel.Core.Dapper.My.AddIsolationRU(szSnapSql),
                                    new { InsuredId = insuredId },
                                    commandTimeout: 1200);
                dbConn.Close();
            }
            _insuredSnapForId = insuredId;   // mark as loaded (even when profile row not found)
        }

        #endregion Insured Snapshot Cache (PERF #3)

        #region OB_OBJECT_PROPERTY Lookup Cache (PERF #4)
        // ════════════════════════════════════════════════════════════════════════════════
        // PROBLEM:
        //   case "DimensionSma" and case "DimensionValue" (P&C branch) each fire a live
        //   DB query — "SELECT PROPERTY_ID FROM OB_OBJECT_PROPERTY WHERE ID = ?" — to
        //   resolve an object-property-instance ID to its parent property definition ID.
        //   OB_OBJECT_PROPERTY is static schema configuration: a given ID always maps to
        //   the same PROPERTY_ID regardless of policy, insured, or evaluation time.
        //   Yet the query runs once per DimensionSma/DimensionValue node, per rule call.
        //
        // SOLUTION:
        //   _ResolvePropertyId(int) checks a Dictionary<int,int> first.
        //   On miss it queries once and stores the result — every subsequent call for the
        //   same ID is a dictionary lookup with zero DB round-trips.
        //   The dictionary lives on the helper instance, so it is shared across all rules
        //   evaluated in the same request.
        //
        // CHANGE SURFACE:
        //   • This region adds _obPropertyIdCache + _ResolvePropertyId(int).
        //   • The 2 using(dbConn) blocks in DimensionSma / DimensionValue are commented
        //     out (AN - 2026-03-22 PERF #4) and replaced with _ResolvePropertyId().
        // ════════════════════════════════════════════════════════════════════════════════

        private readonly Dictionary<int, int> _obPropertyIdCache = new Dictionary<int, int>();

        private int? _ResolvePropertyId(int objectPropertyId)
        {
            if (_obPropertyIdCache.TryGetValue(objectPropertyId, out int cached))
                return cached;

            int? propId;
            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();
                propId = dbConn.QueryFirstOrDefault<int?>(
                    Pixel.Core.Dapper.My.AddIsolationRU(
                        "SELECT PROPERTY_ID FROM OB_OBJECT_PROPERTY WHERE ID = @Id"),
                    new { Id = objectPropertyId }, commandTimeout: 1200);
                dbConn.Close();
            }

            if (propId.HasValue)
                _obPropertyIdCache[objectPropertyId] = propId.Value;

            return propId;
        }

        #endregion OB_OBJECT_PROPERTY Lookup Cache (PERF #4)

        #region dynamic Code

        private string _parseTheCondition(string _ruleXmlCondition, ref bool _errorOccurred, ref string _errorMsg, ref bool _skipTheRule)
        {
            // AN - 2026-03-22 PERF #5 — use StringBuilder instead of string to avoid O(n²)
            // allocations across the node loop.  ToString() is called once at the return point.
            var szCode = new StringBuilder("if ( ");

            this.m_XMLDoc = new XmlDocument();
            this.m_XMLDoc.InnerXml = _ruleXmlCondition;
            this.xNodeList = this.m_XMLDoc.GetElementsByTagName("*");

            string szFunction = "";
            string szInnerFunction = "";
            ArrayList oParameters = new ArrayList();
            ArrayList oInnerParameters = new ArrayList();

            foreach (XmlNode xNode in xNodeList)
            {
                this._formulateCode(xNode,
                                    ref szCode,
                                    ref szFunction,
                                    ref oParameters,
                                    ref szInnerFunction,
                                    ref oInnerParameters,
                                    ref _errorOccurred,
                                    ref _errorMsg,
                                    ref _skipTheRule);
                if (_skipTheRule)
                {
                    return "";
                }
                if (_errorOccurred)
                {
                    return "";
                }
            }

            // AN - 2026-03-22 PERF #5 — "if ( " is 5 chars; Length == 5 means no node appended anything
            if (szCode.Length == 5)
            {
                return "";
            }

            szCode.Append(
                "   )" + Environment.NewLine +
                "   {" + Environment.NewLine +
                "       return true;" + Environment.NewLine +
                "   }" + Environment.NewLine +
                "   else " + Environment.NewLine +
                "   {" + Environment.NewLine +
                "       return false;" + Environment.NewLine +
                "   }" + Environment.NewLine);

            return szCode.ToString();
        }

        // AN - 2026-03-22 PERF #5 — changed ref string _szCode → ref StringBuilder _szCode
        // to avoid O(n²) string allocations when many XML nodes append to the same string.
        // All _szCode.Append(expr; calls below are replaced with _szCode.Append(expr)); equivalents.
        private void _formulateCode(XmlNode _xNode,
                                    ref StringBuilder _szCode,
                                    ref string _function,
                                    ref ArrayList _parameters,
                                    ref string _innerFunction,
                                    ref ArrayList _innerParameters,
                                    ref bool _errorOccurred,
                                    ref string _errorMsg,
                                    ref bool _skipTheRule)
        {
            string szNodeName = _xNode.Name;
            //TODO - RALPH 22/06/2023 LIA-1116
            List<UW_POLICY> policyList = new List<UW_POLICY>();
            System.Data.DataTable policydatatable;
            if (szNodeName.IndexOf("_") != -1)
            {
                switch (szNodeName.Substring(0, szNodeName.IndexOf("_") + 1))
                {
                    case "p_":
                        szNodeName = szNodeName.Remove(0, szNodeName.IndexOf("_") + 1);
                        _function = "";
                        _innerFunction = "";
                        _parameters.Clear();
                        _innerParameters.Clear();

                        switch (szNodeName)
                        {
                            case "Operator":
                            case "LeftParenthesis":
                            case "RightParenthesis":
                                {
                                    if (_xNode.InnerText == "<=" || _xNode.InnerText == ">=")
                                    {
                                        _szCode.Append(_xNode.InnerText.Replace("<>", "!=") + " ");
                                    }
                                    else
                                    {
                                        _szCode.Append(_xNode.InnerText.Replace("=", "==").Replace("<>", "!=") + " ");
                                    }
                                    break;
                                }
                            case "LogOperator":
                                {
                                    _szCode.Append(_xNode.InnerText.Replace("AND", "&&").Replace("OR", "||") + " ");

                                    break;
                                }
                            case "DimensionSma":
