                                            if (polProperty.object_property_id == Convert.ToInt32(_xNode.InnerText))
                                            {
                                                if (polProperty.the_value != "")
                                                {
                                                    if (Pixel.Core.Lib.CoreHelper.IsNumeric(polProperty.the_value))
                                                    {
                                                        _szCode.Append("Convert.ToDecimal(\"" + polProperty.the_value + "\")" + " ");
                                                    }
                                                    else
                                                    {
                                                        _szCode.Append("\"" + polProperty.the_value + "\"" + " ");
                                                    }
                                                }
                                                else
                                                {
                                                    _szCode.Append("Nothing ");
                                                    _skipTheRule = true;
                                                }

                                                blFound = true;
                                                this.m_Linked_to_property_id = Convert.ToInt32(_xNode.InnerText);
                                                break;
                                            }
                                        }
                                    }
                                    else //P&C
                                    {
                                        // AN - 2026-03-22 PERF #4 — replaced per-call DB query with cached lookup.
                                        // Original query kept below for review:
                                        /* AN - 2026-03-22 PERF #4 — replaced by _ResolvePropertyId(); original query kept for review
                                        // giorgio 4-Nov-2025 SFA-1153
                                        int? propertyId = null;

                                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
