                                            dbConn.ConnectionString = connStr;
                                            dbConn.Open();

                                            propertyId = dbConn.QueryFirstOrDefault<int>("SELECT PROPERTY_ID FROM OB_OBJECT_PROPERTY WHERE ID = " + Convert.ToInt32(_xNode.InnerText));
                                        }
                                        // end giorgio 4-Nov-2025 SFA-1153
                                        */
                                        int? propertyId = _ResolvePropertyId(Convert.ToInt32(_xNode.InnerText));

                                        foreach (var polProperty in m_policyDto.policy_property)
