                            case "EndFunction":
                                switch (_xNode.InnerText)
                                {
                                    case "END_ISNULL":
                                        _szCode.Append(this.FnIsNull(_parameters));
                                        _function = "";
                                        _parameters.Clear();

                                        break;
                                    case "END_ADD":
                                        if (_innerFunction != "")
                                        {
                                            this.szTempCode = this.FnAdd(_innerParameters);
                                            _parameters.Add(szTempCode);
                                            _innerFunction = "";
                                            _innerParameters.Clear();

                                            //TODO: Elie BA - 18/MAY/2022 - ticket 10916 - if the _innerFunction is inside a _function it should not be added to_szCode
                                            // _szCode.Append(szTempCode);

                                            if (_function == "")
                                            {
                                                _szCode.Append(szTempCode);
                                            }
                                            //END TODO: Elie BA - 18/MAY/2022 - ticket 10916
                                        }
                                        else
                                        {
                                            _szCode.Append(this.FnAdd(_parameters));
                                            _function = "";
                                            _parameters.Clear();
                                        }

                                        break;
                                    case "END_SUBSTRACT":
                                        if (_innerFunction != "")
                                        {
                                            this.szTempCode = this.FnSubstract(_innerParameters);
                                            _parameters.Add(szTempCode);
                                            _innerFunction = "";
                                            _innerParameters.Clear();

                                            //TODO: Elie BA - 18/MAY/2022 - ticket 10916 - if the _innerFunction is inside a _function it should not be added to_szCode
                                            // _szCode.Append(szTempCode);

                                            if (_function == "")
                                            {
                                                _szCode.Append(szTempCode);
                                            }
                                            //END TODO: Elie BA - 18/MAY/2022 - ticket 10916
                                        }
                                        else
                                        {
                                            _szCode.Append(this.FnSubstract(_parameters));
                                            _function = "";
                                            _parameters.Clear();
                                        }

                                        break;
                                    case "END_MULTIPLY":
                                        if (_innerFunction != "")
                                        {
                                            this.szTempCode = this.FnMultiply(_innerParameters);
                                            _parameters.Add(szTempCode);
                                            _innerFunction = "";
                                            _innerParameters.Clear();

                                            //TODO: Elie BA - 18/MAY/2022 - ticket 10916 - if the _innerFunction is inside a _function it should not be added to_szCode
                                            // _szCode.Append(szTempCode);

                                            if (_function == "")
                                            {
                                                _szCode.Append(szTempCode);
                                            }
                                            //END TODO: Elie BA - 18/MAY/2022 - ticket 10916
                                        }
                                        else
                                        {
                                            _szCode.Append(this.FnMultiply(_parameters));
                                            _function = "";
                                            _parameters.Clear();
                                        }

                                        break;
                                    case "END_DIVIDE":
                                        if (_innerFunction != "")
