                                        m_linked_policy_branch_id = (int)rowfields["BRANCH_ID"];

                                        szAsAt = m_policyDto.policy.date_issue.ToString("yyyy/MM/dd");

                                        if ((int)rowfields["CONTRACT_TYPE_ID"] == (int)Enums.ContractType.Policy ||
