                                            (int)rowfields["CONTRACT_TYPE_ID"] == (int)Enums.ContractType.Endorsement)
                                        {
                                            this.GetContractLastImageData(ref m_PolicyLastImage,
                                                                          (int)m_policyDto.policy.linked_policy_id,
                                                                            szAsAt,
