                                                                                   (int)rowfields["ROOT_ID"],
                                                                                   szAsAt,
                                                                                   (int)rowfields["CERTIF_NO"],
                                                                                   false);
                                        }
                                        else if ((int)rowfields["CONTRACT_TYPE_ID"] == (int)Enums.ContractType.AccountableCertificate)
                                        {
                                            this.GetCertificateLastImageData(ref m_PolicyLastImage,
                                                                             (int)m_policyDto.policy.linked_policy_id,
