        #endregion dynamic Code

        // ════════════════════════════════════════════════════════════════════════════════
        // PERFORMANCE OPTIMISATION — Rule Condition Direct Evaluator
        // AN - 2026-03-22
        //
        // PROBLEM:
        //   Every call to Pixel.Core.Lib.DynamicClass.RunTheDynamicCode(szParsedCode)
        //   performs a full Roslyn pipeline per rule per policy evaluation:
        //     ParseText → CSharpCompilation.Create → Emit(MemoryStream) → Assembly.Load
        //   This costs 100–500 ms per rule.  With 20 rules on a single policy save,
        //   that is up to 10 seconds of pure compilation overhead.
        //   Additionally, each Assembly.Load() leaks memory because loaded assemblies
        //   are never unloaded for the lifetime of the process.
        //
        // ROOT CAUSE:
        //   _formulateCode() already resolves EVERY operand (policy SMA fields, cover
        //   checks, dates, profile values…) to a C# STRING LITERAL before compilation.
        //   The code handed to Roslyn is therefore a CONSTANT boolean expression —
        //   there are NO variables left.  For example:
        //       if ( Convert.ToInt32(Convert.ToBoolean("True")) == 1
        //         || "Sweden" != "Lebanon" )
        //       { return true; } else { return false; }
        //   Roslyn is doing nothing that cannot be done with a 200-line in-process parser.
        //
        // SOLUTION:
        //   _evaluateParsedCondition() parses the string produced by _parseTheCondition()
        //   and evaluates it as a typed boolean expression directly in-process.
        //   Zero compilation.  Zero assembly leaks.  Execution time < 0.1 ms per rule.
        //
        // CHANGE SURFACE (everything else is untouched):
        //   • This region adds _evaluateParsedCondition + nested types _RuleScanner /
        //     _RuleParser.
        //   • The 5 call sites of DynamicClass.RunTheDynamicCode(szParsedCode) are
        //     replaced with _evaluateParsedCondition(szParsedCode).
        //   • _parseTheCondition() and _formulateCode() are LEFT UNCHANGED.
        //
        // SUPPORTED VALUE TOKENS (exactly what _formulateCode emits):
        //   Convert.ToDecimal("…")                     → decimal
        //   Convert.ToDateTime("yyyy/MM/dd")            → DateTime
        //   Convert.ToInt32(Convert.ToBoolean("…"))     → int  (1 = true / 0 = false)
        //   "string literal"                            → string
        //   bare integer / decimal  (0, 1, 42, 3.14)   → int / decimal
        // ════════════════════════════════════════════════════════════════════════════════
        #region Rule Condition Direct Evaluator

        /// <summary>
        /// Evaluates the condition string produced by _parseTheCondition() in-process,
        /// without Roslyn.  Replaces every call to DynamicClass.RunTheDynamicCode().
        /// Returns false for null/empty input — same behaviour as a Roslyn compile failure.
        /// </summary>
        private static bool _evaluateParsedCondition(string szParsedCode)
        {
            // Empty string → _parseTheCondition returned "" (rule skipped / empty condition)
            if (string.IsNullOrWhiteSpace(szParsedCode))
                return false;

            try
            {
                // ── Extract the boolean expression from the if-statement ──────────────
                // _parseTheCondition produces exactly this format:
                //   "if ( <expr> )\n   {\n       return true;\n   }\n   else ..."
                // We need everything between "if (" and the opening "{".
                int ifOpen = szParsedCode.IndexOf("if (", StringComparison.Ordinal);
                if (ifOpen < 0) return false;

                int exprStart = ifOpen + 4;                          // skip "if ("
                int bracePos = szParsedCode.IndexOf('{', exprStart); // first "{" opens the if-body
                if (bracePos < 0) return false;

                // Between exprStart and bracePos we have "  <expr>  )\n   "
                // TrimEnd removes trailing whitespace/newlines → ends with ")"
                // That trailing ")" is the one _parseTheCondition appended ("   )"); remove it.
                string condPart = szParsedCode.Substring(exprStart, bracePos - exprStart).TrimEnd();
                if (condPart.Length > 0 && condPart[condPart.Length - 1] == ')')
                    condPart = condPart.Substring(0, condPart.Length - 1);

                // ── Parse and evaluate ───────────────────────────────────────────────
                var scanner = new _RuleScanner(condPart);
                return new _RuleParser(scanner).ParseOr();
            }
            catch
            {
                // Any unexpected parse/evaluate failure → false
                // (mirrors the Roslyn compile-error path which also returned false)
                return false;
            }
        }

        // ── Token kinds ──────────────────────────────────────────────────────────────
        // These map 1-to-1 with what _formulateCode emits into the condition string.
        private enum _RuleTokKind
        {
            LP, RP,               // parentheses   (  )
            AND, OR,              // logical        && ||
            EQ, NEQ,              // equality       == !=
            GT, GTE, LT, LTE,     // relational      >  >=  <  <=
            ValInt,               // integer  (also used for bool 0/1 from FnPolicyCoverInclude etc.)
            ValDec,               // decimal  (from Convert.ToDecimal or bare numeric)
            ValStr,               // string   (from "…" literals)
            ValDt,                // DateTime (from Convert.ToDateTime)
            EOF
        }

        private struct _RuleTok
        {
            public _RuleTokKind Kind;
            public object Val;  // int | decimal | string | DateTime | null
        }

        // giorgio 26-mar-2026 BNK-534
        // Known prefixes emitted by _formulateCode / Fn* methods.
        // Length includes the opening quote so q1 = _i + Length - 1.
        private const string PfxBool = "Convert.ToInt32(Convert.ToBoolean(\""; // 35 chars
        private const string PfxDecimal = "Convert.ToDecimal(\"";                  // 19 chars
        private const string PfxDate = "Convert.ToDateTime(\"";                 // 20 chars
        // end giorgio 26-mar-2026 BNK-534

        // ── Scanner ──────────────────────────────────────────────────────────────────
        // Converts the condition string into a stream of _RuleTok.
        // Handles exactly the patterns that _formulateCode writes — no more, no less.
        private sealed class _RuleScanner
        {
            private readonly string _s;
            private int _i;
            private _RuleTok? _peek; // one-token look-ahead buffer

            // giorgio 26-mar-2026 BNK-534
            //// Known prefixes emitted by _formulateCode / Fn* methods.
            //// Length includes the opening quote so q1 = _i + Length - 1.
            //private const string PfxBool = "Convert.ToInt32(Convert.ToBoolean(\""; // 35 chars
            //private const string PfxDecimal = "Convert.ToDecimal(\"";                  // 19 chars
            //private const string PfxDate = "Convert.ToDateTime(\"";                 // 20 chars
            // end giorgio 26-mar-2026 BNK-534

            public _RuleScanner(string s) { _s = s ?? string.Empty; }

            // giorgio 26-mar-2026 BNK-534
            public _RuleTok ParseToDecimal()
            {
                int q1 = _i + PfxDecimal.Length - 1;        // opening "
                int q2 = _s.IndexOf('"', q1 + 1);           // closing "
                if (q2 < 0) { _i = _s.Length; return Tok(_RuleTokKind.EOF); }
                string numStr = _s.Substring(q1 + 1, q2 - q1 - 1);
                int closeP = _s.IndexOf(')', q2);            // closing )
                _i = closeP >= 0 ? closeP + 1 : _s.Length;
                return Tok(_RuleTokKind.ValDec,
                    decimal.Parse(numStr,
                        System.Globalization.CultureInfo.InvariantCulture));
            }

            public _RuleTok ParseToDate()
            {
                int q1 = _i + PfxDate.Length - 1;           // opening "
                int q2 = _s.IndexOf('"', q1 + 1);           // closing "
                if (q2 < 0) { _i = _s.Length; return Tok(_RuleTokKind.EOF); }
                string dtStr = _s.Substring(q1 + 1, q2 - q1 - 1);
                int closeP = _s.IndexOf(')', q2);
                _i = closeP >= 0 ? closeP + 1 : _s.Length;
                return Tok(_RuleTokKind.ValDt,
                    DateTime.Parse(dtStr,
                        System.Globalization.CultureInfo.InvariantCulture));
            }

            public _RuleTok ParseToBool()
            {
                int q1 = _i + PfxBool.Length - 1;           // position of opening "
                int q2 = _s.IndexOf('"', q1 + 1);           // position of closing "
                if (q2 < 0) { _i = _s.Length; return Tok(_RuleTokKind.EOF); }
                string boolVal = _s.Substring(q1 + 1, q2 - q1 - 1);
                // Skip past closing "))" — two parens close the nested Convert calls
                int ppPos = _s.IndexOf("))", q2);
                _i = ppPos >= 0 ? ppPos + 2 : _s.Length;
                int intVal = string.Equals(boolVal, "True",
                                 StringComparison.OrdinalIgnoreCase) ? 1 : 0;
                return Tok(_RuleTokKind.ValInt, intVal);
            }
            // end giorgio 26-mar-2026 BNK-534

            // Returns the next token without consuming it (look-ahead).
            public _RuleTok Peek()
            {
                if (_peek == null) _peek = Read();
                return _peek.Value;
            }

            // Consumes and returns the next token.
            public _RuleTok Consume()
            {
                var t = Peek();
                _peek = null;
                return t;
            }

            // giorgio 26-mar-2026 BNK-534 - changed to public
            // Checks whether _s starts with `prefix` at the current position.
            public bool StartsWith(string prefix)
            {
                if (_i + prefix.Length > _s.Length) return false;
                return string.Compare(_s, _i, prefix, 0, prefix.Length,
                                      StringComparison.Ordinal) == 0;
            }

            private void SkipWS()
            {
                while (_i < _s.Length && char.IsWhiteSpace(_s[_i])) _i++;
            }

            private static _RuleTok Tok(_RuleTokKind k, object v = null)
                => new _RuleTok { Kind = k, Val = v };

            private _RuleTok Read()
            {
                SkipWS();
                if (_i >= _s.Length) return Tok(_RuleTokKind.EOF);

                // ── Convert.ToInt32(Convert.ToBoolean("True/False")) ─────────────
                // Emitted by FnPolicyCoverInclude, FnCoInsuranceByCover, etc.
                // Returns int 1 (true) or 0 (false).
                if (StartsWith(PfxBool))
                {
                    // giorgio 26-mar-2026 BNK-534
                    return ParseToBool();

                    //int q1 = _i + PfxBool.Length - 1;           // position of opening "
                    //int q2 = _s.IndexOf('"', q1 + 1);           // position of closing "
                    //if (q2 < 0) { _i = _s.Length; return Tok(_RuleTokKind.EOF); }
                    //string boolVal = _s.Substring(q1 + 1, q2 - q1 - 1);
                    //// Skip past closing "))" — two parens close the nested Convert calls
                    //int ppPos = _s.IndexOf("))", q2);
                    //_i = ppPos >= 0 ? ppPos + 2 : _s.Length;
                    //int intVal = string.Equals(boolVal, "True",
                    //                 StringComparison.OrdinalIgnoreCase) ? 1 : 0;
                    //return Tok(_RuleTokKind.ValInt, intVal);
                    // end giorgio 26-mar-2026 BNK-534
                }

                // ── Convert.ToDecimal("…") ───────────────────────────────────────
                // Emitted by DimensionSma (numeric SMA values), POLICY_PREMIUM, etc.
                if (StartsWith(PfxDecimal))
                {
                    // giorgio 26-mar-2026 BNK-534
                    return ParseToDecimal();

                    //int q1 = _i + PfxDecimal.Length - 1;        // opening "
                    //int q2 = _s.IndexOf('"', q1 + 1);           // closing "
                    //if (q2 < 0) { _i = _s.Length; return Tok(_RuleTokKind.EOF); }
                    //string numStr = _s.Substring(q1 + 1, q2 - q1 - 1);
                    //int closeP = _s.IndexOf(')', q2);            // closing )
                    //_i = closeP >= 0 ? closeP + 1 : _s.Length;
                    //return Tok(_RuleTokKind.ValDec,
                    //    decimal.Parse(numStr,
                    //        System.Globalization.CultureInfo.InvariantCulture));
                    
                    // end giorgio 26-mar-2026 BNK-534
                }

                // ── Convert.ToDateTime("yyyy/MM/dd") ────────────────────────────
                // Emitted by DimensionPolicy DATE_ISSUE / DATE_EFFECTIVE / DATE_EXPIRY
                // and date-type SMA properties.
                if (StartsWith(PfxDate))
                {
                    // giorgio 26-mar-2026 BNK-534
                    return ParseToDate();

                    //int q1 = _i + PfxDate.Length - 1;           // opening "
                    //int q2 = _s.IndexOf('"', q1 + 1);           // closing "
                    //if (q2 < 0) { _i = _s.Length; return Tok(_RuleTokKind.EOF); }
                    //string dtStr = _s.Substring(q1 + 1, q2 - q1 - 1);
                    //int closeP = _s.IndexOf(')', q2);
                    //_i = closeP >= 0 ? closeP + 1 : _s.Length;
                    //return Tok(_RuleTokKind.ValDt,
                    //    DateTime.Parse(dtStr,
                    //        System.Globalization.CultureInfo.InvariantCulture));
                    // end giorgio 26-mar-2026 BNK-534
                }

                // ── Two-character operators (must come before single-char checks) ─
                if (StartsWith("&&")) { _i += 2; return Tok(_RuleTokKind.AND); }
                if (StartsWith("||")) { _i += 2; return Tok(_RuleTokKind.OR); }
                if (StartsWith("==")) { _i += 2; return Tok(_RuleTokKind.EQ); }
                if (StartsWith("!=")) { _i += 2; return Tok(_RuleTokKind.NEQ); }
                if (StartsWith(">=")) { _i += 2; return Tok(_RuleTokKind.GTE); }
                if (StartsWith("<=")) { _i += 2; return Tok(_RuleTokKind.LTE); }

                // ── Single-character tokens ──────────────────────────────────────
                char c = _s[_i];
                if (c == '(') { _i++; return Tok(_RuleTokKind.LP); }
                if (c == ')') { _i++; return Tok(_RuleTokKind.RP); }
                if (c == '>') { _i++; return Tok(_RuleTokKind.GT); }
                if (c == '<') { _i++; return Tok(_RuleTokKind.LT); }

                // ── String literal "…" ───────────────────────────────────────────
                // Emitted for string-typed SMA fields, DimensionValue non-numeric,
                // BRANCH, USER_ROLE, END_TYPE, etc.
                // Values from the DB are assumed not to contain embedded quotes.
                if (c == '"')
                {
                    _i++; // skip opening quote
                    int start = _i;
                    while (_i < _s.Length && _s[_i] != '"') _i++;
                    string strVal = _s.Substring(start, _i - start);
                    if (_i < _s.Length) _i++; // skip closing quote
                    return Tok(_RuleTokKind.ValStr, strVal);
                }

                // ── Bare integer or decimal ──────────────────────────────────────
                // Emitted by: IS_GROUP (0/1), LOB, COB, PRODUCT, BROKER,
                //             DimensionValue TRUE→1 / FALSE→0, POLICY_SUM_INSURED, etc.
                if (c == '-' || char.IsDigit(c))
                {
                    int start = _i;
                    if (c == '-') _i++;
                    while (_i < _s.Length && (char.IsDigit(_s[_i]) || _s[_i] == '.'))
                        _i++;
                    string numStr = _s.Substring(start, _i - start);
                    // Guard: lone minus with no digits (shouldn't happen, but be safe)
                    if (numStr == "-") return Read();
                    if (numStr.IndexOf('.') >= 0)
                        return Tok(_RuleTokKind.ValDec,
                            decimal.Parse(numStr,
                                System.Globalization.CultureInfo.InvariantCulture));
                    return Tok(_RuleTokKind.ValInt, int.Parse(numStr));
                }

                // ── Unknown character — skip and recurse ────────────────────────
                // Handles any whitespace or unexpected chars not caught above.
                _i++;
                return Read();
            }
        }

        // ── Parser (recursive descent) ────────────────────────────────────────────
        // Grammar (precedence: OR < AND < comparison < atom):
        //
        //   or     → and  ( '||' and  )*
        //   and    → cmp  ( '&&' cmp  )*
        //   cmp    → atom compOp atom | atom
        //   atom   → '(' or ')' | VALUE
        //
        // This matches the structure _formulateCode produces: a flat list of
        // [value OP value] clauses joined by AND/OR, with explicit parentheses.
        private sealed class _RuleParser
        {
            private readonly _RuleScanner _sc;
            public _RuleParser(_RuleScanner sc) { _sc = sc; }

            // Entry point — evaluates the full OR-level expression.
            public bool ParseOr()
            {
                bool left = ParseAnd();
                while (_sc.Peek().Kind == _RuleTokKind.OR)
                {
                    _sc.Consume(); // consume '||'
                    bool right = ParseAnd();
                    left = left || right; // short-circuit semantics preserved
                }
                return left;
            }

            private bool ParseAnd()
            {
                bool left = ParseCmp();
                while (_sc.Peek().Kind == _RuleTokKind.AND)
                {
                    _sc.Consume(); // consume '&&'
                    bool right = ParseCmp();
                    left = left && right;
                }
                return left;
            }

            private bool ParseCmp()
            {
                object left = ParseAtom();

                // Check whether a comparison operator follows
                _RuleTokKind k = _sc.Peek().Kind;
                if (k != _RuleTokKind.EQ && k != _RuleTokKind.NEQ &&
                    k != _RuleTokKind.GT && k != _RuleTokKind.GTE &&
                    k != _RuleTokKind.LT && k != _RuleTokKind.LTE)
                {
                    // No comparison operator — treat the single value as truthy/falsy.
                    // This handles standalone IS_GROUP, LOB etc. used as boolean expressions.
                    return IsTruthy(left);
                }

                _sc.Consume(); // consume the comparison operator
                object right = ParseAtom();
                return Compare(left, k, right);
            }

            private object ParseAtom()
            {
                var tok = _sc.Peek();

                // Parenthesised sub-expression: ( or-expr )
                // Returns int 1/0 so it can take part in a subsequent comparison if needed.
                if (tok.Kind == _RuleTokKind.LP)
                {
                    _sc.Consume(); // consume '('
                    bool result = ParseOr();
                    if (_sc.Peek().Kind == _RuleTokKind.RP)
                        _sc.Consume(); // consume ')'
                    return result ? 1 : 0;
                }

                // Any VALUE token — consume and return typed value
                _sc.Consume();
                return tok.Val;
            }

            // ── Type-aware comparison ─────────────────────────────────────────────
            // _formulateCode ensures LHS and RHS have matching types for a given
            // condition, but we add int/decimal coercion for robustness.
            private static bool Compare(object left, _RuleTokKind op, object right)
            {
                // Both null
                if (left == null && right == null) return op == _RuleTokKind.EQ;
                if (left == null || right == null) return op == _RuleTokKind.NEQ;

                // Coerce int ↔ decimal so numeric comparisons always use the same type
                if (left is int liCoerce && right is decimal) left = (decimal)liCoerce;
                if (left is decimal && right is int riCoerce) right = (decimal)riCoerce;

                // DateTime comparison
                // Produced by DATE_ISSUE, DATE_EFFECTIVE, DATE_EXPIRY, SMA date fields
                if (left is DateTime ld && right is DateTime rd)
                    return EvalCmp(ld.CompareTo(rd), op);

                // Decimal comparison
                // Produced by Convert.ToDecimal("…") and numeric SMA values
                if (left is decimal ldec && right is decimal rdec)
                    return EvalCmp(ldec.CompareTo(rdec), op);

                // Integer comparison
                // Produced by bool-converted functions (1/0) and bare ints
                if (left is int li && right is int ri)
                {
                    switch (op)
                    {
                        case _RuleTokKind.EQ: return li == ri;
                        case _RuleTokKind.NEQ: return li != ri;
                        case _RuleTokKind.GT: return li > ri;
                        case _RuleTokKind.GTE: return li >= ri;
                        case _RuleTokKind.LT: return li < ri;
                        case _RuleTokKind.LTE: return li <= ri;
                    }
                }

                // String comparison — ordinal to match C# default "string == string"
                // behaviour that the original Roslyn-compiled code used.
                string ls = left.ToString();
                string rs = right.ToString();
                return EvalCmp(string.CompareOrdinal(ls, rs), op);
            }

            private static bool EvalCmp(int cmpResult, _RuleTokKind op)
            {
                switch (op)
                {
                    case _RuleTokKind.EQ: return cmpResult == 0;
                    case _RuleTokKind.NEQ: return cmpResult != 0;
                    case _RuleTokKind.GT: return cmpResult > 0;
                    case _RuleTokKind.GTE: return cmpResult >= 0;
                    case _RuleTokKind.LT: return cmpResult < 0;
                    case _RuleTokKind.LTE: return cmpResult <= 0;
                    default: return false;
                }
            }

            // Truthy check for standalone values used without a comparison operator.
            private static bool IsTruthy(object v)
            {
                if (v is bool b) return b;
                if (v is int i) return i != 0;
                if (v is decimal d) return d != 0m;
                if (v is string s) return !string.IsNullOrEmpty(s);
                return v != null;
            }
        }

        #endregion Rule Condition Direct Evaluator


        //ValidateACCT
        public PolicyDto ExecuteUWRules()
        {
            //TODO: IRIS5 need this !?
            //cRuleHelper.p_ListAuthorizedOperation = oContextSec.SEC_AUTHORITY_REQUEST.Where(w => w.TABLE_KEY == NewPolicyID).ToList();

            //cRuleHelper.p_current_date = _policyDto.policy.date_issue;
            //TODO: IRIS5 need this !?
            //cRuleHelper.p_parent_date = (int)_ContractIDCollection.ElementAt(i).PolicyID;

            #region policies

            if (p_policyDto.policy.contract_type_id != (int)Enums.ContractType.Certificate)
            {
                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;

                    dbConn.Open();

                    if (p_policyDto.policy.contract_type_id == (int)Enums.ContractType.Endorsement ||
                        p_policyDto.policy.contract_type_id == (int)Enums.ContractType.EndOPC)//TODO ELIASN 19-JAN-2024 AXA-4258
                    {
                        var szSql =
                            " SELECT " +
                            " ID " +
                            ",ROOT_ID " +
                            " FROM UW_POLICY " +
                            " WHERE ID = " + p_policyDto.policy.parent_policy_id;

                        var result = dbConn.QueryFirstOrDefault<policyQry>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                        if (result != null)
                        {
                            //businessRuleHelper.p_ACCT_parent_lob_id = Convert.ToInt32(rowfields["LOB_ID"]);
                            p_ACCT_parent_root_id = result.root_id;
                            p_ACCT_parent_policy_id = result.id;

                            switch (p_policyDto.policy.end_type)
                            {
                                case "C":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndCancellation);
                                    break;
                                case "G":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndGeneral);
                                    break;
                                case "E":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndExtension);
                                    break;
                                case "A":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndReactivation);
                                    break;
                                case "I":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndReinstatement);
                                    break;
                                case "S":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndSuspension);
                                    break;
                            }
                        }
                    }
                    else if (p_policyDto.policy.contract_type_id == (int)Enums.ContractType.RenewalNotice)
                    {
                        var szSql =
                         " SELECT " +
                         " ID" +
                         ",ROOT_ID " +
                         " FROM UW_POLICY " +
                         " WHERE ROOT_ID = " + p_policyDto.root.old_root_id +
                         " AND CONTRACT_TYPE_ID IN (0,11)";

                        var result = dbConn.QueryFirstOrDefault<policyQry>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                        if (result != null)
                        {
                            //businessRuleHelper.p_ACCT_parent_lob_id = Convert.ToInt32(rowfields["LOB_ID"]);
                            p_ACCT_parent_root_id = result.root_id;
                            p_ACCT_parent_policy_id = result.id;

                            ValidateUWRules(Enums.RuleUWOperationType.Renewal);//. "10");
                        }
                    }
                    else if (p_policyDto.root.old_root_id != null)
                    {
                        var szSql =
                           " SELECT " +
                           " ID" +
                           ",ROOT_ID " +
                           " FROM UW_POLICY " +
                           " WHERE ROOT_ID = " + p_policyDto.root.old_root_id +
                           " AND CONTRACT_TYPE_ID IN (0,11)";
                        var result = dbConn.QueryFirstOrDefault<policyQry>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                        if (result != null)
                        {
                            // businessRuleHelper.p_ACCT_parent_lob_id = Convert.ToInt32(rowfields["LOB_ID"]);                               
                            p_ACCT_parent_root_id = result.root_id;
                            p_ACCT_parent_policy_id = result.id;

                            ValidateUWRules(Enums.RuleUWOperationType.Renewal);
                        }
                    }
                    else
                    {
                        switch (p_policyDto.policy.contract_type_id)
                        {
                            case (int)Enums.ContractType.OPC:
                            case (int)Enums.ContractType.PrepaidOPC:
                            case (int)Enums.ContractType.Policy:
                                ValidateUWRules(Enums.RuleUWOperationType.Policy);
                                break;
                            case (int)Enums.ContractType.Proposal:
                                ValidateUWRules(Enums.RuleUWOperationType.Proposal);
                                break;
                            case (int)Enums.ContractType.CoverNote:
                                ValidateUWRules(Enums.RuleUWOperationType.CoverNote);
                                break;
                        }
                    }

                    dbConn.Close();
                }
            }

            #endregion policies

            #region Certificates
            else
            {
                if (p_policyDto.policy.end_type != null && p_policyDto.policy.end_type != "")
                {
                    if (p_policyDto.policy.certif_flag == "A")
                    {
                        //TODO: TONY 26-JUN-2019 WE NEED TO CHANGE PARAMETERS TO HANDLE CONTRACT TYPE in addition to the operation type
                        ValidateUWRules(Enums.RuleUWOperationType.Policy);// "0");
                    }
                    else
                    {
                        var szSql =
                             " SELECT ID " +
                             " FROM UW_POLICY " +
                             " WHERE ROOT_ID = " + p_policyDto.policy.root_id +
                             " AND CERTIF_NO = " + p_policyDto.policy.certif_no +
                             " AND INSURED_ID = " + p_policyDto.policy.insured_id +
                             " AND CERTIF_FLAG = 'A' ";

                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
                            dbConn.ConnectionString = connStr;
                            dbConn.Open();

                            var iPolicyId = dbConn.QueryFirstOrDefault<int>(szSql);
                            if (iPolicyId <= 0)
                            {
                                //Case when motor policy vehicle has a change of profile endorsement.
                                //the system could not find a parent policy for the new profile
                                szSql =
                                    " SELECT " +
                                    " ID " +
                                    " FROM UW_POLICY " + // charbelas 05-august-2025 LAX-5085 wrong table name (FROM ROOT_ID)
                                    " WHERE ROOT_ID = " + p_policyDto.policy.root_id +
                                    " AND CERTIF_NO = " + p_policyDto.policy.certif_no +
                                    " AND CERTIF_FLAG IN('A','M') " +
                                    " ORDER BY ID DESC ";

                                iPolicyId = dbConn.Query<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).FirstOrDefault();
                            }

                            szSql =
                             " SELECT " +
                             " ID " +
                             ",ROOT_ID " +
                             ",CERTIF_NO " +
                             " FROM UW_POLICY " +
                             " WHERE ID = " + iPolicyId;

                            var resultPol = dbConn.QueryFirstOrDefault<policyQry>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                            if (resultPol != null)
                            {
                                //businessRuleHelper.p_ACCT_parent_lob_id = Convert.ToInt32(rowfieldsPol["LOB_ID"]);
                                p_ACCT_parent_root_id = resultPol.root_id;
                                p_ACCT_parent_policy_id = resultPol.id;
                                if (resultPol.certif_no != null)
                                {
                                    p_ACCT_parent_certif_no = Convert.ToInt32(resultPol.certif_no);
                                }

                                switch (p_policyDto.policy.end_type)
                                {
                                    case "C":
                                        ValidateUWRules(Enums.RuleUWOperationType.EndCancellation);
                                        break;
                                    case "G":
                                        ValidateUWRules(Enums.RuleUWOperationType.EndGeneral);
                                        break;
                                    case "E":
                                        ValidateUWRules(Enums.RuleUWOperationType.EndExtension);
                                        break;
                                    case "A":
                                        ValidateUWRules(Enums.RuleUWOperationType.EndReactivation);
                                        break;
                                    case "I":
                                        ValidateUWRules(Enums.RuleUWOperationType.EndReinstatement);
                                        break;
                                    case "S":
                                        ValidateUWRules(Enums.RuleUWOperationType.EndSuspension);
                                        break;
                                }
                            }

                            dbConn.Close();
                        }
                    }
                }
                else if (p_policyDto.root.old_root_id != null)
                {
                    var szSql =
                       " SELECT ID " +
                       " FROM UW_POLICY " +
                       " WHERE ROOT_ID = " + Convert.ToInt32(p_policyDto.root.old_root_id) +
                       " AND INSURED_ID = " + p_policyDto.policy.insured_id +
                       " AND CERTIF_FLAG = 'A' ";

                    using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                    {
                        dbConn.ConnectionString = connStr;
                        dbConn.Open();

                        var result = dbConn.QueryFirstOrDefault<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                        if (result > 0)
                        {
                            szSql =
                             " SELECT " +
                             " ID " +
                             ",ROOT_ID" +
                             ",CERTIF_NO " +
                             " FROM UW_POLICY " +
                             " WHERE ID = " + result;

                            var resultPol = dbConn.QueryFirstOrDefault<policyQry>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                            if (resultPol != null)
                            {
                                //businessRuleHelper.p_ACCT_parent_lob_id = Convert.ToInt32(rowfieldsPol["LOB_ID"]);
                                p_ACCT_parent_root_id = resultPol.root_id;
                                p_ACCT_parent_policy_id = resultPol.id;
                                if (resultPol.certif_no != null)
                                {
                                    p_ACCT_parent_certif_no = Convert.ToInt32(resultPol.certif_no);
                                }

                                ValidateUWRules(Enums.RuleUWOperationType.Renewal);
                            }
                        }
                        else
                        {
                            //TODO: TONY 24-AUG-2020
                            //switch (_policyDto.policy.contract_type_id)
                            //{
                            //    case (int)Enums.ContractType.Policy:
                            //        businessRuleHelper.ValidateUWRules(Enums.RuleUWOperationType.Policy);
                            //        break;
                            //    case (int)Enums.ContractType.Proposal:
                            //        businessRuleHelper.ValidateUWRules(Enums.RuleUWOperationType.Proposal);
                            //        break;
                            //    case (int)Enums.ContractType.CoverNote:
                            //        businessRuleHelper.ValidateUWRules(Enums.RuleUWOperationType.CoverNote);
                            //        break;
                            //}

                            ValidateUWRules(Enums.RuleUWOperationType.Policy);
                            //endTODO: TONY 24-AUG-2020

                        }

                        dbConn.Close();
                    }
                }
                else
                {
                    //TODO: TONY 24-AUG-2020
                    //switch (_policyDto.policy.contract_type_id)
                    //{
                    //    case (int)Enums.ContractType.Policy:
                    //        businessRuleHelper.ValidateUWRules(Enums.RuleUWOperationType.Policy);
                    //        break;
                    //    case (int)Enums.ContractType.Proposal:
                    //        businessRuleHelper.ValidateUWRules(Enums.RuleUWOperationType.Proposal);
                    //        break;
                    //    case (int)Enums.ContractType.CoverNote:
                    //        businessRuleHelper.ValidateUWRules(Enums.RuleUWOperationType.CoverNote);
                    //        break;
                    //}
                    using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                    {
                        dbConn.ConnectionString = connStr;
                        dbConn.Open();

                        var parentContractTypeId = dbConn.QueryFirstOrDefault<int>("SELECT CONTRACT_TYPE_ID FROM UW_POLICY WHERE ID = " + p_policyDto.policy.parent_policy_id);
                        if (parentContractTypeId == (int)Enums.ContractType.Proposal)
                        {
                            ValidateUWRules(Enums.RuleUWOperationType.Proposal);
                        }
                        else if (parentContractTypeId == (int)Enums.ContractType.Endorsement)
                        {
                            switch (p_policyDto.policy.end_type)
                            {
                                case "C":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndCancellation);
                                    break;
                                case "G":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndGeneral);
                                    break;
                                case "E":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndExtension);
                                    break;
                                case "A":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndReactivation);
                                    break;
                                case "I":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndReinstatement);
                                    break;
                                case "S":
                                    ValidateUWRules(Enums.RuleUWOperationType.EndSuspension);
                                    break;
                            }
                        }
                        else if (parentContractTypeId == (int)Enums.ContractType.Policy)
                        {
                            ValidateUWRules(Enums.RuleUWOperationType.Policy);
                        }

                        dbConn.Close();

                    }
                    //end TODO: TONY 24-AUG-2020
                }
            }

            #endregion Certificates

            if (p_ListAuthorityRequest.Count != 0)
            {
                foreach (var item in p_ListAuthorityRequest)
                {
                    var aop = new SEC_AUTHORITY_REQUEST();
                    aop.company_id = item.company_id;
                    aop.authority_id = item.authority_id;
                    aop.authority_scope_id = item.authority_scope_id;
                    aop.request_by = item.request_by;
                    aop.request_date = item.request_date;
                    aop.request_desc = item.request_desc;
                    aop.amount = item.amount;
                    aop.cur_id = item.cur_id;
                    aop.target_authorizer_id = item.target_authorizer_id;
                    aop.rule_id = item.rule_id;
                    aop.action_id = item.action_id;
                    aop.is_rule_valid = item.is_rule_valid;

                    p_policyDto.authority_request.Add(aop);
                }
            }
            if (p_ListAuthorityRequest_deleted.Count != 0)
            {
                if (p_policyDto.authority_request_deleted == null)
                {
                    p_policyDto.authority_request_deleted = new List<SEC_AUTHORITY_REQUEST>();
                }
                foreach (var item in p_ListAuthorityRequest_deleted)
                {
                    var aop = new SEC_AUTHORITY_REQUEST();
                    aop.id = item.id; // todo giorgio 30/4/2024 DEVIRIS5-12733
                    aop.company_id = item.company_id;
                    aop.authority_id = item.authority_id;
                    aop.authority_scope_id = item.authority_scope_id;
                    aop.request_by = item.request_by;
                    aop.request_date = item.request_date;
                    aop.request_desc = item.request_desc;
                    aop.amount = item.amount;
                    aop.cur_id = item.cur_id;
                    aop.target_authorizer_id = item.target_authorizer_id;
                    aop.rule_id = item.rule_id;
                    aop.action_id = item.action_id;
                    aop.is_rule_valid = item.is_rule_valid;
                    p_policyDto.authority_request_deleted.Add(aop);
                }
            }

            p_policyDto.policy_cover = p_policyDto.policy_cover;
            p_policyDto.policy_cover_computation = p_policyDto.policy_cover_computation;
            p_policyDto.policy_flag = p_policyDto.policy_flag;
            p_policyDto.policy_computation = p_policyDto.policy_computation;
            p_policyDto.policy_clause = p_policyDto.policy_clause;
            p_policyDto.policy_cover_scv = p_policyDto.policy_cover_scv;
            p_policyDto.policy_cover_scv_itm = p_policyDto.policy_cover_scv_itm;
            p_policyDto.policy_property = p_policyDto.policy_property;
            p_policyDto.policy_fast_track = p_policyDto.policy_fast_track;
            // _policyDto.policy_cover_disease = cRuleHelper.p_policyDto.policy_cover_disease;

            //_policyWrapper.IsNeedToLoadSmaInControls = CCAcctRules.p_IsNeedToLoadSmaInControls;

            return p_policyDto;
        }

        public Array[] ValidateUWRules(Enums.RuleUWOperationType _operationType)
        {
            Array[] result = new Array[3];//TONY and ELIASN 14-FEB-2024 DEVIRIS5-12646 Array[2]
            List<bool> response = new List<bool>();

            bool blErrorOccurred = false;
            string infoMsg = "";

            int companyId;

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                int contractTypeId;
                int lobId;
                int cobId;
                int prodId;
                DateTime dateEffective;

                //AN 2026-03-07 AIAW-714
                var coreAd = dbConn.QueryFirstOrDefault<CORE_AD>("SELECT * FROM CORE_AD");

                if (this.p_isLife)
                {
                    companyId = this.p_LifePolicyDto.root.company_id;
                    contractTypeId = this.p_LifePolicyDto.policy.contract_type_id;
                    lobId = this.p_LifePolicyDto.root.lob_id;
                    cobId = this.p_LifePolicyDto.policy.cob_id;
                    prodId = this.p_LifePolicyDto.policy.product_id;
                    dateEffective = this.p_LifePolicyDto.policy.date_effective;
                }
                else
                {
                    companyId = this.m_policyDto.root.company_id;
                    contractTypeId = this.m_policyDto.policy.contract_type_id;
                    lobId = this.m_policyDto.root.lob_id;
                    cobId = this.m_policyDto.policy.cob_id;
                    prodId = (int)this.m_policyDto.policy.prod_id;
                    dateEffective = this.m_policyDto.policy.date_effective;
                }

                if (this.m_ListRule == null || this.m_ListRule.Count == 0)
                {
                    var szRisk = "";

                    if (contractTypeId == (int)Enums.ContractType.Certificate ||
                        contractTypeId == (int)Enums.ContractType.OPC ||
                        contractTypeId == (int)Enums.ContractType.PrepaidOPC)
                    {
                        szRisk = " AND (CONTRACT_RISK = " + (int)Enums.RuleUWOperationContractRisk.Any + " OR CONTRACT_RISK = " + (int)Enums.RuleUWOperationContractRisk.Certificate + ")";
                    }
                    else
                    {
                        szRisk = " AND (CONTRACT_RISK = " + (int)Enums.RuleUWOperationContractRisk.Any + " OR CONTRACT_RISK = " + (int)Enums.RuleUWOperationContractRisk.MasterContract + ")";
                    }


                    //AN 2026-03-07 AIAW-714
                    if (this.p_isLife == false && coreAd.uw_apply_rule_action_by_prod == 1)
                    {
                        var szSqlRules =
                            " SELECT  " +
                            " UW_PROD_RULE.SORTING" +
                            ",CORE_RULE.RULE_CONDITION " +
                            ",CORE_RULE.ID" + // giorgio 17-mar-2026 IRIS5-13496
                            " FROM UW_PROD_RULE" +
                            " LEFT JOIN CORE_RULE ON  UW_PROD_RULE.RULE_ID = CORE_RULE.ID" +
                            " LEFT JOIN CORE_RULE_OPERATION ON  CORE_RULE_OPERATION.RULE_ID = CORE_RULE.ID " +

                            " WHERE UW_PROD_RULE.PROD_ID = " + prodId +
                            " AND OPERATION_TYPE = " + (int)_operationType + szRisk +
                            " AND (CORE_RULE.IS_INACTIVE = 0 OR (CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + dateEffective.ToString("yyyy/MM/dd") + "')) " +
                            " ORDER BY UW_PROD_RULE.SORTING ";

                        m_ListRule = dbConn.Query<CORE_RULE>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlRules), commandTimeout: 1200).ToList();

                        var szSqlActions =
                            " SELECT " +
                            " CORE_RULE_ACTION.* " +
                            ",CORE_TYPE.TYPE_DESC AS ACTION_DESC " +
                            ",UW_COMPUT_FRACTION.COMPUT_GROUP_ID " +

                            " FROM CORE_RULE_ACTION " +
                            " LEFT JOIN UW_PROD_RULE ON  CORE_RULE_ACTION.PROD_RULE_ID = UW_PROD_RULE.ID" +
                            " INNER JOIN CORE_RULE ON UW_PROD_RULE.RULE_ID = CORE_RULE.ID " +
                            " LEFT JOIN UW_COMPUT_FRACTION ON CORE_RULE_ACTION.COMPUT_FRACTION_ID = UW_COMPUT_FRACTION.ID  " +
                            " LEFT JOIN CORE_RULE_OPERATION ON  CORE_RULE_OPERATION.RULE_ID = CORE_RULE.ID" +
                            " INNER JOIN CORE_TYPE ON CORE_RULE_ACTION.ACTION_ID = CORE_TYPE.ID      " +

                            " WHERE UW_PROD_RULE.PROD_ID = " + +prodId +
                            " AND OPERATION_TYPE = " + (int)_operationType + szRisk +
                            " AND (CORE_RULE.IS_INACTIVE = 0 OR (CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + dateEffective.ToString("yyyy/MM/dd") + "')) " +
                            " ORDER BY CORE_RULE_ACTION.SORTING ";

                        m_ListRuleAction = dbConn.Query<CORE_RULE_ACTION>(szSqlActions, commandTimeout: 1200).ToList();
                    }
                    else    //AN 2026-03-07 AIAW-714
                    {
                        var szSqlRules =
                            " SELECT " +
                            " CORE_RULE.*  " +
                            " FROM CORE_RULE " +
                            " WHERE CORE_RULE.COMPANY_ID = " + companyId +
                            " AND (CORE_RULE.LOB_ID IS NULL OR CORE_RULE.LOB_ID = " + lobId + ")" +
                            " AND (CORE_RULE.COB_ID IS NULL OR CORE_RULE.COB_ID = " + cobId + ")" +
                            " AND (CORE_RULE.ID NOT IN (SELECT RULE_ID FROM CORE_RULE_PROD) OR CORE_RULE.ID IN (SELECT RULE_ID FROM CORE_RULE_PROD WHERE PROD_ID = " + prodId + "))" +
                            " AND CORE_RULE.ID IN (SELECT RULE_ID FROM CORE_RULE_OPERATION WHERE OPERATION_TYPE = " + (int)_operationType + szRisk + ") " +
                            " AND (CORE_RULE.IS_INACTIVE = 0 OR (CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + dateEffective.ToString("yyyy/MM/dd") + "')) " +
                            " ORDER BY CORE_RULE.SORTING ";

                        m_ListRule = dbConn.Query<CORE_RULE>(Pixel.Core.Dapper.My.AddIsolationRU(szSqlRules), commandTimeout: 1200).ToList();


                        var szSqlActions =
                           " SELECT " +
                           " CORE_RULE_ACTION.*," +
                           " CORE_TYPE.TYPE_DESC AS ACTION_DESC, " +
                           " UW_COMPUT_FRACTION.COMPUT_GROUP_ID  " +
                           " FROM CORE_RULE_ACTION " +
                           " INNER JOIN CORE_TYPE ON CORE_RULE_ACTION.ACTION_ID = CORE_TYPE.ID " +
                           " INNER JOIN CORE_RULE ON CORE_RULE_ACTION.RULE_ID = CORE_RULE.ID " +
                           //TONY 01-MAR-2022
                           //" LEFT JOIN UW_COMPUTATION_ITEM ON CORE_RULE_ACTION.COMPUTATION_ITEM_ID = UW_COMPUTATION_ITEM.ID " +
                           //" LEFT JOIN UW_COMPUT_FRACTION ON UW_COMPUTATION_ITEM.COMPUTATION_ITEM_ID = UW_COMPUT_FRACTION.ID " + 

                           " LEFT JOIN UW_COMPUT_FRACTION ON CORE_RULE_ACTION.COMPUT_FRACTION_ID = UW_COMPUT_FRACTION.ID " +
                           //AN 2025-09-24 " LEFT JOIN UW_COMPUT_FRACTION ON CORE_RULE_ACTION.COMPUTATION_ITEM_ID = UW_COMPUT_FRACTION.ID " + // in the CORE_RULE_ACTION we are using comput fraction NOT the comput item
                           //TONY 01-MAR-2022
                           " WHERE CORE_RULE.COMPANY_ID = " + companyId +
                           " AND (CORE_RULE.LOB_ID IS NULL OR CORE_RULE.LOB_ID = " + lobId + ")" +
                           " AND (CORE_RULE.COB_ID IS NULL OR CORE_RULE.COB_ID = " + cobId + ")" +
                           " AND (CORE_RULE.ID NOT IN (SELECT RULE_ID FROM CORE_RULE_PROD) OR CORE_RULE.ID IN (SELECT RULE_ID FROM CORE_RULE_PROD WHERE PROD_ID = " + prodId + "))" +
                           " AND CORE_RULE.ID IN (SELECT RULE_ID FROM CORE_RULE_OPERATION WHERE OPERATION_TYPE = " + (int)_operationType + szRisk + ") " +
                           " AND (CORE_RULE.IS_INACTIVE = 0 OR " +
                           " (CORE_RULE.IS_INACTIVE = 1 AND CORE_RULE.INACTIVATION_DATE > '" + dateEffective.ToString("yyyy/MM/dd") + "')) " +
                           " ORDER BY CORE_RULE_ACTION.SORTING ";
                        m_ListRuleAction = dbConn.Query<CORE_RULE_ACTION>(szSqlActions, commandTimeout: 1200).ToList();
                    }
                }

                if (this.m_ListSysType == null || this.m_ListSysType.Count == 0)
                {
                    m_ListSysType = dbConn.Query<CORE_TYPE>("SELECT ID, TYPE_DESC FROM CORE_TYPE WHERE TYPE_TABLE = 'BRulesActions'", commandTimeout: 1200).ToList();
                }

                dbConn.Close();
            }

            // todo giorgio 30/4/2024 DEVIRIS5-12733
            Enums.AuthorityScope businessRuleScope = new Enums.AuthorityScope();
            var lstSecAuthority = new List<SEC_AUTHORITY_REQUEST>();

            switch (_operationType)
            {
                case Enums.RuleUWOperationType.Policy:
                    businessRuleScope = Enums.AuthorityScope.BusinessRulePolicy;
                    break;
                case Enums.RuleUWOperationType.Proposal:
                    businessRuleScope = Enums.AuthorityScope.BusinessRuleProposal;
                    break;
                case Enums.RuleUWOperationType.CoverNote:
                    businessRuleScope = Enums.AuthorityScope.BusinessRuleCoverNote;
                    break;
                case Enums.RuleUWOperationType.Renewal:
                    businessRuleScope = Enums.AuthorityScope.BusinessRuleRenewalNotice;
                    break;

                // P&C end
                case Enums.RuleUWOperationType.EndGeneral:
                case Enums.RuleUWOperationType.EndCancellation:
                case Enums.RuleUWOperationType.EndSuspension:
                case Enums.RuleUWOperationType.EndExtension:
                case Enums.RuleUWOperationType.EndReactivation:
                case Enums.RuleUWOperationType.EndReinstatement:
                    businessRuleScope = Enums.AuthorityScope.BusinessRuleEnd;
                    break;

                // end specific for life
                case Enums.RuleUWOperationType.EndBoosterADHOC:
                case Enums.RuleUWOperationType.EndMarturity:
                case Enums.RuleUWOperationType.EndTotalSurrender:
                case Enums.RuleUWOperationType.EndPartialSurrender:
                    businessRuleScope = Enums.AuthorityScope.BusinessRuleEnd;
                    break;
                default:
                    break;
            }

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                lstSecAuthority = dbConn.Query<SEC_AUTHORITY_REQUEST>(
                    " SELECT * FROM SEC_AUTHORITY_REQUEST WHERE AUTHORITY_SCOPE_ID = " + (int)businessRuleScope +
                    " AND TABLE_KEY = " + (p_isLife ? p_LifePolicyDto.policy.id : m_policyDto.policy.id)).ToList();

                dbConn.Close();
            }
            // end todo giorgio 30/4/2024 DEVIRIS5-12733

            for (int i = 0; i < m_ListRule.Count; i++)
            {
                bool blSkipRule = false;
                infoMsg = "";

                var szParsedCode = this._parseTheCondition(m_ListRule.ElementAt(i).rule_condition, ref blErrorOccurred, ref infoMsg, ref blSkipRule);

                if (blSkipRule) continue;

                if (blErrorOccurred)
                {
                    this.p_ErrorOccurred = true;
                    this.p_ErrorMessage = infoMsg;

                    return result;
                }

                List<CORE_RULE_ACTION> lstActionToApply = new List<CORE_RULE_ACTION>();

                // AN - 2026-03-22 - PERFORMANCE: replaced Roslyn compilation with direct in-process evaluator.
                // See #region Rule Condition Direct Evaluator for full explanation.
                if (_evaluateParsedCondition(szParsedCode))
                {
                    //rule actions if VALID
                    lstActionToApply = m_ListRuleAction.Where(x => x.rule_id == m_ListRule.ElementAt(i).id && x.is_rule_valid == 1).ToList();
                    //lstActionToApply = m_ListRuleAction.Where(w => w.is_rule_valid == 1).ToList();
                }
                else
                {
                    //rule actions if NOT VALID
                    lstActionToApply = m_ListRuleAction.Where(x => x.rule_id == m_ListRule.ElementAt(i).id && x.is_rule_valid == 0).ToList();
                    //lstActionToApply = m_ListRuleAction.Where(w => w.is_rule_valid == 0).ToList();

                    // todo giorgio 30/4/2024 DEVIRIS5-12733
                    List<CORE_RULE_ACTION> lstAuthorizationAction = m_ListRuleAction.Where(x => x.rule_id == m_ListRule.ElementAt(i).id && x.action_id == (int)Enums.RuleAction.NeedAuthorization).ToList();

                    foreach (var authorizationActionToRemove in lstAuthorizationAction)
                    {
                        var lstSecAuthorityToDelete = lstSecAuthority.Where(x => x.rule_id == authorizationActionToRemove.rule_id);
                        if (lstSecAuthorityToDelete.Count() > 0)
                        {
                            m_ListAuthorityRequest_deleted.AddRange(lstSecAuthorityToDelete);
                        }
                    }
                    // end todo giorgio 30/4/2024 DEVIRIS5-12733
                }

                foreach (var ruleAction in lstActionToApply)
                {
                    //if (ruleAction.rule_id == m_ListRule.ElementAt(i).id)
                    //{
                    if (p_isLife)
                    {
                        this.LifeApplyRuleAction(
                            companyId,
                            p_LifePolicyDto.policy,
                            ruleAction,
                            m_ListRule.ElementAt(i).id,
                            _operationType,
                            infoMsg);
                    }
                    else
                    {
                        this.ApplyRuleAction(
                            companyId,
                            m_policyDto.policy,
                            ruleAction,
                            m_ListRule.ElementAt(i).id,
                            _operationType,
                            infoMsg);
                    }
                    //}
                }
            }

            if (p_isLife)
            {
                result[0] = this.p_LifePolicyDto.policy_action.ToArray();
            }
            else
            {
                result[0] = this.m_policyDto.policy_action.ToArray();
            }

            result[1] = this.m_ListAuthorityRequest.ToArray();
            result[2] = this.m_ListAuthorityRequest_deleted.ToArray();//TONY and ELIASN 14-FEB-2024 DEVIRIS5-12646

            return result;
        }

        #region Rule Actions 

        private void ApplyRuleAction(
            int _companyId,
            UW_POLICY _policy,
            CORE_RULE_ACTION _ruleAction,
            int _ruleId,
            Enums.RuleUWOperationType _operationType,
            string _infoMsg)
        {
            int m_baseCurId = 1;
            int m_counterCurId = 2;

            bool blActionApplied = false;

            UW_POLICY_ACTION policyAction = new UW_POLICY_ACTION();
            policyAction.policy_id = m_policyDto.policy.id;

            policyAction.rule_id = _ruleAction.rule_id;

            policyAction.action_id = _ruleAction.action_id;

            var currentAction = this.m_ListSysType.FirstOrDefault(w => w.id == _ruleAction.action_id);
            if (currentAction != null)
            {
                policyAction.message = currentAction.type_desc;
            }
            if (_ruleAction.message != "")
            {
                policyAction.message += " > " + _ruleAction.message;
            }

            if (_infoMsg != "")
            {
                policyAction.message += " | " + _infoMsg;
            }

            switch (_ruleAction.action_id) //|| //_ruleAction.action_id == (int)Enums.RuleAction.StopError
            {
                case (int)Enums.RuleAction.Warning:
                case (int)Enums.RuleAction.Errors:
                case (int)Enums.RuleAction.RemoveFromCertificateCount:
