                                case Enums.RuleUWOperationType.EndCancellation:
                                case Enums.RuleUWOperationType.EndSuspension:
                                case Enums.RuleUWOperationType.EndExtension:
                                case Enums.RuleUWOperationType.EndReactivation:
                                case Enums.RuleUWOperationType.EndReinstatement:
                                    businessRuleScope = Enums.AuthorityScope.BusinessRuleEnd;
                                    break;
                                default:
                                    break;
                            }

                            var secAuthorized = dbConn.QueryFirstOrDefault<SEC_AUTHORITY_REQUEST>(
                                " SELECT SEC_AUTHORITY_REQUEST.*" +
                                " FROM SEC_AUTHORITY_REQUEST WHERE AUTHORITY_SCOPE_ID = " + (int)businessRuleScope +
                                " AND RULE_ID = " + _ruleId +
                                " AND TABLE_KEY = " + m_policyDto.policy.id +
                                " AND IS_APPROVED = 1");

                            if (secAuthorized != null)
                            {
                                blActionApplied = true;
                            }

                            if (blActionApplied == false)
                            {
                                // todo giorgio 30/4/2024 DEVIRIS5-12733 moved to ValidateUWRules function
                                //var secAuthorityToDelete = dbConn.Query<SEC_AUTHORITY_REQUEST>(
                                //" SELECT * FROM SEC_AUTHORITY_REQUEST WHERE AUTHORITY_SCOPE_ID = " + (int)businessRuleScope +
                                //" AND RULE_ID = " + _ruleId +
                                //" AND TABLE_KEY = " + m_policyDto.policy.id).ToList();

