                                //    " AND RULE_ID = " + _ruleId +
                                //    " AND TABLE_KEY = " + m_policyDto.policy.id);

                                //this.m_AuthorizedOperationsRow = null;

                                //Create Auhorization request                                

                                //string szDate = DateTime.Today.ToString("yyyy/MM/dd");

                                //var listAuthorizer = AuthorizerHelper.GetAuthorizerList(m_company_id, m_branch_id, (int)Enums.AuthorityScope.PolicyIssuanceLimit, m_role_id, m_user_id, m_policyDto.root.lob_id);

                                //TONY 11-AUG-2021 TICKET 8849 in case the authorizer_role_id is null
                                //if (_ruleAction.authorizer_role_id != null)
                                if (_ruleAction.authorizer_roles != "" && _ruleAction.authorizer_roles != null)
                                {
                                    var szSqlAuth =
                                   " SELECT DISTINCT USER_ID AS AUTHORIZER_USER_ID " +
                                   " FROM SEC_USER_ROLE " +
                                   " INNER JOIN SEC_USER ON SEC_USER_ROLE.USER_ID = SEC_USER.ID" +//TODO - HAMZA 19/09/2023 DEVIRIS5-11380
                                   " WHERE COMPANY_ID = @companyID" +
