                                        }
                                    }
                                }

                                if (!blActionApplied)
                                {
                                    if (_ruleAction.disease_id != null)
                                    {
                                        //TODO IRIS 5 disease
                                        UW_POLICY_COVER_DISEASE e_disease = new UW_POLICY_COVER_DISEASE();

