                                        m_policyDto.policy_cover_disease.Add(e_disease);
                                    }
                                    else if (_ruleAction.sub_cover_id != null)
                                    {
                                        bool blSubCoverFound = false;
                                        for (int ii = 0; ii < m_policyDto.policy_cover_scv.Count; ii++)
                                        {
                                            if (_ruleAction.sub_cover_id == m_policyDto.policy_cover_scv.ElementAt(ii).sub_cover_id)
                                            {
