                        //TODO TONY 12-NOV-2023: we need to find a solution for the PnCComputationHelper, because it is exist in api.pnc so how to reach it?
                        //also, we need to find solution to reach LifeComputationHelper

                        // AN 2025-09-24
                        //if (_ruleAction.computation_item_id != null)
                        //{
                        //    policyAction.computation_item_id = _ruleAction.computation_item_id;
                        //}
                        if (_ruleAction.comput_fraction_id != null)
                        {
                            // giorgio 31-oct-2025 SFA-1153
                            policyAction.comput_fraction_id = _ruleAction.comput_fraction_id;
                            //policyAction.computation_item_id = _ruleAction.comput_fraction_id;
                            // giorgio 31-oct-2025 SFA-1153
                        }
                        // AN 2025-09-24

                        if (_ruleAction.cover_id != null)
                        {
                            policyAction.cover_id = _ruleAction.cover_id;
                        }
                        policyAction.pct = _ruleAction.percentage;
                        policyAction.amount = _ruleAction.amount;
                        policyAction.additive_amt = _ruleAction.additive_amt;

                        #region PnC

                        if (this.p_isLife == false)
                        {
                            m_policyDto.policy_action.Add(policyAction);

                            //AN 2025-08-21
                            CORE_OPTION coreOption = new CORE_OPTION();
                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();

                                // giorgio 31-oct-2025 SFA-1153
                                //var root = dbConn.QueryFirstOrDefault<UW_ROOT>("SELECT * FROM UW_ROOT WHERE ID = @rootId", new { rootId = m_policyDto.root.company_id });
                                //coreOption = dbConn.QueryFirstOrDefault<CORE_OPTION>("SELECT * FROM CORE_OPTION WHERE COMPANY_ID = " + root.company_id);
                                if (m_policyDto.root.company_id > 0)
                                {
                                    coreOption = dbConn.QueryFirstOrDefault<CORE_OPTION>("SELECT * FROM CORE_OPTION WHERE COMPANY_ID = " + m_policyDto.root.company_id);
                                }
                                else
                                {
                                    coreOption = dbConn.QueryFirstOrDefault<CORE_OPTION>("SELECT TOP 1 * FROM CORE_OPTION");
                                }
                                // end giorgio 31-oct-2025 SFA-1153
                            }
                            //AN 2025-08-21

                            //Action is always applied at level policy from this form
                            if (m_policyDto.root.is_group == 0 ||
                                //TONY 08-JAN-2024 added the below contract types
                                m_policyDto.policy.contract_type_id == 2 ||
                                m_policyDto.policy.contract_type_id == 4 ||
                                m_policyDto.policy.contract_type_id == 41 ||
                                m_policyDto.policy.contract_type_id == 7 ||
                                m_policyDto.policy.contract_type_id == 71
                                //TONY 08-JAN-2024
                                )
                            {
                                if (m_policyDto.policy.end_type == null ||
                                    m_policyDto.policy.end_type == "" || m_policyDto.policy.contract_type_id == 2) //Added certificates by ralph in order to apply business rules for Certs.
                                {
                                    if (_ruleAction.cover_id != null)
                                    {
                                        for (int j = 0; j < m_policyDto.policy_cover.Count; j++)
                                        {
                                            if (m_policyDto.policy_cover.ElementAt(j).cover_id == _ruleAction.cover_id)
                                            {
                                                var lst = m_policyDto.policy_cover_computation.Where(w => w.policy_cover_id == m_policyDto.policy_cover.ElementAt(j).id).ToList();
                                                if (lst.Count != 0) //Detailed Computation
                                                {
                                                    for (int k = 0; k < lst.Count; k++)
                                                    {
                                                        //AN 2025-09-24 if (lst.ElementAt(k).computation_item_id == _ruleAction.computation_item_id) 
                                                        if (lst.ElementAt(k).comput_fraction_id == _ruleAction.comput_fraction_id)
                                                        {
                                                            if (_ruleAction.percentage != 0)
                                                            {
                                                                lst.ElementAt(k).amount += Math.Round(lst.ElementAt(k).amount * (_ruleAction.percentage / 100), coreOption.decimal_places);
                                                            }
                                                            else if (_ruleAction.additive_amt != 0)
                                                            {
                                                                lst.ElementAt(k).amount += _ruleAction.additive_amt;
                                                            }
                                                            else
                                                            {
                                                                lst.ElementAt(k).amount = _ruleAction.amount;
                                                            }
                                                        }
                                                    }
                                                }
                                                else //Regular computation not detailed
                                                {
                                                    if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Total)
                                                    {
                                                        if (_ruleAction.percentage != 0)
                                                        {
                                                            m_policyDto.policy_cover.ElementAt(j).total_premium += Math.Round(m_policyDto.policy_cover.ElementAt(j).total_premium * (_ruleAction.percentage / 100), coreOption.decimal_places);
                                                            m_policyDto.policy_cover.ElementAt(j).yearly_net_premium += Math.Round(m_policyDto.policy_cover.ElementAt(j).yearly_net_premium * (_ruleAction.percentage / 100), coreOption.decimal_places);
                                                        }
                                                        else if (_ruleAction.additive_amt != 0)
                                                        {
                                                            m_policyDto.policy_cover.ElementAt(j).total_premium += _ruleAction.additive_amt;
                                                        }
                                                        else
                                                        {
                                                            m_policyDto.policy_cover.ElementAt(j).total_premium = _ruleAction.amount;
                                                            m_policyDto.policy_cover.ElementAt(j).yearly_net_premium = _ruleAction.amount;
                                                        }

                                                        //setting netPremium in cover to zero to recalculate the net from the total when change of total occurs
                                                        m_policyDto.policy_cover.ElementAt(j).net_premium = 0;
                                                        m_policyDto.policy_cover.ElementAt(j).net_premium = 0;

                                                        //Compute Total Premium of policy when action is applied by cover
                                                        //regular computation on total

                                                        decimal nTotal = 0M;
                                                        for (int i = 0; i < m_policyDto.policy_cover.Count; i++)
                                                        {
                                                            nTotal += m_policyDto.policy_cover.ElementAt(i).total_premium;
                                                        }

                                                        for (var i = 0; i < m_policyDto.policy_computation.Count; i++)
                                                        {
                                                            if (m_policyDto.policy_computation.ElementAt(i).comput_group_id == (int)Enums.ComputationsGroups.Total)
                                                            {
                                                                m_policyDto.policy_computation.ElementAt(i).amount = nTotal;

                                                                if (m_policyDto.policy.premium_cur_id == m_baseCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).base_amt = nTotal;

                                                                }
                                                                else if (m_policyDto.policy.premium_cur_id == m_counterCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).base_amt = Math.Round(nTotal * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);
                                                                }
                                                                else
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).base_amt = Math.Round(nTotal * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);
                                                                }

                                                                if (m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to != 0)
                                                                {
                                                                    if (m_policyDto.policy_computation.ElementAt(i).amount > 0)
                                                                    {
                                                                        m_policyDto.policy_computation.ElementAt(i).base_amt = Math.Ceiling(m_policyDto.policy_computation.ElementAt(i).base_amt / Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to)) * Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to);
                                                                    }
                                                                    else
                                                                    {
                                                                        m_policyDto.policy_computation.ElementAt(i).base_amt = -Math.Ceiling(m_policyDto.policy_computation.ElementAt(i).base_amt / Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to)) * Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to);
                                                                    }
                                                                }
                                                                //setting netPremium in cover to zero to recalculate the net from the total when change of total occurs


                                                                // AN 2026-01-31
                                                                if (m_policyDto.policy.premium_cur_id == m_counterCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).counter_amt = nTotal;

                                                                }
                                                                else if (m_policyDto.policy.premium_cur_id == m_baseCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).counter_amt = Math.Round(nTotal / m_policyDto.policy.base_cur_rate, coreOption.counter_cur_decimal_places);
                                                                }
                                                                else
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).counter_amt = Math.Round(nTotal / m_policyDto.policy.base_cur_rate, coreOption.counter_cur_decimal_places);
                                                                }
                                                                // AN 2026-01-31
                                                            }
                                                            else if (m_policyDto.policy_computation.ElementAt(i).comput_group_id == (int)Enums.ComputationsGroups.Net)
                                                            {
                                                                m_policyDto.policy_computation.ElementAt(i).amount = 0;
                                                            }
                                                        }

                                                        decimal nDiff = nTotal - decimal.Truncate(nTotal);

                                                        Enums.ComputationsGroups iCGroup;

                                                        decimal nValue = 0M;

                                                        Pixel.iris5.shared.pnc.PnCComputationHelper pncComputHlpr = new Pixel.iris5.shared.pnc.PnCComputationHelper();

                                                        pncComputHlpr.p_base_cur_id = m_baseCurId;
                                                        pncComputHlpr.p_counter_cur_id = m_counterCurId;
                                                        pncComputHlpr.p_decimal_places = m_decimalPlaces;
                                                        pncComputHlpr.p_base_cur_decimal_places = m_baseCurId;
                                                        pncComputHlpr.p_counter_cur_decimal_places = coreOption.counter_cur_decimal_places;

                                                        var m_list_comput_item = commonHlpr.GetComputationData(connStr, m_policyDto.policy.computation_id);

                                                        m_policyDto.policy_computation.Clear();
                                                        foreach (var computItm in m_list_comput_item)
                                                        {
                                                            var polComput = new UW_POLICY_COMPUTATION();

                                                            iCGroup = (Enums.ComputationsGroups)computItm.comput_group_id;
                                                            polComput.comput_group_id = computItm.comput_group_id;
                                                            polComput.item_sorting = computItm.item_sorting;
                                                            polComput.is_accept_rounding_diff = computItm.is_accept_rounding_diff;
                                                            polComput.is_accept_tax_exemption = computItm.is_accept_tax_exemption;
                                                            polComput.is_applied_once_per_group = computItm.is_applied_once_per_group;
                                                            polComput.is_applied_only_on_new_renew = computItm.is_applied_only_on_new_renew; // CharbelAs 09-Jan-2026 AIAW-191
                                                            //TONY 11-APR-2023
                                                            //pol_computation.is_applied_on_certificate_only = computItm.is_applied_on_certificate_only;
                                                            polComput.base_cur_rounded_to = computItm.base_cur_rounded_to;
                                                            polComput.computation_item_id = computItm.id;
                                                            polComput.comput_fraction_id = computItm.comput_fraction_id;
                                                            polComput.comput_fraction_desc = computItm.comput_fraction_desc;
                                                            polComput.tax_refund_period = computItm.tax_refund_period;

                                                            if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Certificate)
                                                            {
                                                                polComput.amount = 0;
                                                                polComput.base_amt = 0;
                                                                polComput.counter_amt = 0; // AN 2026-01-31
                                                            }
                                                            else
                                                            {
                                                                if (Pixel.Core.Lib.CoreHelper.IsNumeric(computItm.formula))
                                                                {
                                                                    if (computItm.cur_id == null)
                                                                    {
                                                                    }
                                                                    else
                                                                    {
                                                                        if (computItm.is_per_copy == 1)
                                                                        {
                                                                            nValue = Convert.ToDecimal(computItm.formula) * m_policyDto.policy.print_copies;
                                                                        }
                                                                        else
                                                                        {
                                                                            nValue = Convert.ToDecimal(computItm.formula);
                                                                        }

                                                                        if (Convert.ToInt32(computItm.cur_id) == m_baseCurId)
                                                                        {
                                                                            polComput.base_amt = nValue;

                                                                            // AN 2026-01-31
                                                                            polComput.counter_amt = Helper.ConvertAmount(
                                                                                                                            connStr,
                                                                                                                            nValue,
                                                                                                                            Convert.ToInt32(polComput.cur_id),
                                                                                                                            m_policyDto.policy.date_issue,
                                                                                                                            m_counterCurId, coreOption.counter_cur_decimal_places);
                                                                            // AN 2026-01-31
                                                                        }
                                                                        else if (Convert.ToInt32(computItm.cur_id) == m_counterCurId)
                                                                        {
                                                                            polComput.base_amt = Helper.ConvertAmount(connStr,
                                                                                                                            nValue,
                                                                                                                            Convert.ToInt32(computItm.cur_id),
                                                                                                                            m_policyDto.policy.date_issue,
                                                                                                                            m_baseCurId, coreOption.base_cur_decimal_places);
                                                                            polComput.counter_amt = nValue; // AN 2026-01-31
                                                                        }

                                                                        if (Convert.ToInt32(computItm.cur_id) != m_policyDto.policy.premium_cur_id)
                                                                        {
                                                                            nValue = Helper.ConvertAmount(connStr,
                                                                                                           nValue,
                                                                                                           Convert.ToInt32(computItm.cur_id),
                                                                                                           m_policyDto.policy.date_issue,
                                                                                                           m_policyDto.policy.premium_cur_id, coreOption.decimal_places);
                                                                        }
                                                                        polComput.amount = nValue;
                                                                    }
                                                                }
                                                            }
                                                        }

                                                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                                                        {
                                                            dbConn.ConnectionString = connStr;
                                                            dbConn.Open();

                                                            var szSql = "SELECT FROM UW_COB WHERE ID = " + m_policyDto.policy.cob_id;

                                                            var resultCob = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();

                                                            dbConn.Close();

                                                            if (resultCob != null)
                                                            {
                                                                var rowfieldsCob = resultCob as IDictionary<string, object>;

                                                                this.m_fraction_subtructed_from_total = Convert.ToDecimal(rowfieldsCob["FRACTION_SUBTRACTED_FROM_TOTAL"]);
                                                                this.m_fraction_added_to_total = Convert.ToDecimal(rowfieldsCob["FRACTION_SUBTRACTED_FROM_TOTAL"]);

                                                                if (nDiff <= m_fraction_subtructed_from_total &&
                                                                m_fraction_subtructed_from_total != 0)
                                                                {
                                                                    nTotal -= nDiff;
                                                                }
                                                                else if (nDiff >= (1 - this.m_fraction_added_to_total) &&
                                                                         nDiff < 1M && this.m_fraction_added_to_total != 0)
                                                                {
                                                                    nTotal += (1 - nDiff);
                                                                }
                                                            }
                                                        }

                                                        pncComputHlpr.ComputeNetPremium(
                                                            connStr,
                                                            _policy,
                                                            m_policyDto.policy_computation,
                                                            //TODO: 25-NOV-2020 tony commented out _listComputationItem
                                                            //m_list_comput_item,
                                                            nTotal,
                                                            Convert.ToBoolean(m_policyDto.root.is_acceptance),
                                                            Convert.ToBoolean(m_policyDto.root.is_leader)
                                                            );

                                                        pncComputHlpr.PremiumBalancer(
                                                            connStr,
                                                            _policy,
                                                            m_policyDto.policy_computation,
                                                            //TODO: 25-NOV-2020 tony commented out _listComputationItem
                                                            //m_list_comput_item,
                                                            nTotal,
                                                            Convert.ToBoolean(m_policyDto.root.is_acceptance),
                                                            Convert.ToBoolean(m_policyDto.root.is_leader)
                                                                );
                                                    }
                                                    else if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Net)
                                                    {
                                                        if (_ruleAction.percentage != 0)
                                                        {
                                                            m_policyDto.policy_cover.ElementAt(j).net_premium += Math.Round(m_policyDto.policy_cover.ElementAt(j).net_premium * (_ruleAction.percentage / 100), coreOption.decimal_places);

                                                            m_policyDto.policy_cover.ElementAt(j).yearly_net_premium += Math.Round(m_policyDto.policy_cover.ElementAt(j).net_premium * (_ruleAction.percentage / 100), coreOption.decimal_places);
                                                        }
                                                        else if (_ruleAction.additive_amt != 0)
                                                        {
                                                            m_policyDto.policy_cover.ElementAt(j).net_premium += _ruleAction.additive_amt;
                                                        }
                                                        else
                                                        {
                                                            m_policyDto.policy_cover.ElementAt(j).net_premium = _ruleAction.amount;
                                                            m_policyDto.policy_cover.ElementAt(j).yearly_net_premium = _ruleAction.amount;
                                                        }

                                                        //Compute Net Premium of policy when action is applied by cover
                                                        //regular computation on Net

                                                        decimal nNet = 0M;
                                                        for (var i = 0; i < m_policyDto.policy_cover.Count; i++)
                                                        {
                                                            nNet += m_policyDto.policy_cover.ElementAt(i).net_premium;
                                                        }

                                                        for (var i = 0; i < m_policyDto.policy_computation.Count; i++)
                                                        {
                                                            if (m_policyDto.policy_computation.ElementAt(i).comput_group_id == (int)Enums.ComputationsGroups.Net)
                                                            {
                                                                m_policyDto.policy_computation.ElementAt(i).amount = nNet;

                                                                if (m_policyDto.policy.premium_cur_id == m_baseCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).base_amt = nNet;
                                                                }
                                                                else if (m_policyDto.policy.premium_cur_id == m_counterCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).base_amt = Math.Round(nNet * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);
                                                                }
                                                                else
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).base_amt = Math.Round(nNet * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);
                                                                }

                                                                if (m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to != 0)
                                                                {
                                                                    if (m_policyDto.policy_computation.ElementAt(i).amount > 0)
                                                                    {
                                                                        m_policyDto.policy_computation.ElementAt(i).base_amt = Math.Ceiling(m_policyDto.policy_computation.ElementAt(i).base_amt / Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to)) * Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to);
                                                                    }
                                                                    else
                                                                    {
                                                                        m_policyDto.policy_computation.ElementAt(i).base_amt = -Math.Ceiling(m_policyDto.policy_computation.ElementAt(i).base_amt / Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to)) * Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).base_cur_rounded_to);
                                                                    }
                                                                }

                                                                // AN 2026-01-31
                                                                if (m_policyDto.policy.premium_cur_id == m_counterCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).counter_amt = nNet;
                                                                }
                                                                else if (m_policyDto.policy.premium_cur_id == m_baseCurId)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).counter_amt = Math.Round(nNet / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);
                                                                }
                                                                else
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).counter_amt = Math.Round(nNet / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);
                                                                }
                                                                // AN 2026-01-31
                                                            }
                                                        }

                                                        //TODO: IRIS5 need to changed to logic from grid to LIST
                                                        Enums.ComputationsGroups iCGroup;
                                                        decimal nValue = 0M;

                                                        PnCComputationHelper pncComputHlp = new PnCComputationHelper();
                                                        pncComputHlp.p_base_cur_id = m_baseCurId;
                                                        pncComputHlp.p_counter_cur_id = m_counterCurId;

                                                        var computationItems = commonHlpr.GetComputationData(connStr, m_policyDto.policy.computation_id);
                                                        m_policyDto.policy_computation.Clear();

                                                        foreach (var computItem in computationItems)
                                                        {
                                                            var pol_computation = new UW_POLICY_COMPUTATION();

                                                            iCGroup = (Enums.ComputationsGroups)computItem.comput_group_id;
                                                            pol_computation.comput_group_id = computItem.comput_group_id;
                                                            pol_computation.item_sorting = computItem.item_sorting;
                                                            pol_computation.is_accept_rounding_diff = computItem.is_accept_rounding_diff;
                                                            pol_computation.is_accept_tax_exemption = computItem.is_accept_tax_exemption;
                                                            pol_computation.is_applied_once_per_group = computItem.is_applied_once_per_group;
                                                            pol_computation.is_applied_only_on_new_renew = computItem.is_applied_only_on_new_renew; // CharbelAs 09-Jan-2026 AIAW-191
                                                            //TONY 11-APR-2023
                                                            //pol_computation.is_applied_on_certificate_only = computItem.is_applied_on_certificate_only;
                                                            pol_computation.base_cur_rounded_to = computItem.base_cur_rounded_to;
                                                            pol_computation.computation_item_id = computItem.id;
                                                            pol_computation.comput_fraction_desc = computItem.comput_fraction_desc;
                                                            pol_computation.comput_fraction_id = computItem.comput_fraction_id;
                                                            pol_computation.tax_refund_period = computItem.tax_refund_period;
                                                            pol_computation.formula = computItem.formula; //08-JAn-2024

                                                            if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Certificate)// ||
                                                                                                                                           //m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Shipment)
                                                            {
                                                                pol_computation.amount = 0;
                                                                pol_computation.base_amt = 0;
                                                                pol_computation.counter_amt = 0;
                                                            }
                                                            else
                                                            {
                                                                if (Pixel.Core.Lib.CoreHelper.IsNumeric(computItem.formula))
                                                                {
                                                                    if (computItem.cur_id == null)
                                                                    {
                                                                        //MessageBox.Show("Currency is not specified for component : " + oDsComputationRules.UW_ComputationRules.Rows(jj)["ComputationRuleDesc"], string.Empty, MessageBoxButtons.OK, MessageBoxIcon.Error);
                                                                    }
                                                                    else
                                                                    {
                                                                        if (computItem.is_per_copy == 1)
                                                                        {
                                                                            nValue = Convert.ToDecimal(computItem.formula) * m_policyDto.policy.print_copies;
                                                                        }
                                                                        else
                                                                        {
                                                                            nValue = Convert.ToDecimal(computItem.formula);
                                                                        }

                                                                        if (Convert.ToInt32(computItem.cur_id) == m_baseCurId)
                                                                        {
                                                                            pol_computation.base_amt = nValue;
                                                                            pol_computation.counter_amt = Helper.ConvertAmount(connStr,
                                                                                                                                nValue,
                                                                                                                                Convert.ToInt32(computItem.cur_id),
                                                                                                                                m_policyDto.policy.date_issue,
                                                                                                                                m_counterCurId, coreOption.counter_cur_decimal_places);

                                                                        }
                                                                        else if (Convert.ToInt32(computItem.cur_id) == m_counterCurId)
                                                                        {
                                                                            pol_computation.base_amt = Helper.ConvertAmount(connStr,
                                                                                                                            nValue,
                                                                                                                            Convert.ToInt32(computItem.cur_id),
                                                                                                                            m_policyDto.policy.date_issue,
                                                                                                                            m_baseCurId, coreOption.base_cur_decimal_places);

                                                                            pol_computation.counter_amt = nValue;
                                                                        }
                                                                        if (Convert.ToInt32(computItem.cur_id) != m_policyDto.policy.premium_cur_id)
                                                                        {
                                                                            nValue = Helper.ConvertAmount(connStr,
                                                                                                            nValue,
                                                                                                            Convert.ToInt32(computItem.cur_id),
                                                                                                            m_policyDto.policy.date_issue,
                                                                                                            m_policyDto.policy.premium_cur_id,
                                                                                                            coreOption.decimal_places);
                                                                        }
                                                                        pol_computation.amount = nValue;
                                                                    }
                                                                }
                                                            }

                                                            m_policyDto.policy_computation.Add(pol_computation);

                                                        }

                                                        pncComputHlp.PerformCalculationOnAllComponents(
                                                            connStr,
                                                            _policy,
                                                            m_policyDto.policy_computation,
                                                            -1,
                                                            -1,
                                                            false,
                                                            Convert.ToBoolean(m_policyDto.root.is_acceptance),
                                                            Convert.ToBoolean(m_policyDto.root.is_leader));
 
                                                        for (var i = 0; i < m_policyDto.policy_computation.Count; i++)
                                                        {
                                                            if (Convert.ToInt32(m_policyDto.policy_computation.ElementAt(i).comput_group_id) == (int)Enums.ComputationsGroups.Total)
                                                            {
                                                                decimal nDiff = m_policyDto.policy_computation.ElementAt(i).amount - decimal.Truncate(m_policyDto.policy_computation.ElementAt(i).amount);

                                                                if (nDiff <= this.m_fraction_subtructed_from_total &&
                                                                    this.m_fraction_subtructed_from_total != 0)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).amount -= nDiff;

                                                                    pncComputHlp.PremiumBalancer(
                                                                        connStr,
                                                                        _policy,
                                                                        m_policyDto.policy_computation,
                                                                        //TODO: 25-NOV-2020 tony commented out _listComputationItem
                                                                        //m_list_COMPUTATION_ITEM,
                                                                        m_policyDto.policy_computation.ElementAt(i).amount,
                                                                        Convert.ToBoolean(m_policyDto.root.is_acceptance),
                                                                        Convert.ToBoolean(m_policyDto.root.is_leader));

                                                                    //m_policyDto.policy.counter_cur_rate,
                                                                    //m_policyDto.policy.contract_type_id);

                                                                }
                                                                else if (nDiff >= (1 - this.m_fraction_added_to_total) && nDiff < 1M &&
                                                                         this.m_fraction_added_to_total != 0)
                                                                {
                                                                    m_policyDto.policy_computation.ElementAt(i).amount += (1 - nDiff);

                                                                    pncComputHlp.PremiumBalancer(
                                                                        connStr,
                                                                        _policy,
                                                                        m_policyDto.policy_computation,
                                                                        //TODO: 25-NOV-2020 tony commented out _listComputationItem
                                                                        //m_list_COMPUTATION_ITEM,
                                                                        m_policyDto.policy_computation.ElementAt(i).amount,
                                                                        Convert.ToBoolean(m_policyDto.root.is_acceptance),
                                                                        Convert.ToBoolean(m_policyDto.root.is_leader));
                                                                    //m_policyDto.policy.counter_cur_rate, 
                                                                    //m_policyDto.policy.contract_type_id);
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    else //No covers found, changes are applied to PolicyComputation
                                    {
                                        //Changes are applied on discount fraction of the policy computation
                                        for (int k = 0; k < m_policyDto.policy_computation.Count; k++)
                                        {
                                            if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Discount &&

                                                //AN 2025-09-24
                                                m_policyDto.policy_computation.ElementAt(k).comput_fraction_id == _ruleAction.comput_fraction_id)
                                            //m_policyDto.policy_computation.ElementAt(k).computation_item_id == _ruleAction.computation_item_id)
                                            {
                                                if (_ruleAction.percentage != 0)
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount += Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * (_ruleAction.percentage / 100), coreOption.decimal_places);

                                                }
                                                else if (_ruleAction.additive_amt != 0)
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount += _ruleAction.additive_amt;
                                                }
                                                else
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount = _ruleAction.amount;
                                                }

                                                m_policyDto.policy_computation.ElementAt(k).base_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);

                                                //AN 2026-01-31
                                                m_policyDto.policy_computation.ElementAt(k).counter_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);
                                            }
                                            else if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Charges
                                                && m_policyDto.policy_computation.ElementAt(k).comput_fraction_id == _ruleAction.comput_fraction_id)
                                            //  && m_policyDto.policy.is_cover_rate_on_net == 1) // Removed by ralph in order to apply TPA Fees 
                                            {
                                                if (_ruleAction.percentage != 0)
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount += Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * (_ruleAction.percentage / 100), coreOption.decimal_places);

                                                }
                                                else if (_ruleAction.additive_amt != 0)
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount += _ruleAction.additive_amt;
                                                }
                                                else
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount = _ruleAction.amount;
                                                }

                                                m_policyDto.policy_computation.ElementAt(k).base_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);

                                                //AN 2026-01-31
                                                m_policyDto.policy_computation.ElementAt(k).counter_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);
                                            }
                                            // giorgio 31-oct-2025 SFA-1153
                                            else if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Taxes &&
                                                m_policyDto.policy_computation.ElementAt(k).comput_fraction_id == _ruleAction.comput_fraction_id)
                                            {
                                                if (_ruleAction.percentage != 0)
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount += Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * (_ruleAction.percentage / 100), coreOption.decimal_places);

                                                }
                                                else if (_ruleAction.additive_amt != 0)
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount += _ruleAction.additive_amt;
                                                }
                                                else
                                                {
                                                    m_policyDto.policy_computation.ElementAt(k).amount = _ruleAction.amount;
                                                }

                                                m_policyDto.policy_computation.ElementAt(k).base_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);

                                                //AN 2026-01-31
                                                m_policyDto.policy_computation.ElementAt(k).counter_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);
                                            }
                                            // end giorgio 31-oct-2025 SFA-1153
                                        }
                                    }
                                }
                            }
                            else //Policy is Group
                            {
                                //Fraction should only be applied if no cover is specified and to Discount fraction only to not to affect Policy premiums
                                for (int k = 0; k < m_policyDto.policy_computation.Count; k++)
                                {
                                    if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Discount &&
                                        //AN 2025-09-24
                                        m_policyDto.policy_computation.ElementAt(k).comput_fraction_id == _ruleAction.comput_fraction_id)
                                    //m_policyDto.policy_computation.ElementAt(k).computation_item_id == _ruleAction.computation_item_id)
                                    {
                                        if (_ruleAction.percentage != 0)
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount += Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * (_ruleAction.percentage / 100), coreOption.decimal_places);
                                        }
                                        else if (_ruleAction.additive_amt != 0)
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount += _ruleAction.additive_amt;
                                        }
                                        else
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount = _ruleAction.amount;
                                        }

                                        m_policyDto.policy_computation.ElementAt(k).base_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);

                                        //AN 2026-01-31
                                        m_policyDto.policy_computation.ElementAt(k).counter_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);
                                    }
                                    else if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Charges &&

                                        //AN 2025-09-24
                                        m_policyDto.policy_computation.ElementAt(k).comput_fraction_id == _ruleAction.comput_fraction_id)
                                    //m_policyDto.policy_computation.ElementAt(k).computation_item_id == _ruleAction.computation_item_id)
                                    {
                                        if (_ruleAction.percentage != 0)
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount += Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * (_ruleAction.percentage / 100), coreOption.decimal_places);
                                        }
                                        else if (_ruleAction.additive_amt != 0)
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount += _ruleAction.additive_amt;
                                        }
                                        else
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount = _ruleAction.amount;
                                        }

                                        m_policyDto.policy_computation.ElementAt(k).base_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);

                                        //AN 2026-01-31
                                        m_policyDto.policy_computation.ElementAt(k).counter_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);

                                    }
                                    // giorgio 31-oct-2025 SFA-1153
                                    else if (_ruleAction.comput_group_id == (int)Enums.ComputationsGroups.Taxes && m_policyDto.policy_computation.ElementAt(k).comput_fraction_id == _ruleAction.comput_fraction_id)
                                    {
                                        if (_ruleAction.percentage != 0)
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount += Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * (_ruleAction.percentage / 100), coreOption.decimal_places);

                                        }
                                        else if (_ruleAction.additive_amt != 0)
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount += _ruleAction.additive_amt;
                                        }
                                        else
                                        {
                                            m_policyDto.policy_computation.ElementAt(k).amount = _ruleAction.amount;
                                        }

                                        m_policyDto.policy_computation.ElementAt(k).base_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount * m_policyDto.policy.base_cur_rate, coreOption.base_cur_decimal_places);

                                        //AN 2026-01-31
                                        m_policyDto.policy_computation.ElementAt(k).counter_amt = Math.Round(m_policyDto.policy_computation.ElementAt(k).amount / m_policyDto.policy.counter_cur_rate, coreOption.counter_cur_decimal_places);

                                    }
                                    // end giorgio 31-oct-2025 SFA-1153
                                }
