                        break;
                    }

                case (int)Enums.RuleAction.ApplyLoading:
                    {
                        var szSql =
                            " SELECT " +
                            " TOP 1 LOADING_FACTOR " +
                            " FROM UW_MEDICAL_FILE " +
                            " WHERE UW_MEDICAL_FILE.INSURED_ID = " + m_policyDto.policy.insured_id +
                            " AND UW_MEDICAL_FILE.LOB_ID = " + m_policyDto.root.lob_id +
                            " ORDER BY UW_MEDICAL_FILE.START_DATE DESC, UW_MEDICAL_FILE.ID DESC ";

                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
                            dbConn.ConnectionString = connStr;
                            dbConn.Open();

                            var result = dbConn.QueryFirstOrDefault<decimal>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);

                            dbConn.Close();

                            if (result > 0)
                            {
                                policyAction.pct = result;
                            }
                            else
                            {
                                policyAction.pct = -1;
                            }

                            //AN 2025-09-24
                            if (_ruleAction.comput_fraction_id != null)
                            {
                                // giorgio 31-oct-2025 SFA-1153
                                policyAction.comput_fraction_id = _ruleAction.comput_fraction_id;
                                //policyAction.computation_item_id = _ruleAction.comput_fraction_id;
                                // giorgio 31-oct-2025 SFA-1153
                            }
                            //if (_ruleAction.computation_item_id != null)
                            //{
                            //    policyAction.computation_item_id = _ruleAction.computation_item_id;
                            //}
                            //AN 2025-09-24

                            if (_ruleAction.cover_id != null)
                            {
                                policyAction.cover_id = _ruleAction.cover_id;
                            }

                            m_policyDto.policy_action.Add(policyAction);
                        }

                        break;
                    }

                case (int)Enums.RuleAction.AppendClause:
                    {
                        for (int i = 0; i < m_policyDto.policy_clause.Count; i++)
                        {
                            if (m_policyDto.policy_clause.ElementAt(i).clause_id == _ruleAction.clause_id)
                            {
                                m_policyDto.policy_action.Add(policyAction);

                                blActionApplied = true;
                                break;
                            }
                        }

                        if (!blActionApplied)
                        {
                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();
                                //TODO: Elie BA - 02/NOV/2020 - add CLAUSE_TYPE_DESC to query
                                var clause = dbConn.QueryFirstOrDefault<UW_CLAUSE>(@"SELECT
                                                                                        CLAUSE_CODE,
                                                                                        CLAUSE_DESC,
                                                                                        CLAUSE_CONTENT,
                                                                                        IS_CHANGEABLE,
                                                                                        CORE_TYPE.TYPE_DESC AS CLAUSE_TYPE_DESC
                                                                                    FROM UW_CLAUSE
                                                                                    LEFT JOIN CORE_TYPE ON UW_CLAUSE.CLAUSE_TYPE_ID = CORE_TYPE.ID
                                                                                    WHERE UW_CLAUSE.ID = " + _ruleAction.clause_id);

                                dbConn.Close();

                                UW_POLICY_CLAUSE policyClause = new UW_POLICY_CLAUSE();

                                policyClause.policy_id = m_policyDto.policy.id;
                                policyClause.clause_id = _ruleAction.clause_id;
                                policyClause.clause_desc = clause.clause_desc;
                                policyClause.clause_content = clause.clause_content;
                                policyClause.is_changeable = clause.is_changeable;
                                policyClause.clause_type_desc = clause.clause_type_desc;
                                //policyClause.IS_EXCLUSION = oDsClauses.UW_Clauses.Rows(0)["IS_EXCLUSION"];

                                m_policyDto.policy_clause.Add(policyClause);

                                m_policyDto.policy_action.Add(policyAction);
                            }
                        }

                        break;
                    }

                case (int)Enums.RuleAction.DeleteClause:
                    {
                        blActionApplied = true;
                        for (int i = 0; i < m_policyDto.policy_clause.Count; i++)
                        {
                            if (m_policyDto.policy_clause.ElementAt(i).clause_id == Convert.ToInt32(_ruleAction.clause_id))
                            {
                                blActionApplied = false;
                                break;
                            }
                        }

                        if (!blActionApplied)
                        {
                            for (int i = m_policyDto.policy_clause.Count - 1; i >= 0; i--)
                            {
                                if (m_policyDto.policy_clause.ElementAt(i).clause_id == Convert.ToInt32(_ruleAction.clause_id))
                                {
                                    m_policyDto.policy_clause.RemoveAt(i);
                                }
                            }

                            m_policyDto.policy_action.Add(policyAction);
                        }

                        break;
                    }

                //TONY just for testing
                case (int)Enums.RuleAction.AppendCover:
                    {
                        for (int i = 0; i < m_policyDto.policy_cover.Count; i++)
                        {
                            if (m_policyDto.policy_cover.ElementAt(i).cover_id == _ruleAction.cover_id)
                            {
                                m_policyDto.policy_action.Add(policyAction);

                                blActionApplied = true;
                                break;
                            }
                        }

                        if (!blActionApplied)
                        {
                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();
                                var cover = dbConn.QueryFirstOrDefault<UW_COVER>("SELECT" +
                                                                                 "     UW_COVER.*" +
                                                                                 " FROM UW_COVER" +
                                                                                 " WHERE ID = " + _ruleAction.cover_id);

                                dbConn.Close();

                                UW_POLICY_COVER policyCover = new UW_POLICY_COVER();
                                policyCover.policy_id = m_policyDto.policy.id;
                                policyCover.cover_id = (int)_ruleAction.cover_id;
                                policyCover.cover_code = cover.cover_code;
                                policyCover.cover_desc = cover.cover_desc;
                                policyCover.net_premium = 0;
                                policyCover.effective_date = m_policyDto.policy.date_effective;
                                policyCover.expiry_date = m_policyDto.policy.date_expiry;
                                m_policyDto.policy_cover.Add(policyCover);

                                m_policyDto.policy_action.Add(policyAction);
                            }
                        }

                        break;
                    }

                case (int)Enums.RuleAction.CalculateGRBalance:
                    {
                        if (m_policyDto.root.old_root_id != null)
                        {
                            var szSqlCover =
                               " SELECT " +
                               " ID, " +
                               " COVER_CATEGORY_ID " +
                               " FROM UW_COVER " +
                               " WHERE ID =" + _ruleAction.cover_id;

                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();

                                var resultCover = dbConn.Query<UW_COVER>(szSqlCover, commandTimeout: 1200).FirstOrDefault();

                                if (resultCover != null)
                                {
                                    //var rowfieldsCover = resultCover as IDictionary<string, object>; // giorgio 26-mar-2026 BNK-534 - replaced with dapper mapping

                                    var szSqlGrBal =
                                       " SELECT " +
                                       //" UW_POLICY_COVER.GR_BALANCE, " +
                                       " 0.00 AS GR_BALANCE, " +
                                       " CL_CLAIM_ASSESSMENT.VISA_ACTUAL_LOS " +
                                       " FROM CL_CLAIM_ASSESSMENT " +
                                       " LEFT JOIN CL_CLAIM ON CL_CLAIM_ASSESSMENT.CLAIM_ID = CL_CLAIM.ID " +
                                       " LEFT JOIN UW_POLICY ON CL_CLAIM.POLICY_ID = UW_POLICY.ID  " +
                                       " LEFT JOIN UW_COVER ON CL_CLAIM_ASSESSMENT.COVER_ID = UW_COVER.ID " + // giorgio 26-mar-2026 BNK-534
                                       " LEFT JOIN UW_POLICY_COVER ON UW_POLICY.ID = UW_POLICY_COVER.POLICY_ID " +
                                       "     AND UW_POLICY_COVER.COVER_ID = CL_CLAIM_ASSESSMENT.COVER_ID " +
                                       " WHERE UW_POLICY.ROOT_ID = " + m_policyDto.root.old_root_id +
                                       " AND UW_POLICY.INSURED_ID = " + m_policyDto.policy.insured_id +
                                       " AND UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                                       " AND UW_POLICY.CERTIF_FLAG = 'A' " +
                                       // giorgio 26-mar-2026 BNK-534
                                       //" AND CL_CLAIM_ASSESSMENT.COVER_ID IN " +
                                       //" (SELECT COVER_ID FROM UW_COVER WHERE COVER_CATEGORY_ID = " + rowfieldsCover["COVER_CATEGORY_ID"] + ") ";
                                       " AND UW_COVER.COVER_CATEGORY_ID = " + resultCover.cover_category_id;
                                        // end giorgio 26-mar-2026 BNK-534

                                    var resultGrBal = dbConn.Query(szSqlGrBal, commandTimeout: 1200).FirstOrDefault();
                                    if (resultGrBal != null && resultGrBal.Count() > 0)
                                    {
                                        decimal nGR_BALANCE = 0M;

                                        for (int i = 0; i < resultGrBal.Count(); i++)
                                        {
                                            var rowfields = resultGrBal[i] as IDictionary<string, object>;

                                            if (i == 0)
                                            {
                                                nGR_BALANCE = Convert.ToDecimal(rowfields["GR_BALANCE"]);
                                                nGR_BALANCE -= Convert.ToDecimal(rowfields["VISA_ACTUAL_LOS"]);
                                            }
                                            else
                                            {
                                                nGR_BALANCE -= Convert.ToDecimal(rowfields["VISA_ACTUAL_LOS"]);
                                            }
                                        }

                                        for (int i = 0; i < m_policyDto.policy_cover.Count; i++)
                                        {
                                            if (m_policyDto.policy_cover.ElementAt(i).cover_id == _ruleAction.cover_id)
                                            {
                                                //TODO: move this to insured
                                                // m_policyDto.policy_cover.ElementAt(i).gr_balance = nGR_BALANCE;
                                            }
                                        }

                                        m_policyDto.policy_action.Add(policyAction);
                                    }
                                }

                                dbConn.Close();
                            }
                        }

                        break;
                    }

                case (int)Enums.RuleAction.CalculateGRBalance_PolicyAndLinkedPolicies:
                    {
                        if (m_policyDto.root.old_root_id != null)
                        {
                            var szSqlCover =
                                "SELECT " +
                                "ID, " +
                                "COVER_CATEGORY_ID " +
                                "FROM UW_COVER " +
                                " WHERE ID =" + _ruleAction.cover_id;

                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();

                                var resultCover = dbConn.Query(szSqlCover, commandTimeout: 1200).FirstOrDefault();
                                if (resultCover != null)
                                {
                                    var rowfieldsCover = resultCover as IDictionary<string, object>;

                                    var szSqlLinked =
                                      "SELECT " +
                                      "oldPolicy.LINKED_POLICY_ID " +
                                      "FROM UW_POLICY oldPolicy " +
                                      "INNER JOIN UW_ROOT oldRoot ON oldPolicy.ROOT_ID = oldRoot.ID " +
                                      "INNER JOIN UW_ROOT ON oldRoot.NEW_ROOT_ID = UW_ROOT.ID " +
                                      "INNER JOIN UW_POLICY ON UW_ROOT.ID = UW_POLICY.ROOT_ID " +
                                      "      AND UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                                      "      AND UW_POLICY.CERTIF_FLAG = 'A' " +
                                      "	   AND UW_POLICY.INSURED_ID = " + m_policyDto.policy.insured_id +
                                      "	   AND UW_POLICY.ID = " + m_policyDto.policy.id +
                                      " WHERE oldPolicy.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                                      " AND oldPolicy.CERTIF_FLAG = 'A' ";

                                    var resultLinked = dbConn.Query(szSqlLinked, commandTimeout: 1200).FirstOrDefault();
                                    if (resultLinked != null && resultLinked.Count > 0)
                                    {
                                        var rowfieldsLinked = resultLinked as IDictionary<string, object>;

                                        if (!(rowfieldsLinked["LINKED_POLICY_ID"] == null))
                                        {
                                            var szSqlGrBal =
                                              " SELECT " +
                                              " GR_BALANCE " +
                                              " FROM UW_POLICY_COVER " +
                                              " LEFT JOIN UW_COVER ON UW_POLICY_COVER.COVER_ID = UW_COVER.ID " +
                                              " WHERE UW_POLICY_COVER.POLICY_ID = " + rowfieldsLinked["LINKED_POLICY_ID"] +
                                              " AND UW_COVER.COVER_CATEGORY_ID = " + rowfieldsCover["COVER_CATEGORY_ID"] +
                                              " AND UW_POLICY_COVER.IS_GR = 1 ";

                                            var resultGrBal = dbConn.Query(szSqlGrBal, commandTimeout: 1200).FirstOrDefault();

                                            var szSqlClaim =
                                                " SELECT " +
                                                //" UW_POLICY_COVER.GR_BALANCE, " +
                                                " 0.00 AS GR_BALANCE, " +
                                                " CL_CLAIM_ASSESSMENT.VISA_ACTUAL_LOS " +
                                                " FROM CL_CLAIM_ASSESSMENT " +
                                                " LEFT JOIN CL_CLAIM ON CL_CLAIM_ASSESSMENT.CLAIM_ID = CL_CLAIM.ID " +
                                                " LEFT JOIN UW_POLICY ON CL_CLAIM.POLICY_ID = UW_POLICY.ID " +
                                                " LEFT JOIN UW_POLICY_COVER ON UW_POLICY.ID = UW_POLICY_COVER.POLICY_ID " +
                                                "     AND UW_POLICY_COVER.COVER_ID = CL_CLAIM_ASSESSMENT.COVER_ID " +
                                                " WHERE (UW_POLICY.ROOT_ID = " + m_policyDto.root.old_root_id +
                                                " OR UW_POLICY.ID = " + resultLinked["LINKED_POLICY_ID"] + ") " +
                                                " AND UW_POLICY.INSURED_ID = " + m_policyDto.policy.insured_id +
                                                " AND UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                                                " AND UW_POLICY.CERTIF_FLAG = 'A' " +
                                                " AND CL_CLAIM_ASSESSMENT.COVER_ID IN " +
                                                " (SELECT ID FROM UW_COVER WHERE COVER_CATEGORY_ID = " + rowfieldsCover["COVER_CATEGORY_ID"] + ") ";

                                            var resultClaim = dbConn.Query(szSqlGrBal, commandTimeout: 1200).ToList();

                                            decimal nGR_BALANCE = 0M;
                                            if (resultGrBal != null && resultGrBal.Count() > 0)
                                            {
                                                var rowfieldsGrBal = resultGrBal as IDictionary<string, object>;
                                                nGR_BALANCE = Convert.ToDecimal(rowfieldsGrBal["GR_BALANCE"]);

                                                if (resultClaim != null && resultClaim.Count() > 0)
                                                {
                                                    for (int i = 0; i < resultClaim.Count(); i++)
                                                    {
                                                        var rowfields = resultClaim[i] as IDictionary<string, object>;

                                                        if (i == 0)
                                                        {
                                                            nGR_BALANCE = Convert.ToDecimal(rowfields["GR_BALANCE"]);
                                                            nGR_BALANCE -= Convert.ToDecimal(rowfields["VISA_ACTUAL_LOS"]);
                                                        }
                                                        else
                                                        {
                                                            nGR_BALANCE -= Convert.ToDecimal(rowfields["VISA_ACTUAL_LOS"]);
                                                        }
                                                    }

                                                    for (int i = 0; i < m_policyDto.policy_cover.Count; i++)
                                                    {
                                                        if (m_policyDto.policy_cover.ElementAt(i).cover_id == _ruleAction.cover_id)
                                                        {
                                                            //TODO: move this to insured
                                                            //m_policyDto.policy_cover.ElementAt(i).gr_balance = nGR_BALANCE;
                                                        }
                                                    }

                                                    m_policyDto.policy_action.Add(policyAction);
                                                }
                                            }
                                        }
                                    }
                                }

                                dbConn.Close();
                            }
                        }

                        break;
                    }

                case (int)Enums.RuleAction.CalculateRemainingLifeTimeLimit:
                    {
                        int iRootId = 0;
                        int iLimitCurID = m_policyDto.policy.sum_insured_cur_id;
                        decimal nLimitAmount = 0M;

                        if (m_policyDto.root.old_root_id != null)
                        {
                            iRootId = (int)m_policyDto.root.old_root_id;
                        }
                        else
                        {
                            iRootId = m_policyDto.policy.root_id;
                        }

                        szAsAt = m_policyDto.policy.date_issue.ToString("yyyy/MM/dd");

                        switch (m_policyDto.policy.contract_type_id)
                        {
                            case (int)Enums.ContractType.Policy:
                            case (int)Enums.ContractType.RenewalEnd:
                            case (int)Enums.ContractType.Endorsement:
                                this.GetContractLastImageCovers(ref m_PolicyCoversLastImage, m_ACCT_parent_policy_id, szAsAt);
                                break;
                            case (int)Enums.ContractType.Certificate:
                                this.GetSimpleCertificateLastImageCovers(ref m_PolicyCoversLastImage, m_ACCT_parent_root_id, szAsAt, this.m_ACCT_parent_certif_no);
                                break;
                            case (int)Enums.ContractType.AccountableCertificate:
                                this.GetCertificateLastImageCovers(ref m_PolicyCoversLastImage, m_ACCT_parent_policy_id, szAsAt);
                                break;
                        }

                        if (m_PolicyCoversLastImage.Count != 0)
                        {
                            for (int i = 0; i < m_PolicyCoversLastImage.Count; i++)
                            {
                                if (m_PolicyCoversLastImage.ElementAt(i).cover_id == Convert.ToInt32(_ruleAction.cover_id))
                                {
                                    nLimitAmount = m_PolicyCoversLastImage.ElementAt(i).limit_life_time;
                                    break;
                                }
                            }

                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();

                                var szSql =
                                  " SELECT " +
                                  " CL_CLAIM_ASSESSMENT.CUR_ID, " +
                                  " CL_CLAIM_ASSESSMENT.ESTIMATED_AMT, " +
                                  " CL_CLAIM_ASSESSMENT.APPROVED_AMT, " +
                                  " CL_CLAIM_ASSESSMENT.DEDUCTIBLE_AMT " +
                                  " FROM CL_CLAIM_ASSESSMENT " +
                                  " LEFT JOIN CL_CLAIM ON CL_CLAIM_ASSESSMENT.CLAIM_ID = CL_CLAIM.ID " +
                                  " WHERE CL_CLAIM.INSURED_ID = " + m_policyDto.policy.insured_id +
                                  " AND CL_CLAIM_ASSESSMENT.COVER_ID = " + _ruleAction.cover_id +
                                  " AND ((CL_CLAIM_ASSESSMENT.STATUS_ID <> 1211 AND CL_CLAIM_ASSESSMENT.STATUS_ID <> 1212 AND " +
                                  " CL_CLAIM_ASSESSMENT.STATUS_ID IS NOT NULL) OR CL_CLAIM_ASSESSMENT.STATUS_ID IS NULL) ";

                                var result = dbConn.Query(szSql, commandTimeout: 1200).ToList();

                                dbConn.Close();

                                if (result != null && result.Count() > 0)
                                {
                                    foreach (var row in result)
                                    {
                                        var rowfields = row as IDictionary<string, object>;

                                        if (Convert.ToInt32(rowfields["CUR_ID"]) == iLimitCurID)
                                        {
                                            if (Convert.ToDecimal(rowfields["APPROVED_AMT"]) != 0)
                                            {
                                                nLimitAmount -= Convert.ToDecimal(rowfields["APPROVED_AMT"]) - Convert.ToDecimal(rowfields["DEDUCTIBLE_AMT"]);
                                            }
                                            else
                                            {
                                                nLimitAmount -= Convert.ToDecimal(rowfields["ESTIMATED_AMT"]) - Convert.ToDecimal(rowfields["DEDUCTIBLE_AMT"]);
                                            }
                                        }
                                        else
                                        {
                                            if (Convert.ToDecimal(rowfields["APPROVED_AMT"]) != 0)
                                            {
                                                nLimitAmount -= Helper.ConvertAmount(connStr,
                                                                                     Convert.ToDecimal(rowfields["APPROVED_AMT"]) - Convert.ToDecimal(rowfields["DEDUCTIBLE_AMT"]),
                                                                                     Convert.ToInt32(rowfields["CUR_ID"]),
                                                                                     DateTime.Today.Date,
                                                                                     iLimitCurID,
                                                                                     2);
                                            }
                                            else
                                            {
                                                nLimitAmount -= Helper.ConvertAmount(connStr,
                                                                                     Convert.ToDecimal(rowfields["ESTIMATED_AMT"]) - Convert.ToDecimal(rowfields["DEDUCTIBLE_AMT"]),
                                                                                     Convert.ToInt32(rowfields["CUR_ID"]),
                                                                                     DateTime.Today.Date,
                                                                                     iLimitCurID,
                                                                                    2);
                                            }
                                        }
                                    }

                                    for (int i = 0; i < m_policyDto.policy_cover.Count; i++)
                                    {
                                        if (m_policyDto.policy_cover.ElementAt(i).cover_id == _ruleAction.cover_id)
                                        {
                                            m_policyDto.policy_cover.ElementAt(i).limit_life_time = nLimitAmount;
                                            blActionApplied = true;
                                        }
                                    }

                                    if (blActionApplied)
                                    {
                                        m_policyDto.policy_action.Add(policyAction);
                                    }
                                }
                                else
                                {
                                    m_ContractLastImageCoversPrepared = true;
                                    return;
                                }
                            }
                        }

                        break;
                    }

                case (int)Enums.RuleAction.ChangeSmaProperty:
                    {
                        if (this.p_isLife)
                        {
                            foreach (var polProperty in p_LifePolicyDto.policy_property)
                            {
                                if (polProperty.object_property_id == _ruleAction.object_property_id)
                                {
                                    polProperty.the_value = _ruleAction.object_property_the_value;
                                    blActionApplied = true;
                                    this.m_NeedToLoadSmaInControls = true;
                                    break;
                                }
                            }
                            if (blActionApplied)
                            {
                                m_policyDto.policy_action.Add(policyAction);
                            }
                        }
                        else // P&C
                        {
                            foreach (var polProperty in m_policyDto.policy_property)
                            {
                                if (polProperty.object_property_id == _ruleAction.object_property_id)
                                {
                                    polProperty.the_value = _ruleAction.object_property_the_value;
                                    blActionApplied = true;
                                    this.m_NeedToLoadSmaInControls = true;
                                    break;
                                }
                            }
                            if (blActionApplied)
                            {
                                m_policyDto.policy_action.Add(policyAction);
                            }
                        }

                        break;
                    }

                case (int)Enums.RuleAction.LogFastTrackClearanceFromClaim:
                case (int)Enums.RuleAction.LogFastTrackClearanceFromCollection:
                case (int)Enums.RuleAction.LogFastTrackCompliance:
                case (int)Enums.RuleAction.LogFastTrackCodification:
                    {
                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
                            dbConn.ConnectionString = connStr;
                            dbConn.Open();

                            var ft = dbConn.QueryFirstOrDefault<int>(
                                " SELECT ID " +
                                " FROM UW_POLICY_FAST_TRACK " +
                                " WHERE POLICY_ID = " + m_policyDto.policy.id +
                                " AND FAST_TRACK_TYPE = " + _ruleAction.action_id);

                            //if (m_policyDto.policy_fast_track.Where(w => w.fast_track_type == _ruleAction.id).Count() == 0)
                            if (ft == 0)
                            {
                                var fastTrack = new UW_POLICY_FAST_TRACK();
                                fastTrack.policy_id = m_policyDto.policy.id;
                                fastTrack.fast_track_type = _ruleAction.action_id;
                                fastTrack.is_passed = _ruleAction.fast_track_value;
                                fastTrack.created_by = m_user_id;
                                fastTrack.created_on = DateTimeOffset.Now;
                                m_policyDto.policy_fast_track.Add(fastTrack);

                                //m_policyDto.policy_action.Add(policyAction);
                            }

                            dbConn.Close();
                        }

                        break;
                    }

                case (int)Enums.RuleAction.SetExternalType:
                    {
                        //TONY 18-FEB-2022 we need to let the system change the external type 
                        //if (m_policyDto.policy.external_type == null || m_policyDto.policy.external_type == "")
                        if (
                            (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Policy ||
                             m_policyDto.policy.contract_type_id == (int)Enums.ContractType.RenewalEnd ||
                             m_policyDto.policy.contract_type_id == (int)Enums.ContractType.RenewalNotice //TONY 23-AUG-2023
                            )
                            && (m_policyDto.root.is_group == 1 || m_policyDto.policy.id <= 0 || m_policyDto.policy.external_type == null || m_policyDto.policy.external_type == "")
                           )
                        {
                            m_policyDto.policy.external_type = _ruleAction.set_value;

                            m_policyDto.policy_action.Add(policyAction);
                        }

                        break;
                    }
            }

        }


        private void LifeApplyRuleAction(
            int companyId,
            Pixel.iris5.models.LF_POLICY _policy,
            CORE_RULE_ACTION _ruleAction,
            int _ruleId,
            Enums.RuleUWOperationType _operationType,
            string _infoMsg)
        {
            bool blActionApplied = false;

            Pixel.iris5.models.LF_POLICY_ACTION policyAction = new Pixel.iris5.models.LF_POLICY_ACTION();

            policyAction.policy_id = p_LifePolicyDto.policy.id;

            policyAction.rule_id = _ruleAction.rule_id;

            policyAction.action_id = _ruleAction.action_id;


            var currentAction = this.m_ListSysType.FirstOrDefault(w => w.id == _ruleAction.action_id);
            if (currentAction != null)
            {
                policyAction.message = currentAction.type_desc;
            }
            if (_ruleAction.message != "")
            {
                policyAction.message += " > " + _ruleAction.message;
            }

            if (_infoMsg != "")
            {
                policyAction.message += " | " + _infoMsg;
            }

            switch (_ruleAction.action_id) //|| //_ruleAction.action_id == (int)Enums.RuleAction.StopError
            {
                case (int)Enums.RuleAction.Warning:
                case (int)Enums.RuleAction.Errors:
                case (int)Enums.RuleAction.RemoveFromCertificateCount:
                case (int)Enums.RuleAction.PrintMessage:
                    p_LifePolicyDto.policy_action.Add(policyAction);
                    break;

                case (int)Enums.RuleAction.AppendClause:
                    {
                        for (int i = 0; i < p_LifePolicyDto.policy_clause.Count; i++)
                        {
                            if (p_LifePolicyDto.policy_clause.ElementAt(i).clause_id == _ruleAction.clause_id)
                            {
                                blActionApplied = true;
                                break;
                            }
                        }

                        if (!blActionApplied)
                        {
                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();

                                var clause = dbConn.QueryFirstOrDefault<Pixel.iris5.models.LF_CLAUSE>("SELECT CLAUSE_CODE, CLAUSE_DESC FROM  LF_CLAUSE WHERE ID = " + _ruleAction.clause_id);

                                dbConn.Close();

                                Pixel.iris5.models.LF_POLICY_CLAUSE policyClause = new Pixel.iris5.models.LF_POLICY_CLAUSE();
                                policyClause.policy_id = p_LifePolicyDto.policy.id;
                                policyClause.clause_id = (int)_ruleAction.clause_id;
                                policyClause.clause_desc = clause.clause_desc;
                                policyClause.clause_content = clause.clause_content;
                                policyClause.is_changeable = clause.is_changeable;
                                //policyClause.IS_EXCLUSION = oDsClauses.UW_Clauses.Rows(0)["IS_EXCLUSION"];
                                p_LifePolicyDto.policy_clause.Add(policyClause);

                                p_LifePolicyDto.policy_action.Add(policyAction);
                            }
                        }

                        break;
                    }

                case (int)Enums.RuleAction.DeleteClause:
                    {
                        blActionApplied = true;
                        for (int i = 0; i < p_LifePolicyDto.policy_clause.Count; i++)
                        {
                            if (p_LifePolicyDto.policy_clause.ElementAt(i).clause_id == Convert.ToInt32(_ruleAction.clause_id))
                            {
                                blActionApplied = false;
                                break;
                            }
                        }

                        if (!blActionApplied)
                        {
                            for (int i = p_LifePolicyDto.policy_clause.Count - 1; i >= 0; i--)
                            {
                                if (p_LifePolicyDto.policy_clause.ElementAt(i).clause_id == Convert.ToInt32(_ruleAction.clause_id))
                                {
                                    p_LifePolicyDto.policy_clause.RemoveAt(i);
                                }
                            }

                            p_LifePolicyDto.policy_action.Add(policyAction);
                        }

                        break;
                    }

                case (int)Enums.RuleAction.NeedAuthorization:
                    {
                        //TODO: IRIS5 Authority Changed                        
                        Enums.AuthorityScope businessRuleScope = new Enums.AuthorityScope();

                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
