                                    break;
                                case Enums.RuleUWOperationType.Proposal:
                                    businessRuleScope = Enums.AuthorityScope.BusinessRuleProposal;
                                    break;
                                //case Enums.RuleUWOperationType.CoverNote:
                                //    businessRuleScope = Enums.AuthorityScope.BusinessRuleCoverNote;
                                //    break;
                                case Enums.RuleUWOperationType.Renewal:
                                    businessRuleScope = Enums.AuthorityScope.BusinessRuleRenewalNotice;
                                    break;
                                case Enums.RuleUWOperationType.EndGeneral:
                                case Enums.RuleUWOperationType.EndCancellation:
                                //case Enums.RuleUWOperationType.EndSuspension:
                                //case Enums.RuleUWOperationType.EndExtension:
                                //case Enums.RuleUWOperationType.EndReactivation:
                                //case Enums.RuleUWOperationType.EndReinstatement:
                                case Enums.RuleUWOperationType.EndBoosterADHOC:
                                case Enums.RuleUWOperationType.EndMarturity:
                                case Enums.RuleUWOperationType.EndTotalSurrender:
                                case Enums.RuleUWOperationType.EndPartialSurrender:
                                    businessRuleScope = Enums.AuthorityScope.BusinessRuleEnd;
                                    break;
                                default:
                                    break;
                            }

                            var secAuthorized = dbConn.QueryFirstOrDefault<SEC_AUTHORITY_REQUEST>(
                                " SELECT * FROM SEC_AUTHORITY_REQUEST WHERE AUTHORITY_SCOPE_ID = " + (int)businessRuleScope +
                                " AND RULE_ID = " + _ruleId +
                                " AND TABLE_KEY = " + p_LifePolicyDto.policy.id +
