                                // todo giorgio 30/4/2024 DEVIRIS5-12733 moved to ValidateUWRules function
                                //var secAuthorityToDelete = dbConn.Query<SEC_AUTHORITY_REQUEST>(
                                //" SELECT * FROM SEC_AUTHORITY_REQUEST WHERE AUTHORITY_SCOPE_ID = " + (int)businessRuleScope +
                                //" AND RULE_ID = " + _ruleId +
                                //" AND TABLE_KEY = " + p_LifePolicyDto.policy.id).ToList();

                                //foreach (var item in secAuthorityToDelete)
                                //{
                                //    var authorityRequest_delete = new SEC_AUTHORITY_REQUEST();

                                //    authorityRequest_delete.authority_scope_id = item.authority_scope_id;
                                //    authorityRequest_delete.company_id = item.company_id;
                                //    authorityRequest_delete.rule_id = item.rule_id;
                                //    authorityRequest_delete.request_date = item.request_date;
                                //    authorityRequest_delete.request_by = item.request_by;
                                //    authorityRequest_delete.request_desc = item.request_desc;
                                //    authorityRequest_delete.action_id = item.action_id;
                                //    authorityRequest_delete.is_rule_valid = item.is_rule_valid;
                                //    authorityRequest_delete.target_authorizer_id = item.target_authorizer_id;
                                //    authorityRequest_delete.is_approved = item.is_approved;

                                //    m_ListAuthorityRequest_deleted.Add(authorityRequest_delete);
                                //}
                                // end todo giorgio 30/4/2024 DEVIRIS5-12733 moved to ValidateUWRules function

                                //    //TODO: added by tony on 17-07-2019 !!!???
                                //    var result = dbConn.Execute(
                                //    " DELETE FROM SEC_AUTHORITY_REQUEST WHERE AUTHORITY_SCOPE_ID = " + (int)businessRuleScope +
                                //    " AND RULE_ID = " + _ruleId +
                                //    " AND TABLE_KEY = " + p_LifePolicyDto.policy.id);

                                //this.m_AuthorizedOperationsRow = null;

                                //Create Auhorization request                                

                                //string szDate = DateTime.Today.ToString("yyyy/MM/dd");

