                                 " WHERE COMPANY_ID = @companyId" +
                                 " AND SEC_USER.IS_INACTIVE = 0" +//TODO - HAMZA 19/09/2023 DEVIRIS5-11380
                                 " AND ROLE_ID IN @roles ";
                                //" AND ROLE_ID IN (SELECT value FROM STRING_SPLIT(@roles, ','))";

                                int[] roleIds = Array.ConvertAll(_ruleAction.authorizer_roles.Split(","), int.Parse);

                                var listAuthorizer = dbConn.Query<int>(szSqlAuth, new { companyId = m_company_id, roles = roleIds }).ToList();

                                if (listAuthorizer.Count != 0)
