                                        //{
                                        //blAuthorityApplied = true;

                                        var authorityRequest = new SEC_AUTHORITY_REQUEST();

                                        authorityRequest.authority_scope_id = (int)businessRuleScope;
                                        authorityRequest.company_id = m_company_id;
                                        authorityRequest.rule_id = _ruleId;
                                        authorityRequest.request_date = DateTime.Now;
                                        authorityRequest.request_by = m_user_id;
                                        authorityRequest.request_desc = _ruleAction.message;
                                        authorityRequest.action_id = _ruleAction.action_id;
                                        authorityRequest.is_rule_valid = _ruleAction.is_rule_valid;
                                        authorityRequest.target_authorizer_id = listAuthorizer.ElementAt(i);
                                        authorityRequest.is_approved = 0;
                                        m_ListAuthorityRequest.Add(authorityRequest);

                                        //TONY 29-NOV-2021
                                        if (p_LifePolicyDto.policy.contract_type_id == 8 || p_LifePolicyDto.policy.contract_type_id == 9)
