        #region Last Image Sma 

        private void GetContractSmaLastImage(int _policyID,
                                                  string _asAt,
                                                  ref List<UW_POLICY_PROPERTY> _listPolicyProperties)
        {
            if (this.m_ContractSmaLastImagePrepared)
            {
                return;
            }

            // Test if we have issued an endorsement

            // retreiving last image as of specified date
            var szSql =
                " SELECT " +

                // giorgio 26-mar-2026 BNK-534
                //" TOP 1 ID " +
                " TOP 1 UW_POLICY.ID " +

                " FROM UW_POLICY " +
                " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                " WHERE  UW_ROOT.COMPANY_ID = " + m_company_id +
                " AND (UW_POLICY.ID = " + _policyID + " OR UW_POLICY.PARENT_POLICY_ID = " + _policyID + ")" +
                " AND IS_DRAFT = 0 AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                " AND UW_POLICY.CONTRACT_TYPE_ID IN (" + (int)Enums.ContractType.Policy + "," +
                                                         (int)Enums.ContractType.RenewalEnd + "," +
                                                         (int)Enums.ContractType.Endorsement + ")" +
                " AND CERTIF_NO IS NULL " +
                " ORDER BY UW_POLICY.DATE_EFFECTIVE DESC, UW_POLICY.ID DESC";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();

                dbConn.Close();

                if (result == null)
                {
                    this.m_ContractSmaLastImagePrepared = true;

                    return;
                }

                var rowfields = result as IDictionary<string, object>;

                int iPolicyID = 0;
                iPolicyID = Convert.ToInt32(rowfields["ID"]);

                this.FillPolicySma(iPolicyID, ref _listPolicyProperties);

                this.m_ContractSmaLastImagePrepared = true;
            }
        }

