        private void FillPolicySma(int _policyID,
                                        ref List<UW_POLICY_PROPERTY> _listPolicyPropertyTarget)
        {
            //IRIS 5 how to add missing colun
            //Add Missing Columns in _DsSmaTarget
            //
            //if (!(_ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Contains("PROPERTY_ID")))
            //{
            //    _ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Add("PROPERTY_ID");
            //}
            //if (!(_ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Contains("PROPERTY_DESC")))
            //{
            //    _ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Add("PROPERTY_DESC");
            //}
            //if (!(_ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Contains("PROPERTY_TYPE_ID")))
            //{
            //    _ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Add("PROPERTY_TYPE_ID");
            //}
            //if (!(_ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Contains("PROPERTY_TABLE_ID")))
            //{
            //    _ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Add("PROPERTY_TABLE_ID");
            //}
            //if (!(_ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Contains("CONTACT_FIELD")))
            //{
            //    _ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Add("CONTACT_FIELD");
            //}
            //if (!(_ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Contains("CONTACT_FIELDPROPERTY_TYPE_ID")))
            //{
            //    _ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Add("CONTACT_FIELDPROPERTY_TYPE_ID");
            //}
            //if (!(_ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Contains("SYSTEM_TABLE")))
            //{
            //    _ListPolicyPropertyTarget.UW_POLICY_PROPERTY.Columns.Add("SYSTEM_TABLE");
            //}

            // string szSqlObject = null;
            string szSqlObjectProperties = null;

            string szSqlCurrentObjectProperties = null;
            //string szSqlObjectsCOBs = null;
            //szSqlObjectsCOBs = "";

            List<iris5.models.UW_POLICY_PROPERTY> oDsPolicySmaSource = new List<iris5.models.UW_POLICY_PROPERTY>();
            List<iris5.models.UW_POLICY_PROPERTY> oDsCurrentObjects = new List<iris5.models.UW_POLICY_PROPERTY>();

            //szSqlObject = "SELECT * FROM UW_POLICY_PROPERTY " +
            //    " WHERE POLICY_ID = " + _PolicyID;

            szSqlObjectProperties =
                " SELECT " +
                " UW_POLICY_PROPERTY.*, " +
                " OB_OBJECT_PROPERTY.PROPERTY_ID, " +
                " OB_OBJECT_PROPERTY.PROPERTY_DESC, " +
                " OB_PROPERTY.PROPERTY_TYPE_ID, " +
                " OB_PROPERTY.PROPERTY_TABLE_ID, " +
                " OB_PROPERTY.CONTACT_FIELD, " +
                // "OB_PROPERTY.CONTACT_FIELDPROPERTY_TYPE_ID, " +
                " OB_PROPERTY.SYSTEM_TABLE " +
                " FROM UW_POLICY_PROPERTY " +
                " LEFT JOIN OB_OBJECT_PROPERTY ON UW_POLICY_PROPERTY.OBJECT_PROPERTY_ID = OB_OBJECT_PROPERTY.ID " +
                " LEFT JOIN OB_PROPERTY ON OB_OBJECT_PROPERTY.PROPERTY_ID = OB_PROPERTY.ID " +
                " WHERE UW_POLICY_PROPERTY.POLICY_ID = " + _policyID +
                " ORDER BY UW_POLICY_PROPERTY.SORTING ";

            szSqlCurrentObjectProperties =
                " SELECT " +
                " OB_OBJECT_PROPERTY.*, " +
                " OB_PROPERTY.PROPERTY_TYPE_ID," +
                " OB_PROPERTY.PROPERTY_TABLE_ID, " +
                " OB_PROPERTY.CONTACT_FIELD, " +
                //" OB_PROPERTY.CONTACT_FIELDPROPERTY_TYPE_ID," +
                " OB_PROPERTY.SYSTEM_TABLE " +
                " FROM OB_OBJECT_PROPERTY " +
                " LEFT JOIN OB_PROPERTY ON OB_OBJECT_PROPERTY.PROPERTY_ID = OB_PROPERTY.ID " +
                " LEFT JOIN UW_POLICY_PROPERTY ON OB_OBJECT_PROPERTY.ID = UW_POLICY_PROPERTY.OBJECT_PROPERTY_ID " +
                " WHERE UW_POLICY_PROPERTY.POLICY_ID = " + _policyID +

                // giorgio 26-mar-2026 BNK-534
                //" ORDER BY OB_OBJECT_PROPERTY.SORTING ";
                " ORDER BY OB_OBJECT_PROPERTY.UW_SORTING ";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                oDsPolicySmaSource = dbConn.Query<UW_POLICY_PROPERTY>(szSqlObjectProperties, commandTimeout: 1200).ToList();

                oDsCurrentObjects = dbConn.Query<UW_POLICY_PROPERTY>(szSqlCurrentObjectProperties, commandTimeout: 1200).ToList();

                if (oDsPolicySmaSource == null)
                {
                    return;
                }

                //foreach (var row in oDsPolicySmaSource)
                //{
                //    var rowfields = row as IDictionary<string, object>;
                //    if (rowfields["ACTION_ID"] == _parameters[0])
                //    {
                //        blResult = true;
                //        break;
                //    }
                //}


                //oDsCurrentObjects = oCBRObjects.GetData(szSqlObject, szSqlCurrentObjectProperties, szSqlObjectsCOBs);

                UW_POLICY_PROPERTY e_policy_property_target = null;


                foreach (var row in oDsPolicySmaSource)
                {
                    e_policy_property_target = new UW_POLICY_PROPERTY();
                    e_policy_property_target.policy_id = row.policy_id;
                    e_policy_property_target.object_property_id = row.object_property_id;
                    e_policy_property_target.property_id = row.property_id;
                    e_policy_property_target.property_desc = row.property_desc;
                    e_policy_property_target.property_type_id = row.property_type_id;
                    if (row.property_table_id != null)
                    {
                        e_policy_property_target.property_table_id = row.property_table_id;
                    }
                    if (row.contact_field != null)
                    {
                        e_policy_property_target.contact_field = row.contact_field;
                    }
                    //if (row.CONTACT_FIELDPROPERTY_TYPE_ID != null)
                    //{
                    //    e_policy_property_target.CONTACT_FIELDPROPERTY_TYPE_ID = row.CONTACT_FIELDPROPERTY_TYPE_ID;
                    //}
                    if (row.system_table != null)
                    {
                        e_policy_property_target.system_table = row.system_table;
                    }
                    e_policy_property_target.sorting = row.sorting;
                    e_policy_property_target.the_value = row.the_value;
                    e_policy_property_target.is_subject_to_accumulation = row.is_subject_to_accumulation;
                    e_policy_property_target.is_mandatory = row.is_mandatory;
                    _listPolicyPropertyTarget.Add(e_policy_property_target);
                }

                for (int i = 0; i < oDsCurrentObjects.Count; i++)
                {
                    var lst = oDsPolicySmaSource.Where(w => w.object_property_id == oDsCurrentObjects.ElementAt(i).object_property_id);

                    if (lst == null || lst.Count() == 0)
                    {
                        e_policy_property_target = new UW_POLICY_PROPERTY();

                        e_policy_property_target.policy_id = _policyID;
                        e_policy_property_target.object_property_id = oDsCurrentObjects.ElementAt(i).object_property_id;
                        e_policy_property_target.property_id = oDsCurrentObjects.ElementAt(i).property_id;
                        e_policy_property_target.property_desc = oDsCurrentObjects.ElementAt(i).property_desc;
                        e_policy_property_target.property_type_id = oDsCurrentObjects.ElementAt(i).property_type_id;
                        e_policy_property_target.property_table_id = oDsCurrentObjects.ElementAt(i).property_table_id;
                        if (oDsCurrentObjects.ElementAt(i).contact_field != null)
                        {
                            e_policy_property_target.contact_field = oDsCurrentObjects.ElementAt(i).contact_field;
                        }
                        //if (oDsCurrentObjects.ElementAt(i).CONTACT_FIELDPROPERTY_TYPE_ID != null)
                        //{
                        //    e_policy_property_target.CONTACT_FIELDPROPERTY_TYPE_ID = oDsCurrentObjects.ElementAt(i).CONTACT_FIELDPROPERTY_TYPE_ID;
                        //}
                        if (oDsCurrentObjects.ElementAt(i).system_table != null)
                        {
                            e_policy_property_target.system_table = oDsCurrentObjects.ElementAt(i).system_table;
                        }
                        e_policy_property_target.sorting = oDsCurrentObjects.ElementAt(i).sorting;
                        if (oDsCurrentObjects.ElementAt(i).property_type_id == (int)Enums.SMAPropertyType.Bit)
                        {
                            e_policy_property_target.the_value = "0";
                        }
                        else
                        {
                            e_policy_property_target.the_value = "";
                        }
                        e_policy_property_target.is_subject_to_accumulation = oDsCurrentObjects.ElementAt(i).is_subject_to_accumulation;
                        e_policy_property_target.is_mandatory = oDsCurrentObjects.ElementAt(i).is_mandatory;

                        _listPolicyPropertyTarget.Add(e_policy_property_target);
                    }
                }

                dbConn.Close();
            }
        }

        #endregion Last Image Sma 

        #region Last Image 

        private void GetContractLastImageData(ref PolicyLastImageDto _policyLastImage,
                                              int _policyId,
                                              string _asAt,
                                              bool _withComputation)
        {
            if (m_ContractLastImageDataPrepared)
            {
                return;
            }

            string szPolicy = "";
            string szWherePolicy = "";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                if (this.m_SubBranchID == Enums.SubBranches.Health &&
                    _UW_HealthGetLastImageInEndorsement == true)
                {
                    szPolicy =
                        " SELECT TOP 1 " +
                        " ID, " +
                        " PARENT_POLICY_ID, " +
                        " CONTRACT_TYPE_ID, " +
                        " END_TYPE," +
                        " DATE_EFFECTIVE " +
                        " FROM UW_POLICY " +
                        " WHERE UW_POLICY.ID = " + _policyId +
                        " OR UW_POLICY.PARENT_POLICY_ID = " + _policyId +
                        " AND UW_POLICY.CONTRACT_TYPE_ID IN (0,1,11) " +
                        " ORDER BY UW_POLICY.DATE_EFFECTIVE DESC, UW_POLICY.ID DESC ";

                    szWherePolicy = "";

                    var result = dbConn.Query(szPolicy, commandTimeout: 1200).FirstOrDefault();
                    if (result != null)
                    {
                        var rowfields = result as IDictionary<string, object>;

                        if (szWherePolicy.Trim() == "")
                        {
                            szWherePolicy += " AND (UW_POLICY.ID = " + Convert.ToInt32(rowfields["ID"]) + ")";
                        }
                        else
                        {
                            szWherePolicy += " OR (UW_POLICY.ID = " + Convert.ToInt32(rowfields["ID"]) + ")";
                        }

                        //make the asat = DATE_EFFECTIVE of last endorsement in order to issue other endorsements on medical policies
                        _asAt = Convert.ToDateTime(rowfields["DATE_EFFECTIVE"]).ToString("yyyy/MM/dd");
                    }
                }
                else
                {
                    szPolicy =
                        "SELECT " +
                        "ID, " +
                        "PARENT_POLICY_ID, " +
                        "CONTRACT_TYPE_ID, " +
                        "END_TYPE " +
                        "FROM UW_POLICY " +
                        " WHERE UW_POLICY.ID = " + _policyId;

                    szWherePolicy = "";

                    var result = dbConn.Query(szPolicy, commandTimeout: 1200).ToList();
                    if (result != null)
                    {
                        foreach (var row in result)
                        {
                            var rowfields = row as IDictionary<string, object>;

                            if (Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == (int)Enums.ContractType.Policy ||
                                Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == (int)Enums.ContractType.RenewalEnd)
                            {
                                if (szWherePolicy.Trim() == "")
                                {
                                    szWherePolicy +=
                                        " AND ((UW_POLICY.ID = " + Convert.ToInt32(rowfields["ID"]) +
                                        " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["ID"]) + ")";
                                }
                                else
                                {
                                    szWherePolicy +=
                                        " OR (UW_POLICY.ID = " + Convert.ToInt32(rowfields["ID"]) +
                                        " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["ID"]) + ")";
                                }
                            }
                            else
                            {
                                if (rowfields["PARENT_POLICY_ID"] != null)
                                {
                                    if (szWherePolicy.Trim() == "")
                                    {
                                        szWherePolicy += " AND ((UW_POLICY.ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) +
                                            " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) + ")";
                                    }
                                    else
                                    {
                                        szWherePolicy += " OR (UW_POLICY.ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) +
                                            " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) + ")";
                                    }
                                }
                            }
                        }
                    }

                    if (szWherePolicy != "")
                    {
                        szWherePolicy += ")";
                    }
                }

                UW_POLICY oDsPolicySource = new UW_POLICY();

                var szWhere =
                    " UW_ROOT.COMPANY_ID = " + m_company_id +
                    " AND UW_POLICY.CONTRACT_TYPE_ID IN(" + (int)Enums.ContractType.Policy + "," +
                                                            (int)Enums.ContractType.RenewalEnd + "," +
                                                            (int)Enums.ContractType.Endorsement + ")" +
                    " AND CERTIF_NO IS NULL AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                    " AND UW_POLICY.IS_DRAFT = 0 " +
                    szWherePolicy;

                var szSql =
                    " SELECT UW_POLICY.* " +
                    " FROM UW_POLICY " +
                    " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                    " WHERE " + szWhere +
                    " ORDER BY UW_POLICY.ID ";

                var resultPolicySource = dbConn.Query<UW_POLICY>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();
                if (resultPolicySource == null || resultPolicySource.Count() == 0)
                {
                    //No image was found for this policy at the specified date
                    m_ContractLastImageDataPrepared = true;

                    return;
                }

                List<UW_POLICY_COMPUTATION> resultComputationSource = new List<UW_POLICY_COMPUTATION>(); // AN 2026-02-02

                if (_withComputation)
                {
                    var szComputations =
                        " SELECT " +
                        " COMPUT_GROUP_ID, " +
                        " UW_COMPUTATION_ITEM.COMPUT_FRACTION_ID, " +
                        " SUM(UW_POLICY_COMPUTATION.AMOUNT) AS AMOUNT " +
                        " FROM UW_POLICY_COMPUTATION " +
                        " LEFT JOIN UW_POLICY ON UW_POLICY_COMPUTATION.POLICY_ID = UW_POLICY.ID " +
                        " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                        " LEFT JOIN UW_COMPUTATION_ITEM ON UW_POLICY_COMPUTATION.COMPUTATION_ITEM_ID = UW_COMPUTATION_ITEM.ID" +
                        " LEFT JOIN UW_COMPUT_FRACTION ON UW_COMPUTATION_ITEM.COMPUT_FRACTION_ID = UW_COMPUT_FRACTION.ID " +
                        " WHERE " + szWhere +
                        " GROUP BY COMPUT_GROUP_ID, UW_COMPUTATION_ITEM.COMPUT_FRACTION_ID ";

                    resultComputationSource = dbConn.Query<UW_POLICY_COMPUTATION>(szComputations, commandTimeout: 1200).ToList();
                }

                UW_POLICY oRowPolicySource = null;
                UW_POLICY_COMPUTATION oRowComputationTarget = null;

                //oCBrPolicy.SetDefaultValues(_DsPolicy);

                //try
                //{
                //    _PolicyLastImage.UW_POLICY_COMPUTATION.Columns.Add("COMPUT_GROUP_ID", System.Type.GetType("System.Int32"));
                //}
                //catch (Exception ex)
                //{
                //}

                for (int i = 0; i < resultPolicySource.Count; i++)
                {
                    oRowPolicySource = resultPolicySource.ElementAt(i);

                    if (this.m_SubBranchID == Enums.SubBranches.Health &&
                        _UW_HealthGetLastImageInEndorsement == true)
                    {
                        // Policy table info
                        _policyLastImage.policy = new UW_POLICY();

                        //e_policy_target = new Models.UW_POLICY();
                        _policyLastImage.policy.contract_type_id = (int)Enums.ContractType.Policy;
                        _policyLastImage.policy.id = oRowPolicySource.id;
                        _policyLastImage.policy.root_id = oRowPolicySource.root_id;
                        _policyLastImage.policy.insured_id = oRowPolicySource.insured_id;
                        _policyLastImage.policy.print_name = oRowPolicySource.print_name;
                        _policyLastImage.policy.broker_id = oRowPolicySource.broker_id;
                        if (oRowPolicySource.account_id != null)
                        {
                            _policyLastImage.policy.account_id = oRowPolicySource.account_id;
                        }
                        _policyLastImage.policy.date_issue = oRowPolicySource.date_issue;
                        _policyLastImage.policy.date_effective = oRowPolicySource.date_effective;
                        if (oRowPolicySource.date_expiry != null)
                        {
                            _policyLastImage.policy.date_expiry = oRowPolicySource.date_expiry;
                        }
                        _policyLastImage.policy.cob_id = oRowPolicySource.cob_id;
                        _policyLastImage.policy.policy_no = oRowPolicySource.policy_no;
                        if (oRowPolicySource.residency_address_id != null)
                        {
                            _policyLastImage.policy.residency_address_id = oRowPolicySource.residency_address_id;
                        }
                        if (oRowPolicySource.billing_address_id != null)
                        {
                            _policyLastImage.policy.billing_address_id = oRowPolicySource.billing_address_id;
                        }

                        if (oRowPolicySource.prod_id != null)
                        {
                            _policyLastImage.policy.prod_id = oRowPolicySource.prod_id;
                        }

                        _policyLastImage.policy.sum_insured_cur_id = oRowPolicySource.sum_insured_cur_id;
                        _policyLastImage.policy.sum_insured = oRowPolicySource.sum_insured;
                        _policyLastImage.policy.premium_cur_id = oRowPolicySource.premium_cur_id;
                        _policyLastImage.policy.base_cur_rate = oRowPolicySource.base_cur_rate;
                        _policyLastImage.policy.counter_cur_rate = oRowPolicySource.counter_cur_rate;
                        _policyLastImage.policy.computation_id = oRowPolicySource.computation_id;
                        _policyLastImage.policy.sub_total = oRowPolicySource.sub_total;
                        _policyLastImage.policy.vat_location_id = oRowPolicySource.vat_location_id;
                        _policyLastImage.policy.vat_code_id = oRowPolicySource.vat_code_id;
                        _policyLastImage.policy.vat_pct = oRowPolicySource.vat_pct;
                        _policyLastImage.policy.vat_amt = oRowPolicySource.vat_amt;
                        _policyLastImage.policy.grand_total = oRowPolicySource.grand_total;
                        _policyLastImage.policy.is_cover_rate_on_net = oRowPolicySource.is_cover_rate_on_net;
                        //IRIS5 to add
                        //_PolicyLastImage.policy.isSignedCopyReceived = oRowPolicySource.isSignedCopyReceived;
                        //_PolicyLastImage.policy.isLifeTimeComputation = oRowPolicySource.isLifeTimeComputation;
                        //_PolicyLastImage.policy.isLifeTimeCommission = oRowPolicySource.isLifeTimeCommission;

                        _policyLastImage.policy.notes = oRowPolicySource.notes;
                        _policyLastImage.policy.reference = oRowPolicySource.reference;

                        //_PolicyLastImage.policy AddUW_POLICYRow(e_policy_target);

                        // Computations
                        if (_withComputation && resultComputationSource != null)
                        {
                            for (int j = 0; j < resultComputationSource.Count; j++)
                            {
                                oRowComputationTarget = new UW_POLICY_COMPUTATION();
                                oRowComputationTarget.policy_id = _policyLastImage.policy.id;
                                oRowComputationTarget.computation_item_id = -1;
                                oRowComputationTarget.comput_fraction_id = resultComputationSource.ElementAt(0).comput_fraction_id;
                                oRowComputationTarget.comput_group_id = resultComputationSource.ElementAt(0).comput_group_id;
                                oRowComputationTarget.amount = resultComputationSource.ElementAt(0).amount;

                                _policyLastImage.policy_computation.Add(oRowComputationTarget);
                            }
                        }
                    }
                    else //Regular Last Image
                    {
                        if (oRowPolicySource.contract_type_id == 0 ||
                            oRowPolicySource.contract_type_id == (int)Enums.ContractType.RenewalEnd)
                        {
                            // Policy table info
                            _policyLastImage.policy = new UW_POLICY();
                            _policyLastImage.policy.contract_type_id = (int)Enums.ContractType.Policy;
                            _policyLastImage.policy.id = oRowPolicySource.id;
                            _policyLastImage.policy.root_id = oRowPolicySource.root_id;
                            _policyLastImage.policy.insured_id = oRowPolicySource.insured_id;
                            _policyLastImage.policy.print_name = oRowPolicySource.print_name;
                            _policyLastImage.policy.broker_id = oRowPolicySource.broker_id;
                            if (oRowPolicySource.account_id != null)
                            {
                                _policyLastImage.policy.account_id = oRowPolicySource.account_id;
                            }
                            _policyLastImage.policy.date_issue = oRowPolicySource.date_issue;
                            _policyLastImage.policy.date_effective = oRowPolicySource.date_effective;
                            if (oRowPolicySource.date_expiry != null)
                            {
                                _policyLastImage.policy.date_expiry = oRowPolicySource.date_expiry;
                            }
                            _policyLastImage.policy.cob_id = oRowPolicySource.cob_id;
                            _policyLastImage.policy.policy_no = oRowPolicySource.policy_no;
                            if (oRowPolicySource.residency_address_id != null)
                            {
                                _policyLastImage.policy.residency_address_id = oRowPolicySource.residency_address_id;
                            }
                            if (oRowPolicySource.billing_address_id != null)
                            {
                                _policyLastImage.policy.billing_address_id = oRowPolicySource.billing_address_id;
                            }

                            if (oRowPolicySource.prod_id != null)
                            {
                                _policyLastImage.policy.prod_id = oRowPolicySource.prod_id;
                            }
                            //if (!oRowPolicySource.IsDistributionSTATUS_IDNull)
                            //{
                            //    _PolicyLastImage.policy.DistributionSTATUS_ID = oRowPolicySource.DistributionSTATUS_ID;
                            //}
                            _policyLastImage.policy.sum_insured_cur_id = oRowPolicySource.sum_insured_cur_id;
                            _policyLastImage.policy.sum_insured = oRowPolicySource.sum_insured;
                            _policyLastImage.policy.premium_cur_id = oRowPolicySource.premium_cur_id;
                            _policyLastImage.policy.base_cur_rate = oRowPolicySource.base_cur_rate;
                            _policyLastImage.policy.counter_cur_rate = oRowPolicySource.counter_cur_rate;
                            _policyLastImage.policy.computation_id = oRowPolicySource.computation_id;
                            _policyLastImage.policy.sub_total = oRowPolicySource.sub_total;
                            _policyLastImage.policy.vat_location_id = oRowPolicySource.vat_location_id;
                            _policyLastImage.policy.vat_code_id = oRowPolicySource.vat_code_id;
                            _policyLastImage.policy.vat_pct = oRowPolicySource.vat_pct;
                            _policyLastImage.policy.vat_amt = oRowPolicySource.vat_amt;
                            _policyLastImage.policy.grand_total = oRowPolicySource.grand_total;
                            _policyLastImage.policy.is_cover_rate_on_net = oRowPolicySource.is_cover_rate_on_net;
                            //IRIS5 to add
                            //_PolicyLastImage.policy.isSignedCopyReceived = oRowPolicySource.isSignedCopyReceived;
                            //_PolicyLastImage.policy.isLifeTimeComputation = oRowPolicySource.isLifeTimeComputation;
                            //_PolicyLastImage.policy.isLifeTimeCommission = oRowPolicySource.isLifeTimeCommission;
                            if (oRowPolicySource.notes != null)
                            {
                                _policyLastImage.policy.notes = oRowPolicySource.notes;
                            }
                            if (oRowPolicySource.external_type != null)
                            {
                                _policyLastImage.policy.external_type = oRowPolicySource.external_type;
                            }
                            if (oRowPolicySource.external_no != null)
                            {
                                _policyLastImage.policy.external_no = oRowPolicySource.external_no;
                            }
                            if (oRowPolicySource.reference != null)
                            {
                                _policyLastImage.policy.reference = oRowPolicySource.reference;
                            }

                            //_PolicyLastImage.UW_POLICY.AddUW_POLICYRow(e_policy_target);

                            // Computations
                            if (_withComputation && resultComputationSource != null)
                            {
                                for (int j = 0; j < resultComputationSource.Count; j++)
                                {
                                    oRowComputationTarget = new UW_POLICY_COMPUTATION();
                                    oRowComputationTarget.policy_id = _policyLastImage.policy.id;
                                    oRowComputationTarget.computation_item_id = -1;
                                    oRowComputationTarget.comput_fraction_id = resultComputationSource.ElementAt(j).comput_fraction_id;
                                    oRowComputationTarget.comput_group_id = resultComputationSource.ElementAt(i).comput_group_id;
                                    oRowComputationTarget.amount = resultComputationSource.ElementAt(i).amount;

                                    _policyLastImage.policy_computation.Add(oRowComputationTarget);
                                }
                            }
                        }
                        else
                        {
                            //
                            //This is an endorsement
                            //
                            //INSTANT C# TODO TASK: The return type of the tempWith1 variable must be corrected.
                            //ORIGINAL LINE: With _DsPolicy.UW_POLICY.Rows(_DsPolicy.UW_POLICY.Rows.Count - 1)
                            //TODO: IRIS5 how many rowa are found?
                            //object tempWith1 = _PolicyLastImage.UW_POLICY.Rows(_PolicyLastImage.UW_POLICY.Rows.Count - 1);

                            _policyLastImage.policy.insured_id = oRowPolicySource.insured_id;

                            if (oRowPolicySource.print_name != null)
                            {
                                _policyLastImage.policy.print_name = oRowPolicySource.print_name;
                            }
                            _policyLastImage.policy.broker_id = oRowPolicySource.broker_id;

                            if (oRowPolicySource.account_id != null)
                            {
                                _policyLastImage.policy.account_id = oRowPolicySource.account_id;
                            }

                            if (oRowPolicySource.contract_type_id == 1 && oRowPolicySource.end_type != null)
                            {
                                switch (oRowPolicySource.end_type)
                                {
                                    case "G":
                                        if (oRowPolicySource.date_expiry != null)
                                        {
                                            _policyLastImage.policy.date_expiry = oRowPolicySource.date_expiry;
                                        }
                                        if (oRowPolicySource.residency_address_id != null)
                                        {
                                            _policyLastImage.policy.residency_address_id = oRowPolicySource.residency_address_id;
                                        }
                                        if (oRowPolicySource.billing_address_id != null)
                                        {
                                            _policyLastImage.policy.billing_address_id = oRowPolicySource.billing_address_id;
                                        }
                                        break;
                                    case "C":
                                        _policyLastImage.policy.date_expiry = oRowPolicySource.date_effective;

                                        break;
                                    case "S":
                                        _policyLastImage.policy.date_expiry = oRowPolicySource.date_effective;

                                        break;
                                    case "I":
                                        _policyLastImage.policy.date_effective = oRowPolicySource.date_effective;
                                        if (oRowPolicySource.date_expiry != null)
                                        {
                                            _policyLastImage.policy.date_expiry = oRowPolicySource.date_expiry;
                                        }

                                        break;
                                    case "E":
                                        if (oRowPolicySource.date_expiry != null)
                                        {
                                            _policyLastImage.policy.date_expiry = oRowPolicySource.date_expiry;
                                        }

                                        break;
                                }
                            }
                        }
                    }
                }

                m_ContractLastImageDataPrepared = true;

                dbConn.Close();
            }
        }

        private void GetSimpleCertificateLastImageData(
                ref PolicyLastImageDto _policyLastImage,
                int _rootId,
                string _asAt,
                int _certifNo,
                bool _withComputation)
        {

            if (m_SimpleCertificateLastImageDataPrepared)
            {
                return;
            }

            string szComputations = null;

            var szSql =
                //TODO ELIASN 18-APR-2024 LIA-3680
                //" SELECT TOP 1 ID " +
                " SELECT TOP 1 UW_POLICY.ID " +
                //TODO ELIASN 18-APR-2024 LIA-3680
                " FROM UW_POLICY " +
                " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                " WHERE UW_ROOT.COMPANY_ID = " + m_company_id +
                " AND UW_ROOT.ID = " + _rootId +
                " AND CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                " AND UW_POLICY.CERTIF_NO = '" + _certifNo + "'" +
                " AND UW_POLICY.DATE_EFFECTIVE <= '" + _asAt + "'" +
                " AND IS_DRAFT = 0 " +
                " ORDER BY DATE_EFFECTIVE DESC, ID DESC ";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();

                dbConn.Close();

                if (result != null && result.Count() != 0)
                {
                    var rowfields = result as IDictionary<string, object>;

                    Int32 iCertificateID = 0;
                    iCertificateID = Convert.ToInt32(rowfields["ID"]);

                    szSql =
                        " SELECT UW_POLICY.* " +
                        " FROM UW_POLICY " +
                        " WHERE UW_POLICY.ID = " + iCertificateID;

                    //TODO: IRIS5 need to be checked
                    m_PolicyLastImage.policy = dbConn.Query<UW_POLICY>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).FirstOrDefault();

                    if (_withComputation)
                    {
                        szComputations =
                            " SELECT " +
                            " COMPUT_GROUP_ID, " +
                            " AMOUNT " +
                            " FROM UW_POLICY_COMPUTATION " +
                            " LEFT JOIN UW_POLICY ON UW_POLICY_COMPUTATION.POLICY_ID = UW_POLICY.ID " +
                            " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                            " LEFT JOIN UW_COMPUTATION_ITEM ON UW_POLICY_COMPUTATION.COMPUTATION_ITEM_ID = UW_COMPUTATION_ITEM.ID  " +
                            " LEFT JOIN UW_COMPUT_FRACTION ON UW_COMPUTATION_ITEM.COMPUT_FRACTION_ID = UW_COMPUT_FRACTION.ID  " +
                            " WHERE UW_POLICY.ID = " + iCertificateID;

                        m_PolicyLastImage.policy_computation = dbConn.Query<UW_POLICY_COMPUTATION>(szComputations, commandTimeout: 1200).ToList();

                    }

                    m_SimpleCertificateLastImageDataPrepared = true;

                }
                else
                {
                    m_SimpleCertificateLastImageDataPrepared = true;

                    return;
                }
            }
        }

        private void GetCertificateLastImageData(
                ref PolicyLastImageDto _PolicyLastImage,
                int _policyId,
                string _asAt,
                bool _withComputation)
        {
            if (m_CertificateLastImageDataPrepared)
            {
                return;
            }

            UW_POLICY oDsPolicySource = new UW_POLICY();
            string szWhere = null;

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                if (this.m_SubBranchID == Enums.SubBranches.Health &&
                        _UW_HealthGetLastImageInEndorsement == true)
                {
                    string szCert =
                        " SELECT TOP 1 " +
                        " UW_POLICY.CERTIF_NO, " +
                        " UW_POLICY.ID " +
                        " FROM UW_POLICY " +
                        " WHERE CERTIF_NO IN (SELECT CERTIF_NO FROM UW_POLICY tPolicy " +
                        " WHERE tPolicy.ID = " + _policyId +
                        " AND tPolicy.CERTIF_NO IS NOT NULL " +
                        " AND UW_POLICY.ROOT_ID = tPolicy.ROOT_ID ) " +
                        " AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                        " ORDER BY UW_POLICY.DATE_EFFECTIVE DESC, ID DESC ";

                    var result = dbConn.Query(szCert, commandTimeout: 1200).FirstOrDefault();
                    if (result != null)
                    {
                        var rowfields = result as IDictionary<string, object>;
                        _policyId = Convert.ToInt32(rowfields["ID"]);
                    }

                    szWhere = " AND UW_POLICY.ID = " + _policyId;
                }
                else
                {
                    szWhere =
                        " UW_ROOT.COMPANY_ID = " + m_company_id +
                        " AND (UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.AccountableCertificate +
                        " OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.OPC +
                        " OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.PrepaidOPC +
                        " OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Endorsement +
                        " OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate + ")" +
                        " AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                        " AND UW_POLICY.IS_DRAFT = 0 " +
                        " AND (UW_POLICY.ID = " + _policyId +
                        " OR UW_POLICY.PARENT_POLICY_ID = " + _policyId + ")";
                }

                var szSql =
                    " SELECT UW_POLICY.* " +
                    " FROM UW_POLICY " +
                    " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                    " WHERE " + szWhere +
                    " ORDER BY UW_POLICY.ROOT_ID, UW_POLICY.ID ";

                var resultPolicySource = dbConn.Query<UW_POLICY>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();
