        //TODO: IRIS5 the DATE_EFFECTIVE IS NOT IN THE SELECT???
        private void GetContractLastImageCovers(
            ref List<iris5.models.UW_POLICY_COVER> _listPolicyCovers,
            int _policyId,
            string _asAt)
        {
            if (m_ContractLastImageCoversPrepared)
            {
                return;
            }

            var szWherePolicy = "";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                if (this.m_SubBranchID == Enums.SubBranches.Health &&
                    _UW_HealthGetLastImageInEndorsement == true)
                {
                    var szSqlPolicy =
                        " SELECT " +
                        " TOP 1 " +
                        " ID " +
                        " FRO, DATE_EFFECTIVE " +
                        " FROM UW_POLICY " +
                        " WHERE UW_POLICY.ID = " + _policyId +
                        " OR UW_POLICY.PARENT_POLICY_ID = " + _policyId +
                        " AND UW_POLICY.CONTRACT_TYPE_ID IN (0,1,11) " +
                        " ORDER BY UW_POLICY.DATE_EFFECTIVE DESC, UW_POLICY.ID DESC ";

                    var result = dbConn.Query(szSqlPolicy, commandTimeout: 1200).FirstOrDefault();
                    if (result != null)
                    {
                        var rowfields = result as IDictionary<string, object>;

                        _policyId = Convert.ToInt32(rowfields["ID"]);
                        _asAt = Convert.ToDateTime(rowfields["DATE_EFFECTIVE"]).ToString("yyyy/MM/dd");

                        var szSql =
                           " SELECT " +
                           " UW_POLICY_COVER.COVER_ID, " +
                           " LIMIT_LIFE_TIME, " +
                           " COINS_DESC " +
                           " FROM UW_POLICY_COVER " +
                           " LEFT JOIN UW_COINS ON UW_POLICY_COVER.CO_INS_ID = UW_COINS.ID " +
                           " WHERE UW_POLICY_COVER.POLICY_ID = " + _policyId +
                           "  AND (('" + _asAt + "' BETWEEN UW_POLICY_COVER.EFFECTIVE_DATE AND UW_POLICY_COVER.EXPIRY_DATE) OR " +
                           " (UW_POLICY_COVER.EXPIRY_DATE IS NULL AND '" + _asAt + "' >= UW_POLICY_COVER.EFFECTIVE_DATE)) " +
                           " ORDER BY UW_POLICY_COVER.POLICY_ID, UW_POLICY_COVER.ID ";

                        _listPolicyCovers = dbConn.Query<iris5.models.UW_POLICY_COVER>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();

                        m_ContractLastImageCoversPrepared = true;
                    }
                }
                else
                {
                    var szSqlPolicy =
                        "SELECT " +
                        "ID, " +
                        "PARENT_POLICY_ID, " +
                        "CONTRACT_TYPE_ID, " +
                        "END_TYPE " +
                        "FROM UW_POLICY " +
                        " WHERE UW_POLICY.ID = " + _policyId;

                    var result = dbConn.Query(szSqlPolicy, commandTimeout: 1200).ToList();
                    if (result != null)
                    {
                        szWherePolicy = "";

                        foreach (var row in result)
                        {
                            var rowfields = row as IDictionary<string, object>;

                            if (Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == 0 ||
                                Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == (int)Enums.ContractType.RenewalEnd)
                            {
                                if (szWherePolicy.Trim() == "")
                                {
                                    szWherePolicy += " AND ((UW_POLICY.ID = " + Convert.ToInt32(rowfields["ID"]) +
                                        " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["ID"]) + ")";
                                }
                                else
                                {
                                    szWherePolicy += " OR (UW_POLICY.ID = " + Convert.ToInt32(rowfields["ID"]) +
                                        " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["ID"]) + ")";
                                }
                            }
                            else
                            {
                                if (rowfields["PARENT_POLICY_ID"] != null)
                                {
                                    if (szWherePolicy.Trim() == "")
                                    {
                                        szWherePolicy += " AND ((UW_POLICY.ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) +
                                            " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) + ")";
                                    }
                                    else
                                    {
                                        szWherePolicy += " OR (UW_POLICY.ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) +
                                            " OR UW_POLICY.PARENT_POLICY_ID = " + Convert.ToInt32(rowfields["PARENT_POLICY_ID"]) + ")";
                                    }
                                }
                            }
                        }
                        if (szWherePolicy != "")
                        {
                            szWherePolicy += ")";
                        }

                        var szWhere =
                            " UW_ROOT.COMPANY_ID = " + m_company_id +
                            " AND UW_POLICY.CONTRACT_TYPE_ID IN (" + (int)Enums.ContractType.Policy + "," +
                                                                     (int)Enums.ContractType.RenewalEnd + "," +
                                                                     (int)Enums.ContractType.Endorsement + ")" +
                            " AND CERTIF_NO IS NULL AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                            " AND UW_POLICY.IS_DRAFT = 0 " + szWherePolicy;

                        var szSql =
                            " SELECT " +
                            " UW_POLICY_COVER.FLAG, " +
                            " UW_POLICY_COVER.COVER_ID, " +
                            " LIMIT_LIFE_TIME, " +
                            " COINS_DESC " +
                            " FROM UW_POLICY_COVER " +
                            " LEF JOIN UW_COINS ON UW_POLICY_COVER.CO_INS_ID = UW_COINS.ID " +
                            " WHERE " + szWhere +
                            " AND (('" + _asAt + "' BETWEEN UW_POLICY_COVER.EFFECTIVE_DATE AND UW_POLICY_COVER.EXPIRY_DATE) OR " +
                            " (UW_POLICY_COVER.EXPIRY_DATE IS NULL AND '" + _asAt + "' >= UW_POLICY_COVER.EFFECTIVE_DATE)) " +
                            " ORDER BY UW_POLICY_COVER.POLICY_ID, UW_POLICY_COVER.ID ";

                        _listPolicyCovers = dbConn.Query<UW_POLICY_COVER>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();

                        m_ContractLastImageCoversPrepared = true;
                    }
                }
            }
        }

        private void GetCertificateLastImageCovers(
                        ref List<iris5.models.UW_POLICY_COVER> _listPolicyCovers,
                        int _policyId,
                        string _asAt)
        {
            if (m_ContractLastImageCoversPrepared)
            {
                return;
            }

            string szWhere = null;

            if (this.m_SubBranchID == Enums.SubBranches.Health &&
                _UW_HealthGetLastImageInEndorsement == true)
            {
                var szSqlCert =
                    " SELECT " +
                    " TOP 1 CERTIF_NO, " +
                    " UW_POLICY.ID " +
                    " FROM UW_POLICY " +
                    " WHERE CERTIF_NO IN (SELECT CERTIF_NO " +
                    " FROM UW_POLICY tPolicy " +
                    " WHERE tPolicy.ID = " + _policyId +
                    " AND tPolicy.CERTIF_NO IS NOT NULL " +
                    " AND UW_POLICY.ROOT_ID = tPolicy.ROOT_ID ) " +
                    " AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                    " ORDER BY UW_POLICY.DATE_EFFECTIVE DESC, ID DESC ";

                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    var result = dbConn.Query(szSqlCert, commandTimeout: 1200).FirstOrDefault();
                    if (result != null)
                    {
                        var rowfields = result as IDictionary<string, object>;
                        _policyId = Convert.ToInt32(rowfields["ID"]);

                        var szSql =
                            " SELECT " +
                            " UW_POLICY_COVER.COVER_ID, " +
                            " LIMIT_LIFE_TIME, " +
                            " COINS_DESC " +
                            " FROM UW_POLICY_COVER " +
                            " LEFT JOIN UW_COINS ON UW_POLICY_COVER.CO_INS_ID = UW_COINS.ID " +
                            " WHERE UW_POLICY_COVER.POLICY_ID = " + _policyId +
                            " AND (('" + _asAt + "' BETWEEN UW_POLICY_COVER.EFFECTIVE_DATE AND UW_POLICY_COVER.EXPIRY_DATE) OR " +
                            " (UW_POLICY_COVER.EXPIRY_DATE IS NULL AND '" + _asAt + "' >= UW_POLICY_COVER.EFFECTIVE_DATE)) " +
                            " ORDER BY UW_POLICY_COVER.POLICY_ID, UW_POLICY_COVER.ID ";

                        _listPolicyCovers = dbConn.Query<UW_POLICY_COVER>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();

                        m_ContractLastImageCoversPrepared = true;
                        return;
                    }
                    else
                    {
                        m_ContractLastImageCoversPrepared = true;
                        return;
                    }
                }
            }
            else
            {
                szWhere =
                    " UW_ROOT.COMPANY_ID = " + m_company_id +
                    " AND (UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.AccountableCertificate +
                    //" OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.GroupOPC +
                    " OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Endorsement +
                    " OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate + ")" +
                    " AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                    " AND UW_POLICY.IS_DRAFT = 0 " +
                    " AND (UW_POLICY.ID = " + _policyId +
                    " OR UW_POLICY.PARENT_POLICY_ID = " + _policyId + ")";

                var szSql =
                    "SELECT " +
                    "UW_POLICY_COVER.FLAG, " +
                    "UW_POLICY_COVER.COVER_ID, " +
                    "COINS_DESC " +
                    "FROM UW_POLICY_COVER " +
                    "LEFT JOIN UW_COINS ON UW_POLICY_COVER.CO_INS_ID =  UW_COINS.ID " +
                    " WHERE " + szWhere +
                    " AND (('" + _asAt + "' BETWEEN UW_POLICY_COVER.EFFECTIVE_DATE AND UW_POLICY_COVER.EXPIRY_DATE) OR " +
                    "(UW_POLICY_COVER.EXPIRY_DATE IS NULL AND '" + _asAt + "' >= UW_POLICY_COVER.EFFECTIVE_DATE)) " +
                    "ORDER BY UW_POLICY_COVER.POLICY_ID, UW_POLICY_COVER.ID ";

                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    var result = dbConn.Query(szSql, commandTimeout: 1200).ToList();
                    if (result != null)
                    {
                        foreach (var row in result)
                        {
                            //TODO: IRIS5 check the logic here
                            //var rowfields = var as IDictionary<string, object>;
                            //
                            //to be elaborated later
                            //we have to read the covers and insert them to a dataset and check if the cover already exists in the dataset
                            //If it exists, we only update the COINS_DESC 
                            //Another test should be done to check if the cover flag = D
                            //
                        }

                        m_ContractLastImageCoversPrepared = true;
                        return;
                    }
                    else
                    {
                        m_ContractLastImageCoversPrepared = true;
                        return;
                    }
                }
            }
        }

