        private void GetSimpleCertificateLastImageCovers(
                ref List<iris5.models.UW_POLICY_COVER> _listPolicyCovers,
                int _rootId,
                string _asAt,
                int _certifNo)
        {
            if (m_ContractLastImageCoversPrepared)
            {
                return;
            }

            string szSql =
                " SELECT TOP 1 ID " +
                " FROM UW_POLICY " +
                " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                " WHERE UW_ROOT.COMPANY_ID = " + m_company_id +
                " AND UW_ROOT.ID = " + _rootId +
                " AND CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                " AND UW_POLICY.CERTIF_NO = '" + _certifNo + "'" +
                " AND UW_POLICY.DATE_EFFECTIVE <= '" + _asAt + "'" +
                " AND IS_DRAFT = 0 " +
                " ORDER BY DATE_EFFECTIVE DESC, ID DESC ";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.QueryFirstOrDefault<int?>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                if (result != null)
                {
                    var iCertificateID = result;

                    var szCovers =
                        "SELECT " +
                        "UW_POLICY_COVER.* " +
                        "FROM UW_POLICY_COVER " +
                        "LEFT JOIN UW_POLICY ON UW_POLICY_COVER.POLICY_ID = UW_POLICY.ID " +
                        "LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                        " WHERE UW_POLICY.ID = " + iCertificateID;

                    _listPolicyCovers = dbConn.Query<UW_POLICY_COVER>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();

                    m_ContractLastImageCoversPrepared = true;
                    return;
                }
                else
                {
                    m_ContractLastImageCoversPrepared = true;
                    return;
                }
            }
        }

