        #region  Various 

        public Structures.PolicyClaimsInfo GetPolicyClaimsInfoByPolicyID(int _policyId, int _curId)
        {
            Structures.PolicyClaimsInfo oPolicyClaimsInfo = new Structures.PolicyClaimsInfo();
            decimal nOS = 0M;
            decimal nPaid = 0M;
            decimal nRecovered = 0M;

            string dAsAt = DateTime.Today.Date.ToString("yyyy/MM/dd");
            string szWhere = "";

            szWhere += " WHERE CL_CLAIM.POLICY_ID = " + _policyId;

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                //var _cl_os_based_on_po = System.Convert.ToBoolean(dbConn.QueryFirstOrDefault<int>("SELECT CL_OS_BASED_ON_PO FROM CORE_AD"));
                var ad = dbConn.QueryFirstOrDefault<CORE_AD>("SELECT * FROM CORE_AD");
                var _cl_os_based_on_po = System.Convert.ToBoolean(ad.cl_os_based_on_po);
                var _cl_os_uses_claimed_amt = System.Convert.ToBoolean(ad.cl_os_uses_claimed_amt);

                var szSql = "";

                #region Claims Paid 

                if (_cl_os_based_on_po)
                {
                    szSql =
                        " SELECT " +
                        " RP_MVMT.AMOUNT AS PAID_AMT, " +
                        " RP_MVMT.MVMT_DATE AS TRS_DATE, " +
                        " RP_MVMT.CUR_ID, " +
                        " RP_MVMT.BASE_CUR_RATE," +
                        " RP_MVMT.COUNTER_CUR_RATE " +
                        " FROM RP_MVMT " +
                        " INNER JOIN CL_CLAIM_ASSESSMENT ON RP_MVMT.LINK_ID =  CL_CLAIM_ASSESSMENT.ID AND " +
                        " RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments +
                        " INNER JOIN CL_CLAIM ON CL_CLAIM_ASSESSMENT.CLAIM_ID = CL_CLAIM.ID ";

                    szSql += szWhere +
                        " AND MVMT_DATE IS NOT NULL AND MVMT_DATE <= '" + dAsAt + "'" +
                        " AND RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments;
                    //" AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 0 ";
                }
                else
                {
                    szSql =
                        " SELECT " +
                        " GL_TRS_ALLOCAT.PAID_AMT, " +
                        " GL_TRS.TRS_DATE, " +
                        " GL_TRS_ALLOCAT.CUR_ID, " +
                        " GL_TRS_ALLOCAT.BASE_CUR_RATE, " +
                        " GL_TRS_ALLOCAT.COUNTER_CUR_RATE " +
                        " FROM GL_TRS_ALLOCAT " +
                        " INNER JOIN RP_MVMT ON GL_TRS_ALLOCAT.MVMT_ID = RP_MVMT.ID " +
                        " INNER JOIN GL_TRS ON GL_TRS_ALLOCAT.TRS_ID = GL_TRS.ID " +
                        " INNER JOIN CL_CLAIM_ASSESSMENT ON RP_MVMT.LINK_ID =  CL_CLAIM_ASSESSMENT.ID AND " +
                        " RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments +
                        " INNER JOIN CL_CLAIM ON CL_CLAIM_ASSESSMENT.CLAIM_ID = CL_CLAIM.ID ";

                    szSql += szWhere +
                        " AND TRS_DATE IS NOT NULL AND TRS_DATE <= '" + dAsAt + "'" +
                        " AND RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments;

                    //                    " AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 0 ";
                }

                var resultPaid = dbConn.Query(szSql, commandTimeout: 1200).ToList();
                if (resultPaid != null)
                {
                    foreach (var row in resultPaid)
                    {
                        var rowfields = row as IDictionary<string, object>;

                        if (rowfields["CUR_ID"] != null)
                        {
                            if (Convert.ToInt32(rowfields["CUR_ID"]) == _curId)
                            {
                                nPaid += Convert.ToDecimal(rowfields["PAID_AMT"]);
                            }
                            else
                            {
                                if (_curId == m_baseCurId)
                                {
                                    nPaid += Convert.ToDecimal(rowfields["PAID_AMT"]) * Convert.ToDecimal(rowfields["BASE_CUR_RATE"]);
                                }
                                else if (_curId == m_counterCurId)
                                {
                                    if (Convert.ToDecimal(rowfields["COUNTER_CUR_RATE"]) != 0)
                                    {
                                        nPaid += Convert.ToDecimal(rowfields["PAID_AMT"]) / Convert.ToDecimal(rowfields["COUNTER_CUR_RATE"]);
                                    }
                                }
                                else
                                {
                                    nPaid += Helper.ConvertAmount(connStr,
                                                                  Convert.ToDecimal(rowfields["PAID_AMT"]),
                                                                  Convert.ToInt32(rowfields["CUR_ID"]),
                                                                  Convert.ToDateTime(rowfields["TRS_DATE"]),
                                                                  _curId, 2);
                                }
                            }
                        }
                    }

                    oPolicyClaimsInfo.Paid = nPaid;
                }

                #endregion Claims Paid 

                #region Claims Recovered 

                if (_cl_os_based_on_po)
                {
                    szSql =
                        " SELECT " +
                        " RP_MVMT.AMOUNT AS PAID_AMT, " +
                        " RP_MVMT.MVMT_DATE AS TRS_DATE, " +
                        " RP_MVMT.CUR_ID, " +
                        " RP_MVMT.BASE_CUR_RATE," +
                        " RP_MVMT.COUNTER_CUR_RATE " +
                        " FROM RP_MVMT " +
                        " INNER JOIN CL_CLAIM_RECOVERY ON RP_MVMT.LINK_ID = CL_CLAIM_RECOVERY.ID AND " +
                        " RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimRecoveries +
                        " INNER JOIN CL_CLAIM ON CL_CLAIM_RECOVERY.CLAIM_ID = CL_CLAIM.ID ";

                    szSql += szWhere +
                        " AND MVMT_DATE IS NOT NULL AND MVMT_DATE <= '" + dAsAt + "'" +
                        " AND RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimRecoveries;
                    //" AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 1 ";
                }
                else
                {
                    szSql =
                        "SELECT" +
                        " GL_TRS_ALLOCAT.PAID_AMT, " +
                        " GL_TRS.TRS_DATE, " +
                        " GL_TRS_ALLOCAT.CUR_ID, " +
                        " GL_TRS_ALLOCAT.BASE_CUR_RATE," +
                        " GL_TRS_ALLOCAT.COUNTER_CUR_RATE " +
                        " FROM GL_TRS_ALLOCAT " +
                        " INNER JOIN RP_MVMT ON GL_TRS_ALLOCAT.MVMT_ID = RP_MVMT.ID " +
                        " INNER JOIN GL_TRS ON GL_TRS_ALLOCAT.TRS_ID = GL_TRS.ID " +
                        " INNER JOIN CL_CLAIM_RECOVERY ON RP_MVMT.LINK_ID =  CL_CLAIM_RECOVERY.ID AND " +
                        " RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimRecoveries +
                        " INNER JOIN CL_CLAIM ON CL_CLAIM_RECOVERY.CLAIM_ID = CL_CLAIM.ID ";

                    szSql += szWhere +
                        " AND TRS_DATE IS NOT NULL AND TRS_DATE <= '" + dAsAt + "'" +
                        " AND RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimRecoveries;
                    //" AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 1 ";
                }

                var resultRecovered = dbConn.Query(szSql, commandTimeout: 1200).ToList();
                if (resultRecovered != null)
                {
                    foreach (var row in resultRecovered)
                    {
                        var rowfields = row as IDictionary<string, object>;

                        if (rowfields["CUR_ID"] != null)
                        {
                            if (Convert.ToInt32(rowfields["CUR_ID"]) == _curId)
                            {
                                nRecovered += Convert.ToDecimal(rowfields["PAID_AMT"]);
                            }
                            else
                            {
                                if (_curId == m_baseCurId)
                                {
                                    nRecovered += Convert.ToDecimal(rowfields["PAID_AMT"]) * Convert.ToDecimal(rowfields["BASE_CUR_RATE"]);
                                }
                                else if (_curId == m_counterCurId)
                                {
                                    if (Convert.ToDecimal(rowfields["COUNTER_CUR_RATE"]) != 0)
                                    {
                                        nRecovered += Convert.ToDecimal(rowfields["PAID_AMT"]) / Convert.ToDecimal(rowfields["COUNTER_CUR_RATE"]);
                                    }
                                }
                                else
                                {
                                    nRecovered += Helper.ConvertAmount(connStr,
                                                                       Convert.ToDecimal(rowfields["PAID_AMT"]),
                                                                       Convert.ToInt32(rowfields["CUR_ID"]),
                                                                       Convert.ToDateTime(rowfields["TRS_DATE"]),
                                                                       _curId,
                                                                       2);
                                }
                            }
                        }
                    }

                    oPolicyClaimsInfo.Recovered = nRecovered;
                }

                #endregion Claims Recovered 

                #region Claims OS

                var whereOS = " WHERE UW_POLICY.ID = " + this.m_ACCT_parent_policy_id;

                PncOSClaimHelper pncOSClmHler = new PncOSClaimHelper();
                var resultOS = pncOSClmHler.GetOSClaims(connStr, "reserve", whereOS, "", DateTime.Today.ToString("yyyy/MM/dd"), _cl_os_based_on_po, _cl_os_uses_claimed_amt);

                if (resultOS != null && resultOS.Count > 0)
                {
                    foreach (var row in resultOS)
                    {
                        if (row.cur_id == _curId)
                        {
                            nOS += row.os_amt;
                        }
                        else
                        {
                            if (_curId == m_baseCurId)
                            {
                                nOS += row.os_amt * row.base_cur_rate;
                            }
                            else if (_curId == m_counterCurId)
                            {
                                if (row.counter_cur_rate != 0)
                                {
                                    nOS += row.os_amt / row.counter_cur_rate;
                                }
                                else
                                {
                                    nOS += row.os_amt;
                                }
                            }
                            else
                            {
                                nOS += Helper.ConvertAmount(connStr,
                                                            row.os_amt,
                                                            row.cur_id,
                                                            Convert.ToDateTime(dAsAt),
                                                            _curId,
                                                            2);
                            }
                        }
                    }
                }

                oPolicyClaimsInfo.Outstanding = nOS;
            }

            #endregion Claims OS

            oPolicyClaimsInfo.CurID = _curId;

            return oPolicyClaimsInfo;
        }

