        private string FnTotalClaims()
        {
            decimal nPaid = 0M;

            if (this.m_TotalClaimsPrepared)
            {
                nPaid = this.m_TotalClaims;
            }
            else
            {

                m_TotalClaimsPrepared = true;

                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    //AN 2025-08-21
                    var coreOption = dbConn.QueryFirstOrDefault<CORE_OPTION>("SELECT TOP 1 * FROM CORE_OPTION");


                    var _cl_os_based_on_po = System.Convert.ToBoolean(dbConn.QueryFirstOrDefault<int>("SELECT CL_OS_BASED_ON_PO FROM CORE_AD"));

                    var szSql = "";
                    if (_cl_os_based_on_po)
                    {
                        szSql =
                            " SELECT " +
                            " CASE WHEN RP_MVMT.CUR_ID = " + m_counterCurId +
                            " AND RP_MVMT.COUNTER_CUR_RATE <> 0 THEN Round(RP_MVMT.AMOUNT / RP_MVMT.COUNTER_CUR_RATE , " + coreOption.counter_cur_decimal_places + ") " +
                            " ELSE dbo.FN_CONVERT_AMT(RP_MVMT.AMOUNT, RP_MVMT.CUR_ID, '" +
                            DateTime.Today.ToString("yyyy/MM/dd") + "' , " + m_counterCurId + "," + m_baseCurId + "," + m_counterCurId + ") END PAID_AMT " +
                            "FROM CL_CLAIM " +
                            "LEFT JOIN CL_CLAIM_ASSESSMENT ON CL_CLAIM.ID = CL_CLAIM_ASSESSMENT.CLAIM_ID " +
                            "LEFT JOIN RP_MVMT ON RP_MVMT.LINK_ID = CL_CLAIM_ASSESSMENT.ID " +
                            " WHERE RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments +
                            " AND CL_CLAIM.POLICY_ID = " + this.m_ACCT_parent_policy_id;

                        //                    " WHERE ((RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments +
                        //"       AND RP_MVMT.AMOUNT <> 0 " +
                        //"       AND NOT (CL_CLAIM_ASSESSMENT.IS_CANCELLATION = 1 AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 1 ) )" +
                        //"  OR (RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimRecoveries +
                        //" AND RP_MVMT.AMOUNT <> 0" +
                        //" AND CL_CLAIM_ASSESSMENT.IS_CANCELLATION = 1 AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 0 )) " +
                    }
                    else
                    {
                        szSql =
                            " SELECT " +
                            " CASE WHEN RP_MVMT.CUR_ID = " + m_counterCurId +
                            " AND GL_TRS_ALLOCAT.COUNTER_CUR_RATE <> 0 THEN " +
                            " Round(GL_TRS_ALLOCAT.PAID_AMT / GL_TRS_ALLOCAT.COUNTER_CUR_RATE, " + coreOption.counter_cur_decimal_places + ") " +
                            " ELSE dbo.FN_CONVERT_AMT(GL_TRS_ALLOCAT.PAID_AMT, GL_TRS_ALLOCAT.CUR_ID, '" +
                            DateTime.Today.ToString("yyyy/MM/dd") + "' , " +
                            m_counterCurId + "," + m_baseCurId + "," + m_counterCurId + ") END PAID_AMT " +
                            "FROM CL_CLAIM " +
                            "LEFT JOIN CL_CLAIM_ASSESSMENT ON CL_CLAIM.ID = CL_CLAIM_ASSESSMENT.CLAIM_ID " +
                            "LEFT JOIN RP_MVMT ON RP_MVMT.LINK_ID = CL_CLAIM_ASSESSMENT.ID " +
                            "LEFT JOIN GL_TRS_ALLOCAT ON GL_TRS_ALLOCAT.MVMT_ID = RP_MVMT.ID " +
                            " WHERE RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments +
                            " AND CL_CLAIM.POLICY_ID = " + this.m_ACCT_parent_policy_id;

                        //                    " WHERE ((RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimPayments +
                        //"       AND GL_TRS_ALLOCAT.PAID_AMT <> 0 " +
                        //"       AND NOT (CL_CLAIM_ASSESSMENT.IS_CANCELLATION = 1 AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 1 ) )" +
                        //" OR (RP_MVMT.LINK_TYPE_ID = " + (int)Enums.LinksTypes.ClaimRecoveries +
                        //"       AND GL_TRS_ALLOCAT.PAID_AMT <> 0 " +
                        //"       AND CL_CLAIM_ASSESSMENT.IS_CANCELLATION = 1 AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 0 )) " +
                    }

                    if (GlobalVariables.DbType == "ORACLE")
                    {
                        szSql = szSql.Replace("ISNULL", "NVL");
                        szSql = szSql.Replace("DBO.", "");
                    }
                    var result = dbConn.Query<decimal>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();
                    if (result != null)
                    {
                        foreach (var paidAmt in result)
                        {
                            //var rowfields = row as IDictionary<string, object>;
                            //nPaid += (Convert.ToBoolean(rowfields["IS_CANCELLATION"]) == true ? -Convert.ToDecimal(rowfields["PAID_AMT"]) : Convert.ToDecimal(rowfields["PAID_AMT"]));
                            nPaid += paidAmt;
                        }

                        this.m_TotalClaims = nPaid;

                        //return "Convert.ToDecimal(\"" + nPaid + "\")" + " ";
                    }
                    //else
                    //{
                    //    return "Convert.ToDecimal(\"" + 0 + "\")" + " ";
                    //}
                }
            }

            // OS 
            decimal nOS = 0M;

            if (this.m_ListClaimOS == null || this.m_ListClaimOS.Count == 0)
            {
                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    //var _cl_os_based_on_po = System.Convert.ToBoolean(dbConn.QueryFirstOrDefault<int>("SELECT CL_OS_BASED_ON_PO FROM CORE_AD"));
                    var ad = dbConn.QueryFirstOrDefault<CORE_AD>("SELECT * FROM CORE_AD");
                    var _cl_os_based_on_po = System.Convert.ToBoolean(ad.cl_os_based_on_po);
                    var _cl_os_uses_claimed_amt = System.Convert.ToBoolean(ad.cl_os_uses_claimed_amt);

                    var whereOS = " WHERE UW_POLICY.ID = " + this.m_ACCT_parent_policy_id;

                    PncOSClaimHelper pncOSClmHler = new PncOSClaimHelper();
                    var resultOS = pncOSClmHler.GetOSClaims(connStr, "reserve", whereOS, "", DateTime.Today.ToString("yyyy/MM/dd"), _cl_os_based_on_po, _cl_os_uses_claimed_amt);

                    if (resultOS.Count > 0)
                    {
                        foreach (var row in resultOS)
                        {
                            this.FillListClaimOS(row);
                            nOS += row.os_amt / row.counter_cur_rate;
                        }
                    }
                }
            }
            else
            {
                for (int i = 0; i < m_ListClaimOS.Count; i++)
                {
                    nOS += m_ListClaimOS.ElementAt(i).os_amt / m_ListClaimOS.ElementAt(i).counter_cur_rate;
                }
            }

            //if (nOS > 0M)
            //{
            //    return "Convert.ToDecimal(\"" + nOS + "\")" + " ";
            //}
            //else
            //{
            //    return "Convert.ToDecimal(\"" + 0 + "\")" + " ";
            //}

            return "Convert.ToDecimal(\"" + nOS + nPaid + "\")" + " ";
        }

        private int FnIsSanctionedNationality()
        {
            var insuredId = -1;
            var clientId = -1;
            var payerId = -1;
            var holderId = -1;

            if (this.p_isLife)
            {
                insuredId = this.p_LifePolicyDto.policy.insured_id;
                clientId = this.p_LifePolicyDto.policy.client_id == null ? -1 : (int)this.p_LifePolicyDto.policy.client_id;
                payerId = this.p_LifePolicyDto.policy.payer_id;
            }
            else
            {
                insuredId = this.m_policyDto.policy.insured_id;
                clientId = this.m_policyDto.policy.client_id == null ? -1 : (int)this.m_policyDto.policy.client_id;
                holderId = this.m_policyDto.policy.holder_id;
                payerId = this.m_policyDto.policy.payer_id;
            }

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var szSql =
                 @" SELECT NATIONALITY_ID 
                 FROM PF_CONTACT 
                 INNER JOIN PF_PROFILE ON PF_CONTACT.ID = PF_PROFILE.CONTACT_ID 
                 WHERE PF_PROFILE.ID = " + insuredId;

                var nationalityId = dbConn.QueryFirstOrDefault<int?>(szSql);
                if (nationalityId != null && nationalityId > 0)
                {
                    szSql =
                        " SELECT IS_SANCTIONED " +
                        " FROM CORE_COUNTRY " +
                        " WHERE CORE_COUNTRY.ID = " + nationalityId;

                    var result = dbConn.QueryFirstOrDefault<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                    if (result == 1)
                    {
                        return result;
                    }
                }


                if (clientId != -1 && clientId != insuredId)
                {
                    szSql =
                          @" SELECT NATIONALITY_ID 
                         FROM PF_CONTACT 
                         INNER JOIN PF_PROFILE ON PF_CONTACT.ID = PF_PROFILE.CONTACT_ID 
                         WHERE PF_PROFILE.ID = " + clientId;

                    nationalityId = dbConn.QueryFirstOrDefault<int?>(szSql);
                    if (nationalityId != null && nationalityId > 0)
                    {
                        szSql =
                            " SELECT IS_SANCTIONED " +
                            " FROM CORE_COUNTRY " +
                            " WHERE CORE_COUNTRY.ID = " + nationalityId;

                        var result = dbConn.QueryFirstOrDefault<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                        if (result == 1)
                        {
                            return result;
                        }
                    }
                }

                if (holderId != -1 && holderId != insuredId)
                {
                    szSql =
                          @" SELECT NATIONALITY_ID 
                         FROM PF_CONTACT 
                         INNER JOIN PF_PROFILE ON PF_CONTACT.ID = PF_PROFILE.CONTACT_ID 
                         WHERE PF_PROFILE.ID = " + holderId;

                    nationalityId = dbConn.QueryFirstOrDefault<int?>(szSql);
                    if (nationalityId != null && nationalityId > 0)
                    {
                        szSql =
                            " SELECT IS_SANCTIONED " +
                            " FROM CORE_COUNTRY " +
                            " WHERE CORE_COUNTRY.ID = " + nationalityId;

                        var result = dbConn.QueryFirstOrDefault<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                        if (result == 1)
                        {
                            return result;
                        }
                    }
                }


                szSql =
                    @" SELECT NATIONALITY_ID 
                             FROM PF_CONTACT 
                             INNER JOIN PF_PROFILE ON PF_CONTACT.ID = PF_PROFILE.CONTACT_ID 
                             WHERE PF_PROFILE.ID = " + payerId;

                nationalityId = dbConn.QueryFirstOrDefault<int?>(szSql);
                if (nationalityId != null && nationalityId > 0)
                {
                    szSql =
                        " SELECT IS_SANCTIONED " +
                        " FROM CORE_COUNTRY " +
                        " WHERE CORE_COUNTRY.ID = " + nationalityId;

                    var result = dbConn.QueryFirstOrDefault<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                    if (result == 1)
                    {
                        return result;
                    }
                }

                return 0;
            }
        }

