        private int FnIsSubBrokerComGreaterThanBrokerCom()
        {
            decimal highestMainBrokerCom = 0;
            decimal highestSubBrokerCom = 0;
            bool isThereSubBrokerCom = false; // todo giorgio 24-Sep-2024 LIA-4166

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                if (this.p_isLife)
                {
                    // todo giorgio 17/7/2024 LIA-3493
                    // string szSql = "SELECT * FROM LF_POLICY_COMMISSION WHERE POLICY_ID = @POLICY_ID";
                    // var commisions = dbConn.Query<LF_POLICY_COMMISSION>(szSql, new { POLICY_ID = this.p_LifePolicyDto.policy.id }).ToList();

                    var polBroker = p_LifePolicyDto.policy_commission.FirstOrDefault(x => x.profile_id == this.p_LifePolicyDto.policy.broker_id);

                    if (polBroker != null)
                    {
                        highestMainBrokerCom = polBroker.amount;
                    }

                    foreach (var commision in p_LifePolicyDto.policy_commission)
                    {
                        if (commision.profile_type_id == 8 && commision.amount > highestSubBrokerCom) // sub-broker
                        {
                            isThereSubBrokerCom = true; // todo giorgio 24-Sep-2024 LIA-4166
                            highestSubBrokerCom = commision.amount;
                        }
                    }
                }
                else
                {
                    // todo giorgio 17/7/2024 LIA-3493
                    // string szSql = "SELECT * FROM UW_POLICY_COMMISSION WHERE POLICY_ID = @POLICY_ID";
                    // var commisions = dbConn.Query<UW_POLICY_COMMISSION>(szSql, new { POLICY_ID = this.p_policyDto.policy.id }).ToList();
                    // end todo giorgio 17/7/2024 LIA-3493

                    var polBroker = p_policyDto.policy_commission.FirstOrDefault(x => x.profile_id == this.p_policyDto.policy.broker_id);

                    if (polBroker != null)
                    {
                        highestMainBrokerCom = polBroker.amount;
                    }

                    foreach (var commision in p_policyDto.policy_commission)
                    {
                        if (commision.profile_type_id == 8 && commision.amount > highestSubBrokerCom) // sub-broker
                        {
                            isThereSubBrokerCom = true; // todo giorgio 24-Sep-2024 LIA-4166
                            highestSubBrokerCom = commision.amount;
                        }
                    }
                }
            }

            // todo giorgio 24-Sep-2024 LIA-4166
            if (isThereSubBrokerCom)
            {
                return highestSubBrokerCom > highestMainBrokerCom ? 1 : 0;
            }
            else
            {
                return 0;
            }

            //return highestSubBrokerCom > highestMainBrokerCom ? 1 : 0;
            // end todo giorgio 24-Sep-2024 LIA-4166
        }
