        private int FnIsSanctionedSMACountry()
        {
            var szSql = "";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                if (this.p_isLife)
                {
                    foreach (var polProperty in this.p_LifePolicyDto.policy_property)
                    {
                        if (polProperty.system_table != null && polProperty.system_table != "" && polProperty.system_table == "CORE_COUNTRY" &&
                            polProperty.the_value != null && polProperty.the_value != "")
                        {
                            szSql =
                              " SELECT IS_SANCTIONED " +
                              " FROM CORE_COUNTRY " +
                              " WHERE CORE_COUNTRY.ID = " + polProperty.the_value;

                            var result = dbConn.QueryFirstOrDefault<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                            if (result == 1) // sanctioned
                            {
                                return result;
                            }
                        }
                    }
                }
                else //P&C
                {
                    foreach (var polProperty in this.m_policyDto.policy_property)
                    {
                        if (polProperty.system_table != null && polProperty.system_table != "" && polProperty.system_table == "CORE_COUNTRY" &&
                            polProperty.the_value != null && polProperty.the_value != "")
                        {
                            szSql =
                              " SELECT IS_SANCTIONED " +
                              " FROM CORE_COUNTRY " +
                              " WHERE CORE_COUNTRY.ID = " + polProperty.the_value;

                            var result = dbConn.QueryFirstOrDefault<int>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                            if (result == 1) // sanctioned
                            {
                                return result;
                            }
                        }
                    }
                }

                return 0;
            }
        }

