        private string FnIsNull(ArrayList _Parameters)
        {
            bool blResult = false;
            if (_Parameters.Count == 0)
            {
                blResult = true;
            }
            else
            {
                if (Convert.ToString(_Parameters[0]) == "")
                {
                    blResult = true;
                }
            }

            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }

        private string FnAdd(ArrayList _Parameters)
        {
            decimal nResult = 0M;

            _processDecimalParameters(ref _Parameters); // giorgio 26-mar-2026 BNK-534

            nResult = Convert.ToDecimal(_Parameters[0]) + Convert.ToDecimal(_Parameters[1]);

            return "Convert.ToDecimal(\"" + nResult + "\")" + " ";
        }

        // giorgio 26-mar-2026 BNK-534
        private ArrayList _processDecimalParameters(ref ArrayList _Parameters)
        {
            if (Pixel.Core.Lib.CoreHelper.IsNumeric(_Parameters[0]) == false)
            {
                var scanner = new _RuleScanner(_Parameters[0].ToString());

                if (scanner.StartsWith(PfxDecimal))
                {
                    _Parameters[0] = scanner.ParseToDecimal().Val;
                }
            }

            if (Pixel.Core.Lib.CoreHelper.IsNumeric(_Parameters[1]) == false)
            {
                var scanner = new _RuleScanner(_Parameters[1].ToString());

                if (scanner.StartsWith(PfxDecimal))
                {
                    _Parameters[1] = scanner.ParseToDecimal().Val;
                }
            }

            return _Parameters;
        }
        // end giorgio 26-mar-2026 BNK-534

        private string FnSubstract(ArrayList _Parameters)
        {
            decimal nResult = 0M;

            _processDecimalParameters(ref _Parameters); // giorgio 26-mar-2026 BNK-534

            nResult = Convert.ToDecimal(_Parameters[0]) - Convert.ToDecimal(_Parameters[1]);

            return "Convert.ToDecimal(\"" + nResult + "\")" + " ";
        }

        private string FnMultiply(ArrayList _Parameters)
        {
            decimal nResult = 0M;

            _processDecimalParameters(ref _Parameters); // giorgio 26-mar-2026 BNK-534

            nResult = Convert.ToDecimal(_Parameters[0]) * Convert.ToDecimal(_Parameters[1]);

            return "Convert.ToDecimal(\"" + nResult + "\")" + " ";
        }

        private string FnDivide(ArrayList _Parameters)
        {
            decimal nResult = 0M;

            _processDecimalParameters(ref _Parameters); // giorgio 26-mar-2026 BNK-534

            if (Convert.ToDecimal(_Parameters[1]) != 0)
            {
                nResult = Convert.ToDecimal(_Parameters[0]) / Convert.ToDecimal(_Parameters[1]);
            }
            else
            {
                nResult = Convert.ToDecimal(_Parameters[0]);
            }

            return "Convert.ToDecimal(\"" + nResult + "\")" + " ";
        }

