        private string FnPreviousPolicyAction(ArrayList _parameters)
        {
            bool blResult = false;
            var szSql =
                "SELECT ACTION_ID " +
                "FROM UW_POLICY_ACTION " +
                " WHERE POLICY_ID = " + m_ACCT_parent_policy_id;

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).ToList();
                if (result != null)
                {
                    foreach (var row in result)
                    {
                        var rowfields = row as IDictionary<string, object>;
                        if (rowfields["ACTION_ID"] == _parameters[0])
                        {
                            blResult = true;
                            break;
                        }
                    }
                }
            }

            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }

        private string FnOldValue(ArrayList _Parameters, bool _UseAsParameter)
        {
            switch (_Parameters[0])
            {
                case "DimensionPolicy":
                    switch (_Parameters[1].ToString().ToUpper())
                    {
                        case "BRANCH":

                            var szSql =
                                "SELECT " +
                                "CORE_BRANCH.BRANCH_DESC " +
                                "FROM UW_POLICY " +
                                "LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID  " +
                                "LEFT JOIN CORE_BRANCH ON UW_ROOT.BRANCH_ID = CORE_BRANCH.ID  " +
                                " WHERE POLICY_ID = " + this.m_ACCT_parent_policy_id;

                            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                            {
                                dbConn.ConnectionString = connStr;
                                dbConn.Open();

                                var result = dbConn.QueryFirstOrDefault<string>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                                if (result != null)
                                {
                                    if (_UseAsParameter)
                                    {
                                        return result;
                                    }
                                    else
                                    {
                                        return "\"" + result + "\"" + " ";
                                    }
                                }
                            }

                            break;
                        default:

                            szAsAt = m_policyDto.policy.date_issue.ToString("yyyy/MM/dd");

                            if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Policy ||
                                m_policyDto.policy.contract_type_id == (int)Enums.ContractType.RenewalEnd ||
                                m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Endorsement)
                            {
                                this.GetContractLastImageData(ref m_PolicyLastImage, m_ACCT_parent_policy_id, szAsAt, false);

                            }
                            else if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Certificate)
                            {
                                this.GetSimpleCertificateLastImageData(ref m_PolicyLastImage, m_ACCT_parent_root_id, szAsAt, this.m_ACCT_parent_certif_no, false);

                            }
                            else if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.AccountableCertificate)
                            {
                                this.GetCertificateLastImageData(ref m_PolicyLastImage, m_ACCT_parent_policy_id, szAsAt, false);
                            }

                            //TODO: IRIS5 stopped by tony
                            //if (_UseAsParameter)
                            //{
                            //    return m_PolicyLastImage.policy[_Parameters[1]];
                            //}
                            //else
                            //{
                            //    return "Convert.ToDateTime(\"" + m_PolicyLastImage.policy[_Parameters[1].ToString()].ToString() + "\")" + " ";
                            //}   
                            return "";
                    }

                    break;
                case "DimensionSma":

                    szAsAt = m_policyDto.policy.date_issue.ToString("yyyy/MM/dd");

                    if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Policy ||
                        m_policyDto.policy.contract_type_id == (int)Enums.ContractType.RenewalEnd ||
                        m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Endorsement)
                    {
                        this.GetContractSmaLastImage(m_ACCT_parent_policy_id,
                                                           szAsAt,
                                                           ref m_PolicySmaLastImage);

                    }
                    else if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Certificate)
                    {
                        this.GetSimpleCertificateSmaLastImage(m_ACCT_parent_root_id,
                                                                    m_ACCT_parent_certif_no,
                                                                    szAsAt,
                                                                    ref m_PolicySmaLastImage);

                    }
                    else if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.AccountableCertificate)
                    {
                        this.GetCertificateSmaLastImage(m_ACCT_parent_policy_id,
                                                              szAsAt,
                                                              ref m_PolicySmaLastImage);

                    }
                    int objectPropertyId = Convert.ToInt32(_Parameters[1]);

                    for (int i = 0; i < m_PolicySmaLastImage.Count; i++)
                    {
                        if (m_PolicySmaLastImage.ElementAt(i).object_property_id == objectPropertyId)
                        {
                            if (_UseAsParameter)
                            {
                                return m_PolicySmaLastImage.ElementAt(i).the_value;
                            }
                            else
                            {
                                if (m_PolicySmaLastImage.ElementAt(i).the_value != "")
                                {
                                    return "\"" + m_PolicySmaLastImage.ElementAt(i).the_value + "\"";
                                }
                                else
                                {
                                    return ""; // it was -1
                                }
                            }
                        }
                    }
                    return "";// it was -1
            }
            return "";
        }

