        private string FnPrincipalValue(ArrayList _Parameters, bool _UseAsParameter)
        {
            switch (_Parameters[0])
            {
                case "DimensionSma":
                    if (m_policyDto.policy.principal_id != null)
                    {
                        var szSql =
                            " SELECT " +
                            " ROOT_ID, " +
                            " ID, " +
                            " CONTRACT_TYPE_ID, " +
                            " CERTIF_NO " +
                            " FROM UW_POLICY " +
                            " WHERE POLICY_NO = '" + m_policyDto.policy.policy_no + "' " +
                            " AND INSURED_ID = " + m_policyDto.policy.principal_id +
                            " AND CONTRACT_TYPE_ID IN (2,20)";

                        using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                        {
                            dbConn.ConnectionString = connStr;
                            dbConn.Open();

                            var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();
                            if (result != null && result.Count > 0)
                            {
                                szAsAt = m_policyDto.policy.date_issue.ToString("yyyy/MM/dd");

                                var rowfields = result as IDictionary<string, object>;

                                if ((Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == (int)Enums.ContractType.Policy) ||
                                    (Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == (int)Enums.ContractType.Endorsement))
                                {
                                    this.GetContractSmaLastImage(Convert.ToInt32(rowfields["ID"]),
                                                                      szAsAt,
                                                                      ref m_PolicySmaLastImage);
                                }
                                else if (Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == (int)Enums.ContractType.Certificate)
                                {
                                    this.GetSimpleCertificateSmaLastImage(Convert.ToInt32(rowfields["ROOT_ID"]),
                                                                                Convert.ToInt32(rowfields["CERTIF_NO"]),
                                                                                szAsAt,
                                                                                ref m_PolicySmaLastImage);
                                }
                                else if (Convert.ToInt32(rowfields["CONTRACT_TYPE_ID"]) == (int)Enums.ContractType.AccountableCertificate)
                                {
                                    this.GetCertificateSmaLastImage(Convert.ToInt32(rowfields["ID"]),
                                                                         szAsAt,
                                                                         ref m_PolicySmaLastImage);
                                }

                                int objectPropertyId = Convert.ToInt32(_Parameters[1]);

                                for (int i = 0; i < m_PolicySmaLastImage.Count; i++)
                                {
                                    if (m_PolicySmaLastImage.ElementAt(i).object_property_id == objectPropertyId)
                                    {
                                        if (_UseAsParameter)
                                        {
                                            return m_PolicySmaLastImage.ElementAt(i).the_value;
                                        }
                                        else
                                        {
                                            if (m_PolicySmaLastImage.ElementAt(i).the_value != "")
                                            {
                                                return "\"" + m_PolicySmaLastImage.ElementAt(i).the_value + "\"";
                                            }
                                            else
                                            {
                                                return "";//-1;
                                            }
                                        }
                                    }
                                }
                                return "";//-1;
                            }
                            else
                            {
                                return "";//-1;
                            }
                        }
                    }
                    else
                    {
                        return "";//-1;
                    }
            }

            return "";
        }

