        private string FnLossRatioByPolicy()
        {
            szAsAt = m_policyDto.policy.date_issue.ToString("yyyy/MM/dd");

            if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Policy ||
                m_policyDto.policy.contract_type_id == (int)Enums.ContractType.RenewalEnd ||
                m_policyDto.policy.contract_type_id == (int)Enums.ContractType.RenewalNotice ||
                m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Endorsement)
            {
                this.GetContractLastImageData(ref m_PolicyLastImage, m_ACCT_parent_policy_id, szAsAt, true);
            }
            else if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.Certificate)
            {
                this.GetSimpleCertificateLastImageData(ref m_PolicyLastImage, m_ACCT_parent_root_id, szAsAt, m_ACCT_parent_certif_no, true);

            }
            else if (m_policyDto.policy.contract_type_id == (int)Enums.ContractType.AccountableCertificate)
            {
                this.GetCertificateLastImageData(ref m_PolicyLastImage, m_ACCT_parent_policy_id, szAsAt, true);
            }

            decimal nNet = 0M;
            for (int i = 0; i < m_PolicyLastImage.policy_computation.Count; i++)
            {
                if (m_PolicyLastImage.policy_computation.ElementAt(i).comput_group_id == (int)Enums.ComputationsGroups.Net)
                {
                    nNet += m_PolicyLastImage.policy_computation.ElementAt(i).amount;
                    break;
                }
            }

            //// not valid  todo giorgio 15/4/2024 DEVIRIS5-12719
            //DateTime dEffective = DateTime.MinValue;
            //DateTime dExpiry = DateTime.MinValue;
            //DateTime dAsAt = DateTime.MinValue;
            //int iDaysInPeriod = 0;
            //int iDaysAsOf = 0;
            //decimal nEarnedNet = 0M;

            //if (m_PolicyLastImage.policy.date_expiry == null)
            //{
            //    dEffective = m_PolicyLastImage.policy.date_effective;
            //    dExpiry = m_PolicyLastImage.policy.date_effective.AddDays(45);
            //    dAsAt = DateTime.Today;

            //    if (dExpiry > dAsAt)
            //    {
            //        iDaysAsOf = Convert.ToInt32(DateExt.DateDiff(DateInterval.Day, dAsAt, dExpiry));
            //    }
            //    else
            //    {
            //        iDaysAsOf = 0;
            //    }

            //    iDaysInPeriod = Convert.ToInt32(DateExt.DateDiff(DateInterval.Day, dEffective, dExpiry));
            //}
            //else
            //{
            //    dEffective = m_PolicyLastImage.policy.date_effective;
            //    dExpiry = (DateTime)m_PolicyLastImage.policy.date_expiry;
            //    dAsAt = DateTime.Today;
            //    iDaysInPeriod = Convert.ToInt32(DateExt.DateDiff(DateInterval.Day, dEffective, dExpiry));
            //    iDaysAsOf = Convert.ToInt32(DateExt.DateDiff(DateInterval.Day, dAsAt, dExpiry));
            //}

            //if (iDaysAsOf > iDaysInPeriod || iDaysAsOf < 0)
            //{
            //    iDaysAsOf = 0;
            //}

            //if (iDaysInPeriod != 0)
            //{
            //    nEarnedNet = nNet - (nNet * iDaysAsOf / iDaysInPeriod);
            //}
            //else
            //{
            //    nEarnedNet = nNet;
            //}
            //// todo giorgio 15/4/2024 DEVIRIS5-12719

            decimal nLR = 0M;
            if (nNet != 0M)
            // not valid todo giorgio 15/4/2024 DEVIRIS5-12719
            //if (nEarnedNet != 0M)
            {
                var oPolicyClaimsInfo = this.GetPolicyClaimsInfoByPolicyID(m_PolicyLastImage.policy.id,
                                                                            m_PolicyLastImage.policy.premium_cur_id);
                nLR = (oPolicyClaimsInfo.Paid + oPolicyClaimsInfo.Outstanding - oPolicyClaimsInfo.Recovered) / nNet * 100;

                //not valid   todo giorgio 15/4/2024 DEVIRIS5-12719
                //nLR = (oPolicyClaimsInfo.Paid + oPolicyClaimsInfo.Outstanding - oPolicyClaimsInfo.Recovered) / nEarnedNet * 100;
            }

            return "Convert.ToDecimal(\"" + nLR + "\")" + " ";
        }

