        private string FnNumberOfRelatedInsured(ArrayList _Parameters)
        {
            string szType = null;

            var szSql =
                " SELECT " +
                " COUNT(*) AS iCount " +
                " FROM PF_PROFILE_RELATION " +
                " LEFT JOIN PF_PROFILE ON PF_PROFILE_RELATION.PROFILE_ID = PF_PROFILE.ID " +
                " LEFT JOIN PF_PROFILE_TYPE ON PF_PROFILE.PROFILE_TYPE_ID = PF_PROFILE_TYPE.ID " +
                " LEFT JOIN PF_CONTACT ON PF_PROFILE.CONTACT_ID = PF_CONTACT.ID " +
                " LEFT JOIN CORE_TYPE ON PF_CONTACT.GENDER = CORE_TYPE.ID AND CORE_TYPE.TYPE_TABLE = 'Gender' " +
                " LEFT JOIN PF_RELATION ON PF_PROFILE_RELATION.RELATION_ID = PF_RELATION.ID " +
                " INNER JOIN UW_POLICY ON PF_PROFILE.ID = UW_POLICY.INSURED_ID ";

            var szWhere =
                " WHERE PF_PROFILE_RELATION.MAIN_PROFILE_ID = " + m_policyDto.policy.insured_id +
                " AND PF_PROFILE_TYPE.PROFILE_ROOT_ID = " + (int)Enums.ProfileRoots.Insured +
                " AND PF_PROFILE_RELATION.IS_INACTIVE = 0 " +
                " AND PF_PROFILE.ID IN (SELECT INSURED_ID FROM UW_POLICY " +
                " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                " WHERE UW_ROOT.LOB_ID = " + m_policyDto.root.lob_id + ")" +
                " AND (";

            for (int i = 0; i < _Parameters.Count; i += 2)
            {
                switch (_Parameters[i])
                {
                    case "DimensionMember":
                        switch (_Parameters[i + 1])
                        {
                            case "INSURED_AGE":
                                string szRefDate = m_policyDto.policy.date_effective.ToString("yyyy/MM/dd");
                                szWhere += " DATEDIFF(year, PF_CONTACT.DOB, '" + szRefDate + "')";
                                szType = "Age";

                                break;
                            case "INSURED_GENDER":
                                szWhere += " CORE_TYPE.TYPE_DESC ";
                                szType = "Gender";

                                break;
                            case "INSURED_RELATION":
                                szWhere += " PF_RELATION.RELATION_DESC ";
                                szType = "Relation";
                                break;
                        }

                        break;

                    case "Operator":
                        if (_Parameters[i + 1].ToString() == "<=" || _Parameters[i + 1].ToString() == ">=")
                        {
                            szWhere += _Parameters[i + 1].ToString().Replace("<>", "!=") + " ";
                        }
                        else
                        {
                            szWhere += _Parameters[i + 1].ToString().Replace("=", "==").Replace("<>", "!=") + " ";
                        }
                        break;

                    case "LogOperator":
                        szWhere += _Parameters[i + 1].ToString().Replace("AND", "&&").Replace("OR", "||") + " ";

                        break;
                    case "DimensionValue":
                        if (szType == "Age")
                        {
                            szWhere += _Parameters[i + 1].ToString() + " ";
                        }
                        else
                        {
                            szWhere += "'" + _Parameters[i + 1].ToString() + "' ";
                        }
                        break;
                }
            }
            szWhere += ")";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();
                if (result != null && result.Count > 0)
                {
                    var rowfields = result as IDictionary<string, object>;

                    return "Convert.ToInt32(\"" + rowfields["iCount"] + "\")" + " ";
                }
                else
                {
                    return "Convert.ToInt32(\"" + 0 + "\")" + " ";
                }
            }
        }

        private string FnIsPolicyExistForSamePropertySameCob(ArrayList _parameters, ref string _infoMsg)
        {
            bool blResult = false;
            string szEffective = m_policyDto.policy.date_effective.ToString("yyyy/MM/dd");

            var szSql =
               " SELECT DISTINCT " +
               " UW_POLICY.POLICY_NO " +
               " FROM UW_POLICY " +
               " WHERE " +
               " UW_POLICY.IS_DRAFT = 0 " +
               " AND COB_ID = " + m_policyDto.policy.cob_id;

            var szSqlCert =
                " UNION ALL " +
                " SELECT DISTINCT " +
                " UW_POLICY.POLICY_NO " +
                " FROM UW_POLICY " +
                " WHERE " +
                " UW_POLICY.IS_DRAFT = 0 " +
                " AND COB_ID = " + m_policyDto.policy.cob_id;

            var propWhere = "";
            bool atLeastOnePropertyIsFound = false;
            for (int i = 0; i < _parameters.Count; i++)
            {
                var polProperty = m_policyDto.policy_property.FirstOrDefault(w => (int)w.property_id == Convert.ToInt32(_parameters[i]));
                if (polProperty != null && polProperty.the_value != null && polProperty.the_value.ToString() != "")
                {
                    propWhere = " AND (OB_OBJECT_PROPERTY.PROPERTY_ID = " + Convert.ToInt32(_parameters[i]) +
                                " AND THE_VALUE = '" + polProperty.the_value.ToString() + "' )";

                    //TODO - HAMZA 15/09/2023 DEVIRIS5-12241 _ Add ALIAS
                    szSql +=
                        " AND UW_POLICY.ID IN " +
                        " ( " +
                        " SELECT tempUwPol" + i + ".ID " +
                        " FROM UW_POLICY as tempUwPol" + i + " " +
                        " LEFT JOIN UW_POLICY_PROPERTY ON tempUwPol" + i + ".ID = UW_POLICY_PROPERTY.POLICY_ID " +
                        " LEFT JOIN OB_OBJECT_PROPERTY ON UW_POLICY_PROPERTY.OBJECT_PROPERTY_ID = OB_OBJECT_PROPERTY.ID " +
                        " LEFT JOIN UW_ROOT ON tempUwPol" + i + ".ROOT_ID = UW_ROOT.ID " +
                        " WHERE tempUwPol" + i + ".DATE_EXPIRY >= '" + szEffective + "'" +
                        " AND tempUwPol" + i + ".CONTRACT_TYPE_ID IN (0,1,11,10)  " +
                        " AND IS_GROUP = 0   " +
                        " AND tempUwPol" + i + ".IS_DRAFT = 0  " +
                        " AND tempUwPol" + i + ".ID <> " + m_policyDto.policy.id +
                        " AND tempUwPol" + i + ".ROOT_ID NOT IN (SELECT P.ROOT_ID FROM UW_POLICY P WHERE P.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Endorsement +
                        " AND P.END_TYPE = 'C' AND P.ROOT_ID = tempUwPol" + i + ".ROOT_ID) " +
                        propWhere +
                        " )";

                    szSqlCert +=
                        " AND UW_POLICY.ID IN" +
                        " ( " +
                        " SELECT tempUwPolCert" + i + ".ID " +
                        " FROM UW_POLICY as tempUwPolCert" + i + " " +
                        " LEFT JOIN UW_POLICY_PROPERTY ON tempUwPolCert" + i + ".ID = UW_POLICY_PROPERTY.POLICY_ID " +
                        " LEFT JOIN OB_OBJECT_PROPERTY ON UW_POLICY_PROPERTY.OBJECT_PROPERTY_ID = OB_OBJECT_PROPERTY.ID " +
                        " LEFT JOIN UW_POLICY ParentPolicy ON tempUwPolCert" + i + ".PARENT_POLICY_ID = ParentPolicy.ID  " +
                        " LEFT JOIN UW_ROOT ON tempUwPolCert" + i + ".ROOT_ID = UW_ROOT.ID " +
                        " WHERE tempUwPolCert" + i + ".DATE_EXPIRY >= '" + szEffective + "'" +
                        " AND tempUwPolCert" + i + ".IS_DRAFT = 0  " +
                        " AND tempUwPolCert" + i + ".CONTRACT_TYPE_ID IN (2)  " +
                        " AND ParentPolicy.CONTRACT_TYPE_ID in (0,1,11,10) " +
                        " AND IS_GROUP = 1 " +
                        " AND Parentpolicy.IS_DRAFT = 0 " +
                        " AND tempUwPolCert" + i + ".ID <> " + m_policyDto.policy.id +
                        " AND tempUwPolCert" + i + ".CERTIF_NO NOT IN (SELECT CERTIF_NO FROM UW_POLICY p WHERE P.ROOT_ID = tempUwPolCert" + i + ".ROOT_ID" +
                        " AND P.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate + " AND P.CERTIF_FLAG = 'D')" +
                        propWhere +
                        " )";
                    //END TODO - DEVIRIS5-12241
                }
            }
            if (atLeastOnePropertyIsFound)
            {
                szSql += szSqlCert;

                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    var result = dbConn.Query<string>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);

                    if (result != null && result.Count() > 0)
                    {
                        foreach (var item in result)
                        {
                            _infoMsg += item + Environment.NewLine;
                        }
                        blResult = true;
                    }
                }
            }
            else
            {
                blResult = false;
            }

            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }

