        private string FnNumberOfPreviousPolicies()
        {
            var szSql =
                " SELECT " +
                " COUNT(*) AS iCount " +
                " FROM UW_POLICY " +
                " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                " WHERE UW_ROOT.LOB_ID = " + m_policyDto.root.lob_id +
                " AND UW_POLICY.INSURED_ID = " + m_policyDto.policy.insured_id +
                " AND (UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Policy +
                " OR (UW_POLICY.CONTRACT_TYPE_ID IN (" + (int)Enums.ContractType.Certificate + "," + (int)Enums.ContractType.AccountableCertificate + ") AND UW_POLICY.CERTIF_FLAG = 'A') " +
                " OR UW_POLICY.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.RenewalEnd + " ) " +
                " AND UW_POLICY.POLICY_NO <> '" + ((m_policyDto.policy.policy_no != null) ? m_policyDto.policy.policy_no : "") + "'";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.QueryFirstOrDefault<int?>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                if (result != null && result > 0)
                {
                    return "Convert.ToInt32(\"" + result.ToString() + "\")" + " ";
                }
                else
                {
                    return " ";
                }
            }
        }

