        private string FnIsLinkedToActivePolicy()
        {
            bool blResult = false;

            if (m_policyDto.policy.linked_policy_id != null) // giorgio 26-mar-2026 BNK-534 - added if statement
            {
                var szSql =
                    "SELECT " +
                    "UW_POLICY.POLICY_NO, " +
                    "UW_POLICY.CERTIF_NO, " +
                    "UW_POLICY.CONTRACT_TYPE_ID, " +
                    "UW_POLICY.DATE_EFFECTIVE " +
                    "FROM UW_POLICY " +
                    "WHERE UW_POLICY.ID = " + m_policyDto.policy.linked_policy_id;

                Structures.PolicyStatusInfo policyStatusInfo = new Structures.PolicyStatusInfo();

                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    var result = dbConn.Query(szSql, commandTimeout: 1200).ToList();

                    if (result != null && result.Count > 0)
                    {
                        foreach (var row in result)
                        {
                            var rowfields = row as IDictionary<string, object>;

                            if (rowfields["CERTIF_NO"] != null)
                            {
                                policyStatusInfo = uWHelper.PolicyStatusInfo(connStr, m_company_id,
                                                                            rowfields["POLICY_NO"].ToString(),
                                                                            rowfields["CERTIF_NO"].ToString(),
                                                                            (Enums.ContractType)rowfields["CONTRACT_TYPE_ID"],
                                                                            m_policyDto.root.lob_id,
                                                                            (DateTime)rowfields["DATE_EFFECTIVE"],
                                                                            m_policyDto.policy.date_effective);
                            }
                            else
                            {
                                policyStatusInfo = uWHelper.PolicyStatusInfo(connStr, m_company_id,
                                                                            rowfields["POLICY_NO"].ToString(),
                                                                            "",
                                                                            (Enums.ContractType)rowfields["CONTRACT_TYPE_ID"],
                                                                            m_policyDto.root.lob_id,
                                                                            (DateTime)rowfields["DATE_EFFECTIVE"],
                                                                            m_policyDto.policy.date_effective);
                            }

                            if (policyStatusInfo.is_canceled == false && policyStatusInfo.is_suspended == false)
                            {
                                blResult = true;
                            }
                        }
                    }
                }
            }

            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }

