                " AND ((UW_POLICY.DATE_EFFECTIVE >= '" + szEffective + "' " +
                " AND UW_POLICY.DATE_EFFECTIVE < '" + szExpiry + "')" +
                " OR (UW_POLICY.DATE_EXPIRY > '" + szEffective + "' " +
                " AND UW_POLICY.DATE_EXPIRY <= '" + szExpiry + "')) " +
                " AND UW_POLICY.IS_DRAFT = 0 " +
                " AND UW_POLICY.POLICY_NO <> '" + ((m_policyDto.policy.policy_no != null) ? m_policyDto.policy.policy_no : "") + "' ";

            Structures.PolicyStatusInfo policyStatusInfo = new Structures.PolicyStatusInfo();

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).ToList();

                if (result != null && result.Count > 0)
                {
                    foreach (var row in result)
                    {
                        var rowfields = row as IDictionary<string, object>;

                        if (rowfields["CERTIF_NO"] != null)
