                            policyStatusInfo = uWHelper.PolicyStatusInfo(connStr, m_company_id,
                                                                        rowfields["POLICY_NO"].ToString(),
                                                                        rowfields["CERTIF_NO"].ToString(),
                                                                        (Enums.ContractType)rowfields["CONTRACT_TYPE_ID"],
                                                                        m_policyDto.root.lob_id,
                                                                        (DateTime)rowfields["DATE_EFFECTIVE"],
                                                                        m_policyDto.policy.date_effective);
                        }
                        else
                        {
                            policyStatusInfo = uWHelper.PolicyStatusInfo(connStr, m_company_id,
                                                                        rowfields["POLICY_NO"].ToString(),
                                                                        "",
                                                                        (Enums.ContractType)rowfields["CONTRACT_TYPE_ID"],
                                                                        m_policyDto.root.lob_id,
                                                                        (DateTime)rowfields["DATE_EFFECTIVE"],
                                                                        m_policyDto.policy.date_effective);
                        }

                        if (policyStatusInfo.is_canceled == false && policyStatusInfo.is_suspended == false)
                        {
                            iCount += 1;
                        }
                    }
                }
            }

            return "Convert.ToInt32(\"" + iCount + "\")" + " ";
        }

