        private string FnNumberOfActivePoliciesForTheSamePayrollID()
        {
            int iCount = 0;

            string szEffective = m_policyDto.policy.date_effective.ToString("yyyy/MM/dd");
            string szExpiry = Convert.ToDateTime(m_policyDto.policy.date_expiry).ToString("yyyy/MM/dd");
            string szAsAt = DateTime.Today.ToString("yyyy/MM/dd");

            var szSql =
                " WITH tmp AS (" +
                " SELECT PF_PROFILE_RELATION.PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +
                " WHERE RELATION_ID = 35 " +
                " AND IS_INACTIVE = 0 " +
                " AND PF_PROFILE_RELATION.PROFILE_ID = " + m_policyDto.policy.insured_id +
                " " +
                " UNION ALL " +
                " SELECT DISTINCT PF_PROFILE_RELATION.PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +

                // giorgio 26-mar-2026 BNK-534
                //" LEFT JOIN PF_RELATION ON PF_PROFILE_RELATION.RELATION_ID = PF_RELATION.RELATION_ID " +
                " LEFT JOIN PF_RELATION ON PF_PROFILE_RELATION.RELATION_ID = PF_RELATION.ID " +

                " WHERE MAIN_PROFILE_ID IN " +
                " (SELECT PF_PROFILE_RELATION.PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +
                " WHERE PF_PROFILE_RELATION.RELATION_ID = 35 " +
                " AND PF_PROFILE_RELATION.IS_INACTIVE = 0 ) " +
                " AND PF_RELATION.RELATION_GROUP_ID = 2 " +
                " AND MAIN_PROFILE_ID = " + m_policyDto.policy.insured_id +
                " " +
                " UNION ALL " +
                " SELECT PF_PROFILE_RELATION.PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +
                " WHERE RELATION_ID = 35 " +
                " AND IS_INACTIVE = 0 " +
                " AND PF_PROFILE_RELATION.PROFILE_ID IN " +
