                " AND MAIN_PROFILE_ID IN " +
                " (SELECT PF_PROFILE_RELATION.PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +
                " WHERE PF_PROFILE_RELATION.RELATION_ID = 35 " +
                " AND IS_INACTIVE = 0) " +
                " AND PF_RELATION.RELATION_GROUP_ID = 2 ) " +
                " " +
                " UNION ALL " +
                " SELECT DISTINCT PF_PROFILE_RELATION.PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +

                // giorgio 26-mar-2026 BNK-534
                //" LEFT JOIN PF_RELATION ON PF_PROFILE_RELATION.RELATION_ID = PF_RELATION.RELATION_ID " +
