                " (SELECT PF_PROFILE_RELATION.PROFILE_ID " + " FROM PF_PROFILE_RELATION " +
                " WHERE PF_PROFILE_RELATION.RELATION_ID = 35 " +
                " AND PF_PROFILE_RELATION.IS_INACTIVE = 0 ) " +
                " AND PF_RELATION.RELATION_GROUP_ID = 2 " +
                " AND MAIN_PROFILE_ID IN (SELECT TOP 1 PF_PROFILE_RELATION.MAIN_PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +

                // giorgio 26-mar-2026 BNK-534
                //" LEFT JOIN PF_RELATION ON PF_PROFILE_RELATION.RELATION_ID = PF_RELATION.RELATION_ID " +
                " LEFT JOIN PF_RELATION ON PF_PROFILE_RELATION.RELATION_ID = PF_RELATION.ID " +

                " AND RELATION_GROUP_ID = 2 " +
                " WHERE PF_PROFILE_RELATION.PROFILE_ID = " + m_policyDto.policy.insured_id +
                " AND MAIN_PROFILE_ID IN " +
                " (SELECT PF_PROFILE_RELATION.PROFILE_ID " +
                " FROM PF_PROFILE_RELATION " +
                " WHERE PF_PROFILE_RELATION.RELATION_ID = 35 " +
                " AND IS_INACTIVE = 0) " +
                " AND PF_RELATION.RELATION_GROUP_ID = 2 ) " +
                " ) " +
                " SELECT UW_POLICY.POLICY_NO, " +
                " UW_POLICY.CERTIF_NO, " +
                " UW_POLICY.CONTRACT_TYPE_ID, " +
                " UW_POLICY.DATE_EFFECTIVE " +
                " FROM UW_POLICY  " +
                " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                " WHERE UW_POLICY.CONTRACT_TYPE_ID IN (0,1,11) " +
                " AND IS_GROUP = 0  " +
                " AND UW_POLICY.IS_DRAFT = 0  " +
                " AND UW_POLICY.DATE_EXPIRY > = '" + szAsAt + "' " +
                " AND UW_POLICY.PROD_ID IN (SELECT ID FROM UW_PROD WHERE IS_INCLUDED_IN_EMP_FLEET_COUNT = 1) " +

                // giorgio 27-mar-2026 BNK-534
                //" AND UW_POLICY.INSURED_ID IN (SELECT PF_PROFILE_RELATION.PROFILE_ID FROM tmp) " +
                " AND UW_POLICY.INSURED_ID IN (SELECT tmp.PROFILE_ID FROM tmp) " +

                " AND UW_POLICY.ROOT_ID NOT IN (SELECT P.ROOT_ID FROM UW_POLICY P WHERE P.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Endorsement +
                " AND " +
                " P.END_TYPE = 'C' AND P.ROOT_ID = UW_POLICY.ROOT_ID) " +
                " " +
                " UNION ALL " +
                " SELECT  " +
                " UW_POLICY.POLICY_NO, " +
                " UW_POLICY.CERTIF_NO, " +
                " UW_POLICY.CONTRACT_TYPE_ID, " +
                " UW_POLICY.DATE_EFFECTIVE " +
                " FROM UW_POLICY  " +
                " LEFT JOIN UW_ROOT ON UW_POLICY.ROOT_ID = UW_ROOT.ID " +
                " LEFT JOIN UW_POLICY ParentPolicy ON UW_POLICY.PARENT_POLICY_ID = ParentPolicy.ID " +
                " WHERE UW_POLICY.CONTRACT_TYPE_ID IN (2) " +
                " AND ParentPolicy.CONTRACT_TYPE_ID in (0,1,11) " +
                " AND UW_POLICY.DATE_EXPIRY > = '" + szAsAt + "' " +
