                " (SELECT CERTIF_NO FROM UW_POLICY p " +
                " WHERE P.ROOT_ID = UW_POLICY.ROOT_ID" +
                " AND P.CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                " AND P.CERTIF_FLAG = 'D')";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).ToList();
                if (result != null && result.Count > 0)
                {
                    foreach (var row in result)
                    {
                        //If Not IsDBNull(oDReader("CERTIF_NO")) Then
                        //    policyStatusInfo = UWHelper.PolicyStatusInfo(oDReader("POLICY_NO"), _
