                        //    iCount += 1
                        //End 
                        iCount += 1;
                    }
                }
            }

            return "Convert.ToInt32(\"" + iCount + "\")" + " ";
        }

        private string FnExistClaimBeforeEffectiveDate()
        {
            bool blResult = false;

            var szSql =
                " SELECT " +
                " COUNT(*) AS iCount " +
                " FROM CL_CLAIM " +
                " WHERE CL_CLAIM.POLICY_ID = " + m_ACCT_parent_policy_id;

            if (GlobalVariables.DbType == "SQLSERVER")
            {
                szSql += " AND CL_CLAIM.OCCURRENCE_DATE <= '" + m_policyDto.policy.date_effective.ToString("yyy/MM/dd") + "' ";
            }
            else
            {
                szSql += " AND TO_CHAR(CL_CLAIM.OCCURRENCE_DATE,'YYYY/MM/DD') <= '" + m_policyDto.policy.date_effective.ToString("yyy/MM/dd") + "' ";
            }

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.QueryFirstOrDefault<int?>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200);
                if (result != null && result > 0)
                {
                    blResult = true;
                }
            }

            return "Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\"))" + " ";
        }

