        private string FnLeastPeriodBetweenTwoOccurrenceClaimsPerCover(ArrayList _parameters)
        {
            int iPeriod = 0;

            var szSql =
                " SELECT " +
                " ID, " +
                " OCCURRENCE_DATE " +
                " FROM CL_CLAIM " +
                " WHERE CL_CLAIM.POLICY_ID = " + m_ACCT_parent_policy_id +
                " AND CL_CLAIM.ID IN (SELECT CLAIM_ID FROM CL_CLAIM_ASSESSMENT WHERE COVER_ID = " + _parameters[0] + ") " +
                " ORDER BY OCCURRENCE_DATE ";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                //AN 2028-08-27
                var coreOption = dbConn.QueryFirstOrDefault<CORE_OPTION>("SELECT TOP 1 * FROM CORE_OPTION");
                int daysDiffIncludeLastDate = coreOption.days_diff_include_last_day;
                //AN 2028-08-27

                var result = dbConn.Query(szSql, commandTimeout: 1200).ToList();
                if (result != null)
                {
                    if (result.Count < 2)
                    {
                        return "Convert.ToInt32(\"" + 0 + "\")" + " ";
                    }

                    for (int i = 0; i < result.Count; i++)
                    {
                        if (i != result.Count - 1)
                        {
                            var rowfields = result[i] as IDictionary<string, object>;
                            var rowfields2 = result[i + 1] as IDictionary<string, object>;

                            if (iPeriod == 0)
                            {
                                iPeriod = (int)Pixel.Core.Lib.DateExt.DateDiff(Pixel.Core.Lib.DateInterval.Day,
                                                                               Convert.ToDateTime(rowfields["OCCURRENCE_DATE"]),
                                                                               Convert.ToDateTime(rowfields2["OCCURRENCE_DATE"]),
                                                                               daysDiffIncludeLastDate);
                            }
                            else if (Pixel.Core.Lib.DateExt.DateDiff(Pixel.Core.Lib.DateInterval.Day,
                                                                     Convert.ToDateTime(rowfields["OCCURRENCE_DATE"]),
                                                                     Convert.ToDateTime(rowfields2["OCCURRENCE_DATE"]),
                                                                     daysDiffIncludeLastDate) < iPeriod)
                            {
                                iPeriod = (int)Pixel.Core.Lib.DateExt.DateDiff(Pixel.Core.Lib.DateInterval.Day,
                                                                               Convert.ToDateTime(rowfields["OCCURRENCE_DATE"]),
                                                                               Convert.ToDateTime(rowfields2["OCCURRENCE_DATE"]),
                                                                               daysDiffIncludeLastDate);
                            }
                        }
                    }
                }
            }

            return "Convert.ToInt32(\"" + iPeriod + "\")" + " ";
        }

