        private string FnHigherApprovedDischargeDateByAssessmentType(ArrayList _parameters, bool _UseAsParameter)
        {
            var szSql =
                "SELECT " +
                " TOP 1 VISA_APPROVED_DISCHARGE_DATE " +
                " FROM CL_CLAIM_ASSESSMENT " +
                " LEFT JOIN CL_CLAIM ON CL_CLAIM_ASSESSMENT.CLAIM_ID = CL_CLAIM.ID " +
                " WHERE CL_CLAIM.POLICY_ID = " + m_ACCT_parent_policy_id +
                " AND CL_CLAIM.ID IN (SELECT CLAIM_ID FROM CL_CLAIM_ASSESSMENT WHERE ASSESSMENT_TYPE_ID = " + _parameters[0] + ") " +
                " ORDER BY VISA_APPROVED_DISCHARGE_DATE DESC ";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();
                if (result != null && result.Count > 0)
                {
                    var rowfields = result as IDictionary<string, object>;

                    if (Pixel.Core.Lib.CoreHelper.IsDate(rowfields["VISA_APPROVED_DISCHARGE_DATE"]))
                    {
                        if (_UseAsParameter)
                        {
                            return rowfields["VISA_APPROVED_DISCHARGE_DATE"].ToString();
                        }
                        else
                        {
                            return "Convert.ToDateTime(\"" + rowfields["VISA_APPROVED_DISCHARGE_DATE"] + "\")" + " ";
                        }
                    }
                    else
                    {
                        return "-1";
                    }
                }
                else
                {
                    return "-1";
                }
            }

        }

