                " AND CL_CLAIM.ID IN (SELECT CLAIM_ID FROM CL_CLAIM_ASSESSMENT WHERE ASSESSMENT_TYPE_ID = " + _parameters[0] +
                " AND VISA_ACTUAL_DISCHARGE_DATE IS NULL ) ";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSQL, commandTimeout: 1200).ToList();
                if (result != null && result.Count > 0)
                {
                    blResult = true;
                }
            }

            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }

