        private string FnNumberOfAdherentsInPreviousPolicyAtEffectiveDate()
        {
            int iCount = 0;

            ArrayList oArrayList = new ArrayList();
            oArrayList.Add("DimensionPolicy");
            oArrayList.Add("DateEffective");

            string m_Effective = this.FnOldValue(oArrayList, false);

            m_Effective = m_Effective.Replace("\"", "");
            m_Effective = m_Effective.Replace("Convert.ToDateTime", "");
            m_Effective = m_Effective.Replace("(", "");
            m_Effective = m_Effective.Replace(")", "");

            if (Pixel.Core.Lib.CoreHelper.IsDate(m_Effective))
            {
                m_Effective = Convert.ToDateTime(m_Effective).ToString("yyyy/MM/dd");

                //12-NOV-2023
                //iCount = uWHelper.GetCertificatesFinalCount(connectionSQL, this.m_ACCT_parent_root_id, m_Effective);
                iCount = this.GetCertificatesFinalCount(connStr, this.m_ACCT_parent_root_id, m_Effective);
            }

            return "Convert.ToInt32(\"" + iCount + "\")" + " ";
        }

