                 " FROM UW_POLICY " +
                 " WHERE UW_POLICY.PARENT_POLICY_ID = " + this.m_ACCT_parent_policy_id +
                 " AND UW_POLICY.CERTIF_NO = '" + this.m_ACCT_parent_certif_no + "' " +
                 " AND UW_POLICY.CERTIF_FLAG = 'A' ";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();
                if (result != null && result.Count > 0)
                {
                    var rowfields = result as IDictionary<string, object>;

                    if (uWHelper.IsCertificateOnBlackList(connStr, Convert.ToInt32(rowfields["ID"])))
                    {
                        blResult = true;
                    }
                }
                else
                {
                    return "Convert.ToString(\"" + -1 + "\")" + " ";
                }
            }

            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }

