        private string FnScoreOf(ArrayList _parameters)
        {
            decimal nScore = 0M;
            for (int i = 0; i < m_policyDto.policy_question.Count; i++)
            {
                if (m_policyDto.policy_question.ElementAt(i).question_id == Convert.ToInt32(_parameters[0]))
                {
                    if (m_policyDto.policy_question.ElementAt(i).score != null)
                    {
                        nScore = Convert.ToDecimal(m_policyDto.policy_question.ElementAt(i).score);
                    }
                    break;
                }
            }

            return "Convert.ToDecimal(\"" + nScore + "\")" + " ";
        }

        private string FnDiseaseOf(ArrayList _parameters)
        {
            bool blResult = false;

            var szSql =
                "SELECT " +
                "DISEASE_CODE " +
                "FROM UW_DISEASE " +
                " WHERE ID = " + _parameters[1];

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();
                if (result != null && result.Count > 1)
                {
                    var rowfields = result as IDictionary<string, object>;

                    for (int i = 0; i < m_policyDto.policy_question.Count; i++)
                    {
                        if (m_policyDto.policy_question.ElementAt(i).question_id == Convert.ToInt32(_parameters[0]) &&
                            m_policyDto.policy_question.ElementAt(i).disease_id != null &&
                            (m_policyDto.policy_question.ElementAt(i).disease_id == Convert.ToInt32(_parameters[1]) ||
                            m_policyDto.policy_question.ElementAt(i).disease_code.ToString().StartsWith(rowfields["DISEASE_CODE"].ToString())))
                        {
                            if (m_policyDto.policy_question.ElementAt(i).score != null)
                            {
                                blResult = true;
                            }
                            break;
                        }
                    }
                }
            }

            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }

        private string FnOSClaims()
        {
            decimal nOS = 0M;

            if (this.m_ListClaimOS == null || this.m_ListClaimOS.Count == 0)
            {
                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    // var _cl_os_based_on_po = System.Convert.ToBoolean(dbConn.QueryFirstOrDefault<int>("SELECT CL_OS_BASED_ON_PO FROM CORE_AD"));
                    var ad = dbConn.QueryFirstOrDefault<CORE_AD>("SELECT * FROM CORE_AD");
                    var _cl_os_based_on_po = System.Convert.ToBoolean(ad.cl_os_based_on_po);
                    var _cl_os_uses_claimed_amt = System.Convert.ToBoolean(ad.cl_os_uses_claimed_amt);

                    var whereOS = " WHERE UW_POLICY.ID = " + this.m_ACCT_parent_policy_id;

                    PncOSClaimHelper pncOSClmHler = new PncOSClaimHelper();
                    var resultOS = pncOSClmHler.GetOSClaims(connStr, "reserve", whereOS, "", DateTime.Today.ToString("yyyy/MM/dd"), _cl_os_based_on_po, _cl_os_uses_claimed_amt);

                    if (resultOS.Count > 0)
                    {
                        foreach (var row in resultOS)
                        {
                            this.FillListClaimOS(row);

                            nOS += row.os_amt / row.counter_cur_rate;
                        }
                    }
                }
            }
            else
            {
                for (int i = 0; i < m_ListClaimOS.Count; i++)
                {
                    nOS += m_ListClaimOS.ElementAt(i).os_amt / m_ListClaimOS.ElementAt(i).counter_cur_rate;
                }
            }

            if (nOS > 0M)
            {
                return "Convert.ToDecimal(\"" + nOS + "\")" + " ";
            }
            else
            {
                return "Convert.ToDecimal(\"" + 0 + "\")" + " ";
                //return "0";
            }
        }

