        private void FillListClaimOS(PncClaimOSQry row)
        {
            this.m_ListClaimOS.Add(new PncClaimOSQry
            {
                assessment_id = row.assessment_id,
                cover_id = row.cover_id,
                os_amt = row.os_amt,
                counter_cur_rate = row.counter_cur_rate,
            });
        }

