        private string FnOSClaimByFinalDisease(ArrayList _parameters)
        {
            decimal nOS = 0M;

            if ((this.m_ListClaimOS == null) || this.m_ListClaimOS.Count == 0)
            {
                m_ListClaimOS.Clear();

                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    //var _cl_os_based_on_po = System.Convert.ToBoolean(dbConn.QueryFirstOrDefault<int>("SELECT CL_OS_BASED_ON_PO FROM CORE_AD"));
                    var ad = dbConn.QueryFirstOrDefault<CORE_AD>("SELECT * FROM CORE_AD");
                    var _cl_os_based_on_po = System.Convert.ToBoolean(ad.cl_os_based_on_po);
                    var _cl_os_uses_claimed_amt = System.Convert.ToBoolean(ad.cl_os_uses_claimed_amt);

                    var whereOS = " WHERE UW_POLICY.ID = " + this.m_ACCT_parent_policy_id;

                    PncOSClaimHelper pncOSClmHler = new PncOSClaimHelper();
                    var resultOS = pncOSClmHler.GetOSClaims(connStr, "reserve", whereOS, "", DateTime.Today.ToString("yyyy/MM/dd"), _cl_os_based_on_po, _cl_os_uses_claimed_amt);

                    if (resultOS != null && resultOS.Count > 0)
                    {
                        var szSqlDisease =
                               " SELECT " +
                               " DISEASE_CODE " +
                               " FROM UW_DISEASE " +
                               " WHERE ID = " + _parameters[0];

                        var diseaseCode = dbConn.QueryFirstOrDefault<string>(szSqlDisease, commandTimeout: 1200);
                        if (diseaseCode != null)
                        {
                            foreach (var row in resultOS)
                            {
                                var szSqlFinal =
                                    " SELECT " +
                                    " TOP 1 ID " +
                                    " FROM CL_CLAIM_ASSESSMENT_F_DISEASE " +
                                    " LEFT JOIN UW_DISEASE ON CL_CLAIM_ASSESSMENT_F_DISEASE.FINAL_DISEASE_ID = UW_DISEASE.ID " +
                                    " WHERE CL_CLAIM_ASSESSMENT.ID = " + row.assessment_id +
                                    " AND UW_DISEASE.DISEASE_CODE LIKE '" + diseaseCode + "%'";

                                var resultFinal = dbConn.QueryFirstOrDefault<int?>(szSqlFinal, commandTimeout: 1200);
                                if (resultFinal != null)
                                {
                                    nOS += row.os_amt / row.counter_cur_rate;
                                }
                            }
                        }
                    }
                }
            }
            else
            {
                var szSqlDisease =
                              " SELECT " +
                              " DISEASE_CODE " +
                              " FROM UW_DISEASE " +
                              " WHERE ID = " + _parameters[0];

                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = connStr;
                    dbConn.Open();

                    var resultDisease = dbConn.Query(szSqlDisease, commandTimeout: 1200).FirstOrDefault();
                    if (resultDisease != null)
                    {
                        var rowfieldsDisease = resultDisease as IDictionary<string, object>;

                        for (int i = 0; i < m_ListClaimOS.Count; i++)
                        {
                            var szSqlFinal =
                                " SELECT " +
                                " TOP 1 ID " +
                                " FROM CL_CLAIM_ASSESSMENT_F_DISEASE " +
                                " LEFT JOIN UW_DISEASE ON CL_CLAIM_ASSESSMENT_F_DISEASE.FINAL_DISEASE_ID = UW_DISEASE.ID " +
                                " WHERE CL_CLAIM_ASSESSMENT.ID = " + m_ListClaimOS.ElementAt(i).assessment_id +
                                " AND UW_DISEASE.DISEASE_CODE LIKE '" + rowfieldsDisease["DISEASE_CODE"] + "%'";

                            var resultFinal = dbConn.Query(szSqlFinal, commandTimeout: 1200).FirstOrDefault();
                            if (resultFinal != null)
                            {
                                nOS += m_ListClaimOS.ElementAt(i).os_amt / m_ListClaimOS.ElementAt(i).counter_cur_rate;
