                        //"       AND CL_CLAIM_ASSESSMENT.IS_CANCELLATION = 1 AND CL_CLAIM_ASSESSMENT.IS_RECOVERY = 0 )) " +
                    }

                    if (GlobalVariables.DbType == "ORACLE")
                    {
                        szSql = szSql.Replace("ISNULL", "NVL");
                        szSql = szSql.Replace("DBO.", "");
                    }

                    var result = dbConn.Query<decimal>(Pixel.Core.Dapper.My.AddIsolationRU(szSql), commandTimeout: 1200).ToList();
                    if (result != null)
                    {
                        foreach (var paidAmt in result)
                        {
                            //var rowfields = row as IDictionary<string, object>;
                            //nPaid += (Convert.ToBoolean(rowfields["IS_CANCELLATION"]) == true ? -Convert.ToDecimal(rowfields["PAID_AMT"]) : Convert.ToDecimal(rowfields["PAID_AMT"]));
                            nPaid += paidAmt;
                        }

                        this.m_PaidClaims = nPaid;

                        return "Convert.ToDecimal(\"" + nPaid + "\")" + " ";
                    }
                    else
                    {
                        return "Convert.ToDecimal(\"" + 0 + "\")" + " ";
                    }
                }
            }
        }

