        private string FnCoInsuranceByCover(ArrayList _parameters)
        {
            string szCoInsurance = "";

            for (int i = 0; i < m_policyDto.policy_cover.Count; i++)
            {
                if (m_policyDto.policy_cover.ElementAt(i).cover_id == Convert.ToInt32(_parameters[0]))
                {
                    var szSql =
                        "SELECT " +
                        "COINS_DESC " +
                        "FROM UW_COINS " +
                        " WHERE ID = " + m_policyDto.policy_cover.ElementAt(i).co_ins_id;

                    using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                    {
                        dbConn.ConnectionString = connStr;
                        dbConn.Open();

                        var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();
                        if (result != null && result.Count > 0)
                        {
                            var rowfields = result as IDictionary<string, object>;

                            szCoInsurance = rowfields["COINS_DESC"].ToString();

                            break;
                        }
                    }
                }
            }

            return "\"" + szCoInsurance + "\"" + " ";
        }

