        public string FnPolicyHolderTagInclude(ArrayList _parameters)
        {
            bool blResult = false;

            string query = " SELECT TAG_ID FROM PF_PROFILE_TAG WHERE PROFILE_ID = @PROFILE_ID";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = connStr;
                dbConn.Open();

                var result = dbConn.Query<int>(query, new { PROFILE_ID = m_policyDto.policy.holder_id });
                foreach (var tag in result)
                {
                    if (tag == Convert.ToInt32(_parameters[0]))
                    {
                        blResult = true;
                        break;
                    }
                }
            }
            return "Math.Abs(Convert.ToInt32(Convert.ToBoolean(\"" + blResult + "\")))" + " ";
        }
