        private string FnPolicyCoverPremium(ArrayList _parameters)
        {
            decimal nTotal = 0M;
            bool blFound = false;

            for (int i = 0; i < this.m_policyDto.policy_cover.Count; i++)
            {
                if (this.m_policyDto.policy_cover.ElementAt(i).cover_id == Convert.ToInt32(_parameters[0]))
                {

                    blFound = true;

                    if (this.m_policyDto.policy.prod_id != null)
                    {
                        if (this.m_policyDto.policy.is_cover_rate_on_net == 1)
                        {
                            nTotal = this.m_policyDto.policy_cover.ElementAt(i).net_premium;
                        }
                        else
                        {
                            nTotal = this.m_policyDto.policy_cover.ElementAt(i).total_premium;
                        }

                        if (m_policyDto.policy.premium_cur_id == m_baseCurId)
                        {
                            nTotal = Helper.ConvertAmount(connStr, nTotal, m_policyDto.policy.premium_cur_id, this.m_policyDto.policy.date_issue, m_counterCurId, 2);
                        }
                        else if (m_policyDto.policy.premium_cur_id == m_counterCurId)
                        {
                            // AN 2026-03-25
                            // nothing TODO !!!!!
                        }
                        else
                        {
                            nTotal = Helper.ConvertAmount(connStr, nTotal, m_policyDto.policy.premium_cur_id, this.m_policyDto.policy.date_issue, m_counterCurId, 2);
                        }
                        break;
                    }
                    else
                    {
                        return "-1";
                    }
                }
            }

            if (blFound == true)
            {
                return "CDec(\"" + nTotal + "\")" + " ";
            }
            else
            {
                return "-1";
            }

        }

