        // used in business rule
        public decimal GetPolicyUnpaidDueBalance(string _connectionSQL, int _rootId, int _closeOnNet, DateTime _asAt)
        {
            decimal balance = 0M;
            try
            {
                using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
                {
                    dbConn.ConnectionString = _connectionSQL;
                    dbConn.Open();

                    var strQuery =
                        " SELECT" +
                        "   SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT.AMOUNT ELSE 0 END) AS DEBIT," +
                        "   SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT.AMOUNT ELSE 0 END) AS CREDIT, " +
                        "   SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT.PAID_AMT ELSE 0 END) AS PAID_CREDIT," +
                        "   SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT.PAID_AMT ELSE 0 END) AS PAID_DEBIT" +
                        " FROM RP_MVMT" +
                        " LEFT JOIN UW_POLICY ON RP_MVMT.LINK_ID = UW_POLICY.ID" +
                        " WHERE RP_MVMT.IS_SCHEDULED = 0 " +
                        "     AND LINK_TYPE_ID = 1  " +
                        "     AND UW_POLICY.ROOT_ID = " + _rootId +
                        " AND RP_MVMT.DUE_DATE <= '" + _asAt.ToString("yyyy/MM/dd") + "'" +
                        " GROUP BY UW_POLICY.ROOT_ID" +
                        " UNION ALL " +
                        " SELECT	" +
                        "   SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT_INST.AMOUNT ELSE 0 END) AS DEBIT ," +
                        "   SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT_INST.AMOUNT ELSE 0 END) AS CREDIT, " +
                        "   SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT_INST.PAID_AMT ELSE 0 END) AS PAID_CREDIT," +
                        "   SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT_INST.PAID_AMT ELSE 0 END) AS PAID_DEBIT" +
                        " FROM RP_MVMT_INST" +
                        " LEFT JOIN RP_MVMT ON RP_MVMT_INST.MVMT_ID = RP_MVMT.ID" +
                        " LEFT JOIN UW_POLICY ON RP_MVMT.LINK_ID = UW_POLICY.ID" +
                        " WHERE LINK_TYPE_ID = 1  " +
                        "   AND UW_POLICY.ROOT_ID = " + _rootId +
                        "   AND RP_MVMT_INST.DUE_DATE <= '" + _asAt.ToString("yyyy/MM/dd") + "'" +
                        " GROUP BY UW_POLICY.ROOT_ID" +
                        " UNION ALL " +
                        " SELECT	" +
                        "   SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT.AMOUNT ELSE 0 END) AS DEBIT," +
                        "   SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT.AMOUNT ELSE 0 END) AS CREDIT, " +
                        "   SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT.PAID_AMT ELSE 0 END) AS PAID_CREDIT," +
                        "   SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT.PAID_AMT ELSE 0 END) AS PAID_DEBIT" +
                        " FROM RP_MVMT" +
                        " LEFT JOIN UW_POLICY_COMMISSION ON RP_MVMT.LINK_ID = UW_POLICY_COMMISSION.ID" +
                        " LEFT JOIN UW_POLICY ON UW_POLICY_COMMISSION.POLICY_ID = UW_POLICY.ID" +
                        " WHERE RP_MVMT.IS_SCHEDULED = 0 " +
                        "   AND (" + _closeOnNet + " = 1 AND (LINK_TYPE_ID = 8 OR LINK_TYPE_ID = 10)) " +
                        "   AND UW_POLICY.ROOT_ID = " + _rootId +
                        "   AND RP_MVMT.DUE_DATE <= '" + _asAt.ToString("yyyy/MM/dd") + "'" +
                        " GROUP BY UW_POLICY.ROOT_ID" +
                        " UNION ALL " +
                        " SELECT	" +
                        "         SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT_INST.AMOUNT ELSE 0 END) AS DEBIT," +
                        "         SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT_INST.AMOUNT ELSE 0 END) AS CREDIT, " +
                        "         SUM(CASE WHEN DB_CR ='D' THEN RP_MVMT_INST.PAID_AMT ELSE 0 END) AS PAID_CREDIT," +
                        "         SUM(CASE WHEN DB_CR ='C' THEN RP_MVMT_INST.PAID_AMT ELSE 0 END) AS PAID_DEBIT" +
                        " FROM RP_MVMT_INST" +
                        " LEFT JOIN RP_MVMT ON RP_MVMT_INST.MVMT_ID = RP_MVMT_INST.ID" +
                        " LEFT JOIN UW_POLICY_COMMISSION ON RP_MVMT.LINK_ID = UW_POLICY_COMMISSION.ID" +
                        " LEFT JOIN UW_POLICY ON UW_POLICY_COMMISSION.POLICY_ID = UW_POLICY.ID" +
                        " WHERE UW_POLICY.ROOT_ID = " + _rootId +
                        " AND(" + _closeOnNet + " = 1 AND (LINK_TYPE_ID = 8 OR LINK_TYPE_ID = 10)) " +
                        " AND RP_MVMT_INST.DUE_DATE <= '" + _asAt.ToString("yyyy/MM/dd") + "'" +
                        " GROUP BY UW_POLICY.ROOT_ID";

                    //-- PAID PREMIUM
                    //UNION ALL
                    //SELECT SUM(CASE WHEN GL_TRS_ALLOCAT.DB_CR = 'D' THEN GL_TRS_ALLOCAT.PAID_AMT ELSE 0 END) AS DEBIT, 
                    //    SUM(CASE WHEN GL_TRS_ALLOCAT.DB_CR = 'C' THEN GL_TRS_ALLOCAT.PAID_AMT ELSE 0 END) AS CREDIT 
                    //   FROM GL_TRS_ALLOCAT  
                    // LEFT JOIN GL_TRS ON GL_TRS_ALLOCAT.TRS_ID = GL_TRS.ID
                    // LEFT JOIN GL_JOURNAL_TYPE ON GL_TRS.JOURNAL_TYPE_ID = GL_JOURNAL_TYPE.ID
                    // LEFT JOIN RP_MVMT ON GL_TRS_ALLOCAT.MVMT_ID = RP_MVMT.ID  
                    // LEFT JOIN UW_POLICY ON RP_MVMT.LINK_ID = UW_POLICY.ID
                    //   WHERE LINK_TYPE_ID = 1 
                    // AND UW_POLICY.ROOT_ID = @ROOT_ID
                    //GROUP BY UW_POLICY.ROOT_ID

                    //-- PAID PREMIUM
                    //UNION ALL
                    //SELECT SUM(CASE WHEN GL_TRS_ALLOCAT.DB_CR = 'D' THEN GL_TRS_ALLOCAT.PAID_AMT ELSE 0 END) AS DEBIT, 
                    //    SUM(CASE WHEN GL_TRS_ALLOCAT.DB_CR = 'C' THEN GL_TRS_ALLOCAT.PAID_AMT ELSE 0 END) AS CREDIT 
                    //   FROM GL_TRS_ALLOCAT  
                    // LEFT JOIN GL_TRS ON GL_TRS_ALLOCAT.TRS_ID = GL_TRS.ID
                    // LEFT JOIN GL_JOURNAL_TYPE ON GL_TRS.JOURNAL_TYPE_ID = GL_JOURNAL_TYPE.ID
                    // LEFT JOIN RP_MVMT ON GL_TRS_ALLOCAT.MVMT_ID = RP_MVMT.ID  
                    //    LEFT JOIN UW_POLICY_COMMISSION ON RP_MVMT.LINK_ID = UW_POLICY_COMMISSION.ID
                    // LEFT JOIN UW_POLICY ON UW_POLICY_COMMISSION.POLICY_ID = UW_POLICY.ID
                    //   WHERE (@CLOSE_ON_NET = 1 AND (LINK_TYPE_ID = 1 OR LINK_TYPE_ID = 8 OR LINK_TYPE_ID = 10)) 
                    // AND UW_POLICY.ROOT_ID = @ROOT_ID
                    //GROUP BY UW_POLICY.ROOT_ID";

                    var result = dbConn.Query<DebitCreditDto>(strQuery).ToList();

                    foreach (var item in result)
                    {
                        balance += (item.debit - item.credit) - (item.paid_credit - item.paid_debit);
                    }

                    dbConn.Close();
                }

                return balance;
            }
            catch (Exception ex)
            {
                return balance;
            }
        }

        // moved to business rule
        public int GetCertificatesFinalCount(string _connectionSQL, int _rootId, string _asAt)
        {
            int iCount = 0;

            var szSql =
                " SELECT COUNT(*) AS COUNT" +
                " FROM UW_POLICY " +
                " WHERE ROOT_ID = " + _rootId +
                " AND CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                " AND IS_DRAFT = 0 " +
                " AND FLAG = 'A' " +
                " AND PARENT_POLICY_ID NOT IN (SELECT ID FROM UW_POLICY WHERE CONTRACT_TYPE_ID = 10)" +
                " AND (CERTIF_NO NOT IN (SELECT CERTIF_NO FROM UW_POLICY " +
                "      WHERE ROOT_ID = " + _rootId +
                "      AND IS_DRAFT = 0 " +
                "      AND DATE_EFFECTIVE <= '" + _asAt + "'" +
                "      AND CONTRACT_TYPE_ID = " + (int)Enums.ContractType.Certificate +
                " AND FLAG = 'D'))";

            using (var dbConn = Pixel.Core.Dapper.My.ConnectionFactory())
            {
                dbConn.ConnectionString = _connectionSQL;
                dbConn.Open();

                var result = dbConn.Query(szSql, commandTimeout: 1200).FirstOrDefault();
                if (result != null && result.Count() > 0)
                {
                    var rowfields = result as IDictionary<string, object>;
                    iCount = Convert.ToInt32(rowfields["COUNT"]);
                }

                return iCount;
            }
        }

        #endregion moved from PnC 

